window.HYPE_G5_EMB = {"ar":{"meta":{"kicker":"Galop 5 · الثقافة الفروسية","titre":"الشكائم","sous":"افهمي تأثيراتها واختاريها جيدًا.","duree":"حوالي 20 دقيقة من القراءة","type":"درس نظري","audio":"استماع صوتي","langues":"متوفر باللغات الـ14","retour":"دروس Galop 5","progression":"تقدّم القراءة","sommaire":"فهرس الدرس","photoAVenir":"الصورة قريبًا","agrandir":"تكبير الصورة","fermer":"إغلاق","voirPlus":"عرض التفاصيل","voirMoins":"إخفاء التفاصيل","fonctionnement":"طريقة العمل","caracteristiques":"يجب أن تعرفي","precautions":"احتياطات"},"nav":["لماذا","الأنواع","التشريح","الاختيار","الضبط","حالات خاصة"],"s1":{"num":"01","titre":"لماذا نستخدم الشكيمة؟","paras":["الشكيمة هي القطعة المعدنية أو المصنوعة من مادة لينة التي توضع في فم الحصان وتتصل بالأعنّة. تنقل إلى الحصان أفعال يدكِ: إنها إحدى وسائل التواصل بينكِ وبينه، إلى جانب الساقين والجلسة والصوت.","الاتصال الجيد هو صلة خفيفة ومرنة وثابتة بين يدكِ وفم الحصان. ترافق يدكِ حركة الرقبة، خاصة في المشي والعدو، حتى يجد الحصان في الشكيمة سندًا ثابتًا ومطمئنًا، لا مصدر إزعاج أبدًا.","فم الحصان حساس جدًا. يجب أن يكون كل فعل بالعنان — نصف التوقف، العنان الفاتح، العنان المعاكس — قصيرًا ومدروسًا، ثم يُرخى بمجرد أن يستجيب الحصان. فبالإرخاء في اللحظة المناسبة تكافئ اليد الحصان ويتعلّم."],"retenir":{"titre":"تذكّري","points":["تنقل الشكيمة أفعال اليد: لا تحلّ محل الساقين ولا محل الجلسة.","يجب أن يكون الاتصال خفيفًا ومرنًا ومنتظمًا.","يُرخى فعل العنان بمجرد أن يستجيب الحصان."]}},"s2":{"num":"02","titre":"الأنواع المختلفة من الشكائم","intro":"تُصنَّف الشكائم وفق معيارين رئيسيين: شكل القضيب (الجزء الذي يدخل الفم) وطريقة اتصاله بالأعنّة (حلقات السنافل أو أذرع شكيمة الكبح). المسي بطاقة لاكتشاف التفاصيل.","groupes":[{"titre":"شكائم السنافل: تأثير مباشر","texte":"مع شكيمة السنافل، يؤثر العنان مباشرة على الشكيمة، دون تأثير رافعة: الضغط الذي يشعر به الحصان يوافق شدّ العنان.","cartes":[{"nom":"سنافل ذات الزيتونتين (إيغبات)","court":"الحلقات مثبّتة بالقضيب بواسطة زيتونتين.","fonctionnement":"تمنع الزيتونتان الشكيمة من الدوران والانزلاق: تبقى ثابتة في الفم.","caracteristiques":"لا تقرص زوايا الشفتين. غالبًا ما تُختار للخيول الحساسة أو التي تتعلم الاتصال.","precautions":"تحققي من العرض: الشكيمة الضيقة جدًا تضغط على الشفتين، والعريضة جدًا تنزاح عن المركز."},{"nom":"سنافل ذات الأذرع (فول تشيك)","court":"أذرع عمودية تمتد من الحلقات على جانبي الفم.","fonctionnement":"تضغط الأذرع على جانب الرأس عند استخدام العنان الفاتح وتساعد الحصان على الالتفاف. كما تمنع الشكيمة من الانزلاق داخل الفم.","caracteristiques":"عملية للخيول الصغيرة وللخيول التي يصعب توجيهها.","precautions":"غالبًا ما تُثبَّت الأذرع بأحزمة الخدّين في اللجام بواسطة حلقات جلدية صغيرة، حتى لا تعلق بأي شيء."},{"nom":"سنافل بحلقات D (فيردان)","court":"حلقات ثابتة على شكل حرف « D »، بجانب مستقيم ملاصق للخد.","fonctionnement":"يبقى الجانب المستقيم من الحلقة ملاصقًا للخد: الشكيمة ثابتة ويشعر الحصان بالعنان الفاتح بوضوح.","caracteristiques":"لا تقرص زوايا الشفتين. تُستخدم في الترويض على الأرض المستوية كما في القفز وفي السباقات.","precautions":"كما هو الحال في كل سنافل ذات حلقات ثابتة، يجب أن يكون العرض مضبوطًا."},{"nom":"سنافل بحلقات حرّة","court":"تنزلق الحلقات بحرية في ثقوب القضيب.","fonctionnement":"تتحرك الشكيمة أكثر في الفم، مما يشجع الحصان غالبًا على المضغ والاسترخاء.","caracteristiques":"إنها شكيمة السنافل الأكثر شيوعًا.","precautions":"إذا تآكلت الثقوب أو كانت الشكيمة ضيقة جدًا، قد تقرص الحلقات زوايا الشفتين: افحصيها بانتظام."}]},{"titre":"شكل القضيب","texte":"أيًّا كان نوع الحلقات، فإن شكل القضيب يغيّر طريقة توزّع الضغط داخل الفم.","cartes":[{"nom":"قضيب مستقيم","court":"قضيب من قطعة واحدة، صلب أو لين قليلًا.","fonctionnement":"يتوزع الضغط على اللسان وعلى اللثة الخالية من الأسنان (البارات)، بالتساوي يمينًا ويسارًا.","caracteristiques":"شكيمة ثابتة، غالبًا ما تتوفر من المطاط أو من مادة صناعية لينة.","precautions":"أفعال العنان الواحد أقل دقة مقارنة بالقضيب المفصلي."},{"nom":"مفصل واحد","court":"جزءان متصلان في الوسط بمفصل.","fonctionnement":"عندما يُشدّ العنانان معًا، ينثني القضيب: يضغط على اللسان والبارات وقد يرتفع نحو سقف الحلق (تأثير « كسّارة البندق »).","caracteristiques":"يسمح بالتأثير على كل جانب من الفم على حدة.","precautions":"مع يد قاسية أو حصان سقف حلقه منخفض، قد يلمس المفصلُ سقفَ الحلق."},{"nom":"مفصل مزدوج","court":"ثلاثة أجزاء: قطعة وسطى صغيرة (حلقة أو زيتونة أو صفيحة) بين قضيبين.","fonctionnement":"تتكيّف القطعة الوسطى مع شكل اللسان: يقلّ تأثير « كسّارة البندق » كثيرًا.","caracteristiques":"غالبًا ما تكون أكثر راحة للخيول ذات اللسان السميك أو الحساس.","precautions":"يجب أن تبقى الصفيحة الوسطى مسطحة على اللسان: لا ينبغي أن تميل جانبيًا."}]},{"titre":"شكائم ذات تأثير الرافعة","texte":"لهذه الشكائم أذرع. عندما يشدّ العنان أسفل الذراع، تدور الشكيمة: هذا هو تأثير الرافعة.","cartes":[{"nom":"مبدأ الرافعة","court":"الأذرع وسلسلة الذقن وحزام الرأس العلوي تعمل معًا.","fonctionnement":"عند الدوران، تضغط الشكيمة على البارات، وتنشدّ سلسلة الذقن في تجويف الذقن، ويضغط حزام الرأس العلوي على مؤخرة الرأس.","caracteristiques":"كلما طال الذراع أسفل القضيب، كان التأثير أقوى لنفس شدّ العنان.","precautions":"يجب ضبط سلسلة الذقن جيدًا واستخدام الأعنّة بلطف شديد."},{"nom":"بيلهام","court":"قضيب واحد بأذرع وسلسلة ذقن وزوجين من الأعنّة.","fonctionnement":"العنان المربوط في الأعلى يعمل أساسًا كشكيمة سنافل؛ والعنان السفلي يضيف تأثير الرافعة.","caracteristiques":"يجمع في شكيمة واحدة تأثيرات السنافل وشكيمة الكبح.","precautions":"عند تركيبه بعنان واحد (مع قطعة وصل بين الحلقتين)، يفقد من دقته."},{"nom":"شكيمة بيسوا","court":"سنافل بعدة حلقات متراكبة.","fonctionnement":"بحسب الحلقة التي يُربط بها العنان، يكون التأثير قريبًا من السنافل أو يضيف رافعة.","caracteristiques":"كلما كانت الحلقة المختارة أدنى، كان تأثير الرافعة أوضح.","precautions":"تُخصَّص للفرسان ذوي اليد الثابتة، ويجب اختيار الضبط مع المدرّب."}]},{"titre":"اللجام المزدوج","texte":"يجمع اللجام المزدوج شكيمتين في فم الحصان: سنافل رفيعة تُسمّى البرادون، وشكيمة كبح بأذرع مع سلسلة ذقنها، ولكل منهما زوج من الأعنّة.","cartes":[{"nom":"شكيمة الكبح (ويموث) والبرادون","court":"شكيمتان، أربعة أعنّة.","fonctionnement":"يؤثر البرادون على زوايا الشفتين ويرفع الرأس؛ وتضيف شكيمة الكبح تأثير الرافعة على البارات والذقن ومؤخرة الرأس. يضبط الفارس كل عنان على حدة.","caracteristiques":"يُستخدم في الترويض عالي المستوى وفي الزيّ التقليدي. الركوب باللجام المزدوج من ضمن برنامج Galop 7.","precautions":"يتطلب يدًا مستقلة وجلسة ثابتة وحصانًا مروَّضًا جيدًا بالسنافل مسبقًا."}]}],"matieres":{"titre":"هل تعلمين؟","texte":"تتوفر الشكائم بمواد متعددة: الفولاذ المقاوم للصدأ، والنحاس أو السبائك التي تحفّز إفراز اللعاب، والمطاط والمواد الصناعية الأكثر ليونة. الفم الذي يفرز قليلًا من اللعاب ويمضغ هو عمومًا فم مسترخٍ."}},"s3":{"num":"03","titre":"التشريح ومناطق التأثير","intro":"تستقر الشكيمة في مكان محدد جدًا: بين القواطع والأضراس، حيث لا توجد أسنان. وتؤثر على عدة مناطق لا تتفاعل كلها بالطريقة نفسها.","schemaTitre":"رسم مبسّط لرأس الحصان","schemaNote":"رسم تعليمي، النِّسَب مبسّطة.","zones":[{"nom":"اللسان","texte":"يتلقى جزءًا كبيرًا من الضغط، خاصة مع القضيب المستقيم أو ذي المفصل المزدوج."},{"nom":"البارات","texte":"جزء الفك السفلي الخالي من الأسنان، بين القواطع والأضراس. تغطي اللثة العظمَ مباشرة هناك: إنها منطقة حساسة جدًا."},{"nom":"زوايا الشفتين والشفتان","texte":"زوايا الفم. تؤثر السنافل عليها، خاصة عندما ترفع الرأس أو عند استخدام العنان الفاتح."},{"nom":"سقف الحلق","texte":"أعلى الفم. المفصل الواحد الذي ينثني أكثر من اللازم قد يلمسه."},{"nom":"مؤخرة الرأس","texte":"مع شكيمة الرافعة، ينقل حزام الرأس العلوي ضغطًا على أعلى الرأس."},{"nom":"الذقن","texte":"توضع سلسلة الذقن الخاصة بشكيمة الأذرع في تجويف الذقن وتضغط عليه عندما تدور الشكيمة."}],"mecaTitre":"ثلاث طرق للتأثير","mecanismes":[{"nom":"ضغط مباشر","texte":"مع السنافل، ينتقل شدّ العنان إلى اللسان والبارات وزوايا الشفتين، في الاتجاه الذي تشدّ نحوه اليد."},{"nom":"تأثير الرافعة","texte":"مع الأذرع، تدور الشكيمة: تتضاعف القوة وتتوزع بين البارات والذقن ومؤخرة الرأس."},{"nom":"تأثير جانبي","texte":"تضغط الحلقات الثابتة أو الأذرع على الخد المقابل للعنان الفاتح وتساعد الحصان على الالتفاف."}]},"s4":{"num":"04","titre":"كيف تختارين الشكيمة؟","intro":"لا توجد شكيمة « جيدة » بشكل مطلق: توجد شكيمة مناسبة لحصان ما، ولفارس ما، ولمرحلة معينة من عملهما. إليكِ المعايير التي يجب النظر فيها مع مدرّبكِ.","criteres":[{"nom":"فم الحصان","texte":"عرضه يحدد مقاس الشكيمة. اللسان السميك أو سقف الحلق المنخفض يتطلبان غالبًا قضيبًا أرفع أو ذا مفصل مزدوج."},{"nom":"حساسيته","texte":"الحصان الحساس جدًا غالبًا ما يكون أكثر راحة مع شكيمة ثابتة ولطيفة."},{"nom":"مستوى ترويضه","texte":"يبدأ الحصان الصغير بشكيمة سنافل بسيطة. أما شكائم الرافعة واللجام المزدوج فتأتي لاحقًا، مع حصان متمرّس."},{"nom":"الاختصاص","texte":"تحدد لوائح كل اختصاص الشكائم المسموح بها في المنافسات. تحققي دائمًا من لوائح الاتحاد السارية."},{"nom":"يد الفارس","texte":"كلما كانت الشكيمة أقوى، تطلّبت يدًا ثابتة ولطيفة ومستقلة عن الجلسة."},{"nom":"الضبط والراحة","texte":"أفضل شكيمة لا تعمل جيدًا إلا إذا كانت بالمقاس الصحيح ومضبوطة على الارتفاع الصحيح."}],"important":{"titre":"نصيحة المدرّب","texte":"الشكيمة الأشد لا تحلّ أبدًا محل عمل ترويض صحيح. إذا كان حصانكِ يشدّ أو يستند أو يفتح فمه، ابحثي أولًا عن السبب: يدكِ، توازنكِ، استرخاؤه، أسنانه، ضبط المعدات. لا تغيّري الشكيمة إلا برأي مدرّبكِ."}},"s5":{"num":"05","titre":"الضبط والعناية","intro":"الشكيمة المختارة جيدًا لكن المضبوطة بشكل سيئ تصبح سريعًا غير مريحة. اعتادي على التحقق من هذه النقاط قبل كل حصة.","verifTitre":"التحققات قبل الركوب","verifs":["العرض: تبرز الشكيمة بحوالي نصف سنتيمتر من كل جانب من الفم، دون أن تضغط على الشفتين.","الارتفاع: مع السنافل، نرى عادة ثنية أو ثنيتين صغيرتين في زاوية الشفتين. بلا ثنية تكون السنافل منخفضة جدًا؛ ومع ثنيات كثيرة تكون مرتفعة جدًا.","سلسلة الذقن: تكون مسطحة في تجويف الذقن؛ ويجب أن نتمكن من إدخال إصبعين بين السلسلة والذقن.","الحالة: لا حواف حادة، ولا تآكل في ثقوب الحلقات أو في المفاصل، ولا أي قطعة تقرص.","الجلود: أحزمة الخدّين والإبزيمات والأعنّة لينة وفي حالة جيدة."],"entretienTitre":"بعد الحصة","entretien":"اشطفي الشكيمة بالماء النظيف فور نزع السرج واللجام، قبل أن يجفّ اللعاب والعشب. جففيها، اتركيها تجفّ، ثم اعتني بالجلود بانتظام.","erreurs":{"titre":"الأخطاء التي يجب تجنبها","points":["ضبط ارتفاع السنافل « عشوائيًا » دون النظر إلى زوايا الشفتين.","الاحتفاظ بشكيمة تالفة لأن « الحصان معتاد عليها ».","شدّ سلسلة الذقن « للحصول على كبح أكبر ».","ترك الشكيمة تجفّ متّسخة بعد الحصة."]}},"s6":{"num":"06","titre":"حالات خاصة","intro":"في Galop 5، يكفي أن تتعرّفي عليها وتفهمي مبدأها. أما استخدامها فيُقرَّر مع مدرّب.","cartes":[{"nom":"سنافل بوشيه","court":"سنافل مثبّت فيها حلقة صغيرة إضافية بحزام الخد.","detail":"تبقى الشكيمة معلّقة وثابتة جدًا في الفم. تناسب الخيول التي تعبث كثيرًا بشكيمتها."},{"nom":"الشكائم اللينة","court":"من المطاط أو من مادة صناعية.","detail":"لطيفة وخفيفة، تناسب الأفواه الحساسة أو الخيول الصغيرة. تتآكل بسرعة أكبر: تحققي من أنها غير معضوضة أو مشقوقة."},{"nom":"الهاكامور","court":"لجام بلا شكيمة.","detail":"يؤثر بالضغط على قصبة الأنف والذقن ومؤخرة الرأس، دون أي شيء في الفم. ليس حلًا « ألطف » بالضرورة: إذا ضُبط بشكل سيئ قد يكون شديد القسوة."},{"nom":"حزام الأنف","court":"ليس شكيمة، لكنه يغيّر تأثيرها.","detail":"حزام الأنف المشدود أكثر من اللازم يمنع الحصان من المضغ ويجعل الاتصال قاسيًا. يجب أن نتمكن من إدخال إصبعين بين حزام الأنف وقصبة الأنف."}]},"lateral":{"observerTitre":"للملاحظة","observer":"في حصتكِ القادمة، انظري إلى فم الحصان: هل هو مغلق وهادئ؟ هل يمضغ قليلًا؟ هل نرى ثنية أو ثنيتين عند زوايا الشفتين؟ الفم المسترخي غالبًا ما يدل على حصان مسترخٍ.","defiTitre":"تحدّي الفارسة","defi":"في غرفة السروج في ناديكِ، ابحثي عن ثلاث شكائم مختلفة وسمّيها: نوع الحلقات، شكل القضيب، تأثير مباشر أو رافعة. ثم اعرضي إجابتكِ على مدرّبكِ."},"videos":{"titre":"لفهم أفضل بالصور","v1":"التعرّف على الأنواع الرئيسية من الشكائم","v2":"فهم التأثيرات المختلفة للشكيمة","v3":"التحقق من ضبط الشكيمة","aVenir":"الفيديو قريبًا","tous":"عرض مكتبة الفيديو كاملة"},"quiz":{"titre":"اختبري معلوماتكِ","texte":"هل أنهيتِ هذا الدرس؟ تحققي مما تذكّرتِه.","bouton":"الدخول إلى الاختبار","bientot":"قريبًا"}},"de":{"meta":{"kicker":"Galopp 5 · Pferdewissen","titre":"Die Gebisse","sous":"Ihre Wirkung verstehen und das richtige wählen.","duree":"Etwa 20 Min. Lesezeit","type":"Theoriekurs","audio":"Audio anhören","langues":"Verfügbar in 14 Sprachen","retour":"Die Kurse zu Galopp 5","progression":"Lesefortschritt","sommaire":"Inhalt des Kurses","photoAVenir":"Foto folgt","agrandir":"Foto vergrößern","fermer":"Schließen","voirPlus":"Details anzeigen","voirMoins":"Details ausblenden","fonctionnement":"Wirkungsweise","caracteristiques":"Gut zu wissen","precautions":"Worauf du achten musst"},"nav":["Warum","Arten","Anatomie","Auswählen","Anpassen","Sonderfälle"],"s1":{"num":"01","titre":"Wozu ein Gebiss?","paras":["Das Gebiss ist das Teil aus Metall oder weichem Material, das im Maul des Pferdes liegt und mit den Zügeln verbunden ist. Es überträgt die Einwirkungen deiner Hand auf das Pferd: Neben den Schenkeln, dem Sitz und der Stimme ist es eines der Mittel, mit denen du mit ihm kommunizierst.","Eine gute Anlehnung ist eine leichte, elastische und gleichmäßige Verbindung zwischen deiner Hand und dem Pferdemaul. Deine Hand geht die Bewegung des Halses mit, vor allem im Schritt und im Galopp, damit das Pferd am Gebiss eine sichere, vertrauensvolle Stütze findet und es nie als störend empfindet.","Das Pferdemaul ist sehr empfindlich. Jede Zügelhilfe – halbe Parade, öffnender Zügel, verwahrender Zügel – muss kurz und dosiert sein und nachgegeben werden, sobald das Pferd reagiert. Durch rechtzeitiges Nachgeben belohnt die Hand, und so lernt das Pferd."],"retenir":{"titre":"Merke dir","points":["Das Gebiss überträgt die Einwirkungen der Hand: Es ersetzt weder die Schenkel noch den Sitz.","Die Anlehnung muss leicht, elastisch und gleichmäßig sein.","Eine Zügelhilfe wird nachgegeben, sobald das Pferd reagiert hat."]}},"s2":{"num":"02","titre":"Die verschiedenen Gebissarten","intro":"Gebisse werden nach zwei großen Kriterien eingeteilt: der Form des Mundstücks (des Teils, der im Maul liegt) und der Art, wie es mit den Zügeln verbunden ist (Trensenringe oder Anzüge einer Kandare). Tippe auf eine Karte, um die Details zu sehen.","groupes":[{"titre":"Trensen: direkte Wirkung","texte":"Bei einer Trense wirkt der Zügel direkt auf das Gebiss, ohne Hebelwirkung: Der Druck, den das Pferd spürt, entspricht der Spannung des Zügels.","cartes":[{"nom":"Olivenkopftrense","court":"Die Ringe sind über Oliven fest mit dem Mundstück verbunden.","fonctionnement":"Die Oliven verhindern, dass sich das Gebiss dreht oder verschiebt: Es liegt ruhig im Maul.","caracteristiques":"Klemmt die Maulwinkel nicht ein. Wird oft für empfindliche Pferde oder Pferde gewählt, die die Anlehnung erst lernen.","precautions":"Prüfe die Breite: Ein zu schmales Gebiss drückt die Lippen zusammen, ein zu breites verrutscht seitlich."},{"nom":"Knebeltrense","court":"Senkrechte Knebel verlängern die Ringe auf beiden Seiten des Mauls.","fonctionnement":"Bei einem öffnenden Zügel drücken die Knebel seitlich gegen den Kopf und helfen dem Pferd beim Wenden. Außerdem verhindern sie, dass das Gebiss durchs Maul rutscht.","caracteristiques":"Praktisch für junge Pferde und für Pferde, die sich schwer lenken lassen.","precautions":"Die Knebel werden oft mit kleinen Lederschlaufen an den Backenstücken befestigt, damit sie nirgends hängen bleiben."},{"nom":"D-Ring-Trense (Verdun)","court":"Feste Ringe in D-Form, mit einer geraden Seite an der Backe.","fonctionnement":"Die gerade Seite des Rings liegt flach an der Backe an: Das Gebiss liegt ruhig, und das Pferd spürt den öffnenden Zügel deutlich.","caracteristiques":"Klemmt die Maulwinkel nicht ein. Wird in der Dressur ebenso wie im Springen und im Rennsport verwendet.","precautions":"Wie bei jeder Trense mit festen Ringen muss die Breite genau passen."},{"nom":"Wassertrense","court":"Die Ringe gleiten frei durch die Löcher des Mundstücks.","fonctionnement":"Das Gebiss bewegt sich mehr im Maul, was das Pferd oft zum Kauen und Loslassen anregt.","caracteristiques":"Das ist die gebräuchlichste Trense.","precautions":"Sind die Löcher abgenutzt oder ist das Gebiss zu schmal, können die Ringe die Maulwinkel einklemmen: Kontrolliere sie regelmäßig."}]},{"titre":"Die Form des Mundstücks","texte":"Unabhängig von der Art der Ringe verändert die Form des Mundstücks, wie sich der Druck im Maul verteilt.","cartes":[{"nom":"Stangengebiss","court":"Ein Mundstück aus einem Stück, starr oder leicht flexibel.","fonctionnement":"Der Druck verteilt sich gleichmäßig rechts und links auf die Zunge und die Laden.","caracteristiques":"Ruhig liegendes Gebiss, oft aus Gummi oder weichem Kunststoff erhältlich.","precautions":"Einseitige Zügelhilfen sind weniger präzise als mit einem gebrochenen Mundstück."},{"nom":"Einfach gebrochen","court":"Zwei Teile, in der Mitte durch ein Gelenk verbunden.","fonctionnement":"Wenn beide Zügel angenommen werden, knickt das Mundstück ein: Es drückt auf Zunge und Laden und kann zum Gaumen hochsteigen („Nussknackereffekt“).","caracteristiques":"Ermöglicht es, auf jede Maulseite getrennt einzuwirken.","precautions":"Bei harter Hand oder bei einem Pferd mit flachem Gaumen kann das Gelenk den Gaumen berühren."},{"nom":"Doppelt gebrochen","court":"Drei Teile: ein kleines Mittelstück (Ring, Olive oder Plättchen) zwischen zwei Schenkeln des Mundstücks.","fonctionnement":"Das Mittelstück schmiegt sich an die Zunge: Der „Nussknackereffekt“ ist stark verringert.","caracteristiques":"Oft angenehmer für Pferde mit dicker oder empfindlicher Zunge.","precautions":"Das Mittelplättchen muss flach auf der Zunge liegen: Es darf sich nicht schräg stellen."}]},{"titre":"Gebisse mit Hebelwirkung","texte":"Diese Gebisse haben Anzüge (Seitenteile). Wenn der Zügel am unteren Ende des Anzugs zieht, dreht sich das Gebiss: Das ist die Hebelwirkung.","cartes":[{"nom":"Das Hebelprinzip","court":"Anzüge, Kinnkette und Genickstück wirken zusammen.","fonctionnement":"Beim Drehen drückt das Gebiss auf die Laden, die Kinnkette legt sich in die Kinngrube, und das Genickstück drückt auf das Genick.","caracteristiques":"Je länger der Anzug unterhalb des Mundstücks, desto stärker die Wirkung bei gleicher Zügelspannung.","precautions":"Die Kinnkette muss richtig verschnallt sein, und die Zügel müssen sehr gefühlvoll eingesetzt werden."},{"nom":"Pelham","court":"Ein einziges Mundstück mit Anzügen, Kinnkette und zwei Zügelpaaren.","fonctionnement":"Der oben eingeschnallte Zügel wirkt vor allem wie eine Trense; der untere fügt die Hebelwirkung hinzu.","caracteristiques":"Er vereint die Wirkung von Trense und Kandare in einem einzigen Gebiss.","precautions":"Mit nur einem Zügel geritten (mit einem Verbindungsriemen zwischen den beiden Ringen) verliert er an Präzision."},{"nom":"Pessoa-Gebiss","court":"Eine Trense mit mehreren übereinanderliegenden Ringen.","fonctionnement":"Je nachdem, in welchen Ring der Zügel eingeschnallt ist, wirkt es ähnlich wie eine Trense oder zusätzlich mit Hebel.","caracteristiques":"Je tiefer der gewählte Ring, desto stärker die Hebelwirkung.","precautions":"Nur für Reiter mit sicherer Hand; die Einstellung wird mit dem Reitlehrer festgelegt."}]},{"titre":"Die Kandarenzäumung","texte":"Bei der Kandarenzäumung liegen zwei Gebisse im Pferdemaul: eine dünne Trense, die Unterlegtrense, und eine Kandare mit Anzügen und Kinnkette, jede mit ihrem eigenen Zügelpaar.","cartes":[{"nom":"Kandare und Unterlegtrense","court":"Zwei Gebisse, vier Zügel.","fonctionnement":"Die Unterlegtrense wirkt auf die Maulwinkel und richtet auf; die Kandare fügt die Hebelwirkung auf Laden, Kinn und Genick hinzu. Der Reiter dosiert jeden Zügel einzeln.","caracteristiques":"Wird in der Dressur auf hohem Niveau und bei traditioneller Ausrüstung verwendet. Das Reiten auf Kandare steht auf dem Programm von Galopp 7.","precautions":"Erfordert eine unabhängige Hand, einen stabilen Sitz und ein Pferd, das auf Trense bereits gut ausgebildet ist."}]}],"matieres":{"titre":"Wusstest du?","texte":"Gebisse gibt es aus verschiedenen Materialien: Edelstahl, Kupfer oder Legierungen, die den Speichelfluss fördern, sowie Gummi und weichere Kunststoffe. Ein Maul, das etwas speichelt und kaut, ist in der Regel ein entspanntes Maul."}},"s3":{"num":"03","titre":"Anatomie und Einwirkungsbereiche","intro":"Das Gebiss liegt an einer ganz bestimmten Stelle: zwischen den Schneidezähnen und den Backenzähnen, wo keine Zähne sind. Es wirkt auf mehrere Bereiche, die nicht alle gleich reagieren.","schemaTitre":"Vereinfachte Skizze eines Pferdekopfes","schemaNote":"Lernskizze, Proportionen vereinfacht.","zones":[{"nom":"Die Zunge","texte":"Sie nimmt einen großen Teil des Drucks auf, vor allem bei einem Stangengebiss oder einem doppelt gebrochenen Mundstück."},{"nom":"Die Laden","texte":"Zahnloser Teil des Unterkiefers zwischen den Schneidezähnen und den Backenzähnen. Das Zahnfleisch liegt dort direkt auf dem Knochen: ein sehr empfindlicher Bereich."},{"nom":"Maulwinkel und Lippen","texte":"Die Ecken des Mauls. Hier wirkt die Trense, vor allem wenn sie aufrichtet oder bei einem öffnenden Zügel."},{"nom":"Der Gaumen","texte":"Das Dach des Mauls. Ein einfach gebrochenes Gebiss, das zu stark einknickt, kann ihn berühren."},{"nom":"Das Genick","texte":"Bei einem Hebelgebiss überträgt das Genickstück Druck auf die Oberseite des Kopfes."},{"nom":"Das Kinn","texte":"Die Kinnkette eines Gebisses mit Anzügen liegt in der Kinngrube und drückt dort, wenn sich das Gebiss dreht."}],"mecaTitre":"Drei Arten der Einwirkung","mecanismes":[{"nom":"Direkter Druck","texte":"Bei einer Trense überträgt sich die Zügelspannung auf Zunge, Laden und Maulwinkel, in die Richtung, in die die Hand zieht."},{"nom":"Hebelwirkung","texte":"Mit Anzügen dreht sich das Gebiss: Die Kraft wird verstärkt und verteilt sich auf Laden, Kinn und Genick."},{"nom":"Seitliche Wirkung","texte":"Feste Ringe oder Knebel drücken gegen die Backe auf der dem öffnenden Zügel gegenüberliegenden Seite und helfen dem Pferd beim Wenden."}]},"s4":{"num":"04","titre":"Wie wählt man ein Gebiss aus?","intro":"Ein „richtiges“ Gebiss an sich gibt es nicht: Es gibt ein Gebiss, das zu einem Pferd, einem Reiter und einem bestimmten Zeitpunkt ihrer Arbeit passt. Hier sind die Kriterien, die du dir mit deinem Reitlehrer anschauen solltest.","criteres":[{"nom":"Das Pferdemaul","texte":"Seine Breite bestimmt die Größe des Gebisses. Eine dicke Zunge oder ein flacher Gaumen erfordern oft ein dünneres oder doppelt gebrochenes Mundstück."},{"nom":"Seine Empfindlichkeit","texte":"Ein sehr empfindliches Pferd fühlt sich mit einem ruhig liegenden, sanften Gebiss oft wohler."},{"nom":"Sein Ausbildungsstand","texte":"Ein junges Pferd beginnt mit einer einfachen Trense. Hebelgebisse und Kandare kommen später, bei einem ausgebildeten Pferd."},{"nom":"Die Disziplin","texte":"Das Reglement jeder Disziplin legt fest, welche Gebisse im Turnier erlaubt sind. Prüfe immer das aktuell gültige Verbandsreglement."},{"nom":"Die Hand des Reiters","texte":"Je stärker ein Gebiss wirkt, desto mehr verlangt es eine ruhige, weiche und vom Sitz unabhängige Hand."},{"nom":"Passform und Komfort","texte":"Selbst das beste Gebiss funktioniert nur gut, wenn es die richtige Größe hat und in der richtigen Höhe verschnallt ist."}],"important":{"titre":"Der Tipp vom Coach","texte":"Ein schärferes Gebiss ersetzt niemals eine korrekte Ausbildung. Wenn dein Pferd zieht, sich auf das Gebiss legt oder das Maul aufsperrt, such zuerst die Ursache: deine Hand, dein Gleichgewicht, seine Losgelassenheit, seine Zähne, die Verschnallung der Ausrüstung. Wechsle das Gebiss nur nach Rücksprache mit deinem Reitlehrer."}},"s5":{"num":"05","titre":"Anpassung und Pflege","intro":"Ein gut gewähltes, aber schlecht verschnalltes Gebiss wird schnell unbequem. Gewöhn dir an, diese Punkte vor jeder Reitstunde zu kontrollieren.","verifTitre":"Die Kontrollen vor dem Aufsitzen","verifs":["Die Breite: Das Gebiss steht auf jeder Seite des Mauls etwa einen halben Zentimeter über, ohne die Lippen einzuklemmen.","Die Höhe: Bei einer Trense sieht man in der Regel ein oder zwei kleine Falten im Maulwinkel. Ohne Falte hängt die Trense zu tief; bei vielen Falten ist sie zu hoch.","Die Kinnkette: Sie liegt flach in der Kinngrube; zwischen Kinnkette und Kinn müssen zwei Finger passen.","Der Zustand: keine scharfen Kanten, keine Abnutzung an den Ringlöchern oder Gelenken, kein Teil, das einklemmt.","Das Leder: Backenstücke, Schnallen und Zügel sind geschmeidig und in gutem Zustand."],"entretienTitre":"Nach der Reitstunde","entretien":"Spül das Gebiss gleich nach dem Absatteln mit klarem Wasser ab, bevor Speichel und Gras antrocknen. Wisch es ab, lass es trocknen und pflege das Leder regelmäßig.","erreurs":{"titre":"Fehler, die du vermeiden solltest","points":["Die Höhe der Trense „nach Gefühl“ einstellen, ohne auf die Maulwinkel zu schauen.","Ein beschädigtes Gebiss behalten, weil „das Pferd daran gewöhnt ist“.","Die Kinnkette enger schnallen, um „mehr Bremse“ zu haben.","Das Gebiss nach dem Reiten schmutzig antrocknen lassen."]}},"s6":{"num":"06","titre":"Sonderfälle","intro":"Für Galopp 5 reicht es, sie zu erkennen und ihr Prinzip zu verstehen. Über ihren Einsatz wird mit einem Reitlehrer entschieden.","cartes":[{"nom":"Die Baucher-Trense","court":"Eine Trense mit einem zusätzlichen kleinen Ring, der am Backenstück befestigt wird.","detail":"Das Gebiss hängt im Maul und liegt sehr ruhig. Es eignet sich für Pferde, die viel mit dem Gebiss spielen."},{"nom":"Weiche Gebisse","court":"Aus Gummi oder Kunststoff.","detail":"Sanft und leicht, eignen sie sich für empfindliche Mäuler oder junge Pferde. Sie nutzen sich schneller ab: Prüfe, dass sie nicht angeknabbert oder eingerissen sind."},{"nom":"Die Hackamore","court":"Eine gebisslose Zäumung.","detail":"Sie wirkt durch Druck auf Nasenrücken, Kinn und Genick, ohne etwas im Maul. Sie ist nicht grundsätzlich die „sanftere“ Lösung: Falsch verschnallt kann sie sehr scharf sein."},{"nom":"Das Nasenband","court":"Es ist kein Gebiss, verändert aber dessen Wirkung.","detail":"Ein zu eng verschnalltes Nasenband hindert das Pferd am Kauen und macht die Anlehnung hart. Zwischen Nasenband und Nasenrücken müssen zwei Finger passen."}]},"lateral":{"observerTitre":"Beobachte","observer":"Schau dir in deiner nächsten Reitstunde das Maul des Pferdes an: Ist es geschlossen und ruhig? Kaut es ein wenig? Sieht man ein oder zwei Falten in den Maulwinkeln? Ein entspanntes Maul zeigt oft ein entspanntes Pferd.","defiTitre":"Die Reiter-Challenge","defi":"Such in der Sattelkammer deines Stalls drei verschiedene Gebisse und benenne sie: Art der Ringe, Form des Mundstücks, direkte Wirkung oder Hebelwirkung. Zeig deine Antwort dann deinem Reitlehrer."},"videos":{"titre":"Besser verstehen mit Bildern","v1":"Die wichtigsten Gebissarten erkennen","v2":"Die verschiedenen Wirkungen eines Gebisses verstehen","v3":"Die Passform eines Gebisses überprüfen","aVenir":"Video folgt","tous":"Alle Videos ansehen"},"quiz":{"titre":"Teste dein Wissen","texte":"Hast du diese Lektion abgeschlossen? Überprüfe, was du behalten hast.","bouton":"Zum Quiz","bientot":"Demnächst"}},"en":{"meta":{"kicker":"Level 5 · Equestrian knowledge","titre":"Bits","sous":"Understanding how they work and choosing the right one.","duree":"About a 20-minute read","type":"Theory lesson","audio":"Listen to the lesson","langues":"Available in all 14 languages","retour":"Level 5 lessons","progression":"Reading progress","sommaire":"Lesson contents","photoAVenir":"Photo coming soon","agrandir":"Enlarge photo","fermer":"Close","voirPlus":"Show details","voirMoins":"Hide details","fonctionnement":"How it works","caracteristiques":"Good to know","precautions":"Precautions"},"nav":["Why","Families","Anatomy","Choosing","Fitting","Special cases"],"s1":{"num":"01","titre":"Why use a bit?","paras":["The bit is the piece of metal or soft material placed in the horse's mouth and attached to the reins. It passes the actions of your hand on to the horse: it's one of the ways you and your horse communicate, along with your legs, your seat and your voice.","Good contact is a light, elastic and steady connection between your hand and the horse's mouth. Your hand follows the movement of the neck, especially in walk and canter, so that the horse finds a steady, reassuring support in the bit, never something uncomfortable.","The horse's mouth is very sensitive. Every rein aid — half-halt, opening rein, indirect rein — must be brief and measured, then released as soon as the horse responds. By giving at the right moment, your hand rewards the horse and the horse learns."],"retenir":{"titre":"Key points","points":["The bit passes on the actions of your hand: it doesn't replace your legs or your seat.","The contact should be light, elastic and steady.","Release a rein aid as soon as the horse has responded."]}},"s2":{"num":"02","titre":"The different families of bits","intro":"Bits are classified by two main criteria: the shape of the mouthpiece (the part that goes into the mouth) and how it's connected to the reins (snaffle rings or curb shanks). Tap a card to see the details.","groupes":[{"titre":"Snaffles: direct action","texte":"With a snaffle, the rein acts directly on the bit, with no leverage: the pressure the horse feels matches the tension in the rein.","cartes":[{"nom":"Eggbutt snaffle","court":"The rings are attached to the mouthpiece by eggbutt joints.","fonctionnement":"The eggbutt joints stop the bit from turning and sliding: it stays steady in the mouth.","caracteristiques":"Doesn't pinch the corners of the mouth. Often chosen for sensitive horses or horses learning to accept the contact.","precautions":"Check the width: a bit that's too narrow squeezes the lips; one that's too wide slides off-centre."},{"nom":"Full-cheek snaffle","court":"Vertical cheeks extend the rings on each side of the mouth.","fonctionnement":"The cheeks press against the side of the head when you use an opening rein and help the horse turn. They also stop the bit from sliding through the mouth.","caracteristiques":"Useful for young horses and horses that are hard to steer.","precautions":"The cheeks are often fastened to the bridle's cheekpieces with small leather keepers so they don't catch on anything."},{"nom":"D-ring snaffle (Verdun)","court":"Fixed D-shaped rings, with the straight side against the cheek.","fonctionnement":"The straight side of the ring stays flat against the cheek: the bit is steady and the horse clearly feels the opening rein.","caracteristiques":"Doesn't pinch the corners of the mouth. Used on the flat, for jumping and for racing.","precautions":"As with any fixed-ring snaffle, the width must be just right."},{"nom":"Loose-ring snaffle","court":"The rings slide freely through the holes in the mouthpiece.","fonctionnement":"The bit moves more in the mouth, which often encourages the horse to mouth the bit and relax.","caracteristiques":"It's the most common snaffle.","precautions":"If the holes are worn or the bit is too narrow, the rings can pinch the corners of the mouth: check them regularly."}]},{"titre":"The shape of the mouthpiece","texte":"Whatever the type of rings, the shape of the mouthpiece changes how the pressure is spread in the mouth.","cartes":[{"nom":"Mullen mouth (straight bar)","court":"A one-piece mouthpiece, rigid or slightly flexible.","fonctionnement":"The pressure is spread over the tongue and the bars, evenly on the left and right.","caracteristiques":"A steady bit, often available in rubber or soft synthetic material.","precautions":"Single-rein aids are less precise than with a jointed mouthpiece."},{"nom":"Single-jointed","court":"Two parts joined in the middle by a joint.","fonctionnement":"When both reins are tightened, the mouthpiece folds: it presses on the tongue and the bars and can rise towards the palate (the “nutcracker” effect).","caracteristiques":"Lets you act separately on each side of the mouth.","precautions":"With a heavy hand or a horse with a low palate, the joint can touch the palate."},{"nom":"Double-jointed","court":"Three parts: a small central link (ring, lozenge or plate) between two side pieces.","fonctionnement":"The central link follows the shape of the tongue: the “nutcracker” effect is greatly reduced.","caracteristiques":"Often more comfortable for horses with a thick or sensitive tongue.","precautions":"The central plate must lie flat on the tongue: it shouldn't sit at an angle."}]},{"titre":"Leverage bits","texte":"These bits have shanks. When the rein pulls on the bottom of the shank, the bit rotates: this is the leverage effect.","cartes":[{"nom":"How leverage works","court":"Shanks, curb chain and headpiece work together.","fonctionnement":"As it rotates, the bit presses on the bars, the curb chain tightens in the chin groove and the headpiece presses on the poll.","caracteristiques":"The longer the shank below the mouthpiece, the stronger the effect for the same rein tension.","precautions":"The curb chain must be correctly adjusted and the reins used very gently."},{"nom":"Pelham","court":"A single mouthpiece with shanks, a curb chain and two pairs of reins.","fonctionnement":"The top rein acts mainly like a snaffle; the bottom rein adds the leverage effect.","caracteristiques":"It combines the effects of a snaffle and a curb in a single bit.","precautions":"Used with a single rein (with a connector between the two rings), it loses precision."},{"nom":"Pessoa bit (Dutch gag)","court":"A snaffle with several rings one above the other.","fonctionnement":"Depending on which ring the rein is attached to, the effect is close to a snaffle or adds leverage.","caracteristiques":"The lower the ring you choose, the stronger the leverage effect.","precautions":"Only for riders with a secure hand, and the setting should be chosen with your instructor."}]},{"titre":"The double bridle","texte":"The double bridle puts two bits in the horse's mouth: a thin snaffle, called the bradoon, and a curb bit with shanks and a curb chain (the Weymouth), each with its own pair of reins.","cartes":[{"nom":"Weymouth and bradoon","court":"Two bits, four reins.","fonctionnement":"The bradoon acts on the corners of the mouth and raises the head; the Weymouth adds leverage on the bars, chin and poll. The rider adjusts each rein separately.","caracteristiques":"Used in high-level dressage and with traditional turnout. Riding in a double bridle is part of the Level 7 syllabus.","precautions":"It requires an independent hand, a steady seat and a horse that is already well schooled in a snaffle."}]}],"matieres":{"titre":"Did you know?","texte":"Bits come in several materials: stainless steel, copper or alloys that encourage salivation, and softer rubber and synthetic materials. A mouth that salivates a little and gently mouths the bit is usually a relaxed mouth."}},"s3":{"num":"03","titre":"Anatomy and areas of action","intro":"The bit rests in a very specific space: between the incisors and the molars, where there are no teeth. It acts on several areas, which don't all react in the same way.","schemaTitre":"Simplified diagram of a horse's head","schemaNote":"Teaching diagram, simplified proportions.","zones":[{"nom":"The tongue","texte":"It takes a large part of the pressure, especially with a mullen or double-jointed mouthpiece."},{"nom":"The bars","texte":"The toothless part of the lower jaw, between the incisors and the molars. Here the gum lies directly over the bone: it's a very sensitive area."},{"nom":"The corners of the mouth and the lips","texte":"The corners of the mouth. The snaffle acts here, especially when it raises the head or with an opening rein."},{"nom":"The palate","texte":"The roof of the mouth. A single-jointed bit that folds too much can touch it."},{"nom":"The poll","texte":"With a leverage bit, the headpiece passes pressure on to the top of the head."},{"nom":"The chin","texte":"The curb chain of a shanked bit sits in the chin groove and presses there when the bit rotates."}],"mecaTitre":"Three ways of acting","mecanismes":[{"nom":"Direct pressure","texte":"With a snaffle, the rein tension is felt on the tongue, the bars and the corners of the mouth, in the direction your hand is pulling."},{"nom":"Leverage","texte":"With shanks, the bit rotates: the force is multiplied and spread between the bars, the chin and the poll."},{"nom":"Lateral action","texte":"Fixed rings or cheeks press on the cheek opposite the opening rein and help the horse turn."}]},"s4":{"num":"04","titre":"How to choose a bit","intro":"There's no such thing as a “good” bit in absolute terms: there's a bit that suits a particular horse, rider and stage of their training. Here are the criteria to look at with your instructor.","criteres":[{"nom":"The horse's mouth","texte":"Its width determines the size of the bit. A thick tongue or a low palate often calls for a thinner or double-jointed mouthpiece."},{"nom":"Its sensitivity","texte":"A very sensitive horse will often be more comfortable in a steady, mild bit."},{"nom":"Its level of training","texte":"A young horse starts in a simple snaffle. Leverage bits and the double bridle come later, with an experienced horse."},{"nom":"The discipline","texte":"The rules of each discipline set out which bits are allowed in competition. Always check the current federation rules."},{"nom":"The rider's hand","texte":"The stronger the bit, the more it calls for a still, elastic hand that is independent of the seat."},{"nom":"Fit and comfort","texte":"Even the best bit only works well if it's the right size and adjusted at the right height."}],"important":{"titre":"Coach's tip","texte":"A stronger bit never replaces correct schooling. If your horse pulls, leans on the bit or opens its mouth, look for the cause first: your hand, your balance, its relaxation, its teeth, how the tack is adjusted. Only change bits on your instructor's advice."}},"s5":{"num":"05","titre":"Fitting and care","intro":"A well-chosen bit that's badly adjusted quickly becomes uncomfortable. Get into the habit of checking these points before every session.","verifTitre":"Checks before you get on","verifs":["Width: the bit sticks out about half a centimetre on each side of the mouth, without squeezing the lips.","Height: with a snaffle, you usually see one or two small wrinkles at the corners of the lips. No wrinkles means the bit is too low; lots of wrinkles means it's too high.","Curb chain: it lies flat in the chin groove; you should be able to slide two fingers between the curb chain and the chin.","Condition: no sharp edges, no wear on the ring holes or joints, no part that pinches.","Leatherwork: the cheekpieces, buckles and reins are supple and in good condition."],"entretienTitre":"After the session","entretien":"Rinse the bit in clean water as soon as you've untacked, before the saliva and grass dry on it. Wipe it, let it dry, then look after the leatherwork regularly.","erreurs":{"titre":"Mistakes to avoid","points":["Adjusting the height of the snaffle “by guesswork” without looking at the corners of the mouth.","Keeping a damaged bit because “the horse is used to it”.","Tightening the curb chain to “get more brakes”.","Leaving the bit to dry dirty after the session."]}},"s6":{"num":"06","titre":"Special cases","intro":"At Level 5, you just need to recognise them and understand how they work. Whether to use them is decided with an instructor.","cartes":[{"nom":"The Baucher snaffle","court":"A snaffle with an extra small ring attached to the cheekpiece.","detail":"The bit stays suspended and very steady in the mouth. It suits horses that play a lot with their bit."},{"nom":"Soft bits","court":"Made of rubber or synthetic material.","detail":"Mild and light, they suit sensitive mouths or young horses. They wear out faster: check they haven't been chewed or split."},{"nom":"The hackamore","court":"A bitless bridle.","detail":"It works by pressure on the nose, the chin and the poll, with nothing in the mouth. It isn't automatically a “gentler” option: if it's badly adjusted, it can be very severe."},{"nom":"The noseband","court":"It isn't a bit, but it changes how the bit works.","detail":"A noseband that's too tight stops the horse from mouthing the bit and makes the contact hard. You should be able to slide two fingers between the noseband and the nose."}]},"lateral":{"observerTitre":"Things to watch","observer":"At your next session, look at the horse's mouth: is it closed and quiet? Is it gently mouthing the bit? Can you see one or two wrinkles at the corners of the mouth? A relaxed mouth often shows a relaxed horse.","defiTitre":"Rider's challenge","defi":"In your club's tack room, find three different bits and name them: type of rings, shape of the mouthpiece, direct action or leverage. Then show your answer to your instructor."},"videos":{"titre":"See it in pictures","v1":"Recognising the main families of bits","v2":"Understanding the different effects of a bit","v3":"Checking how a bit fits","aVenir":"Video coming soon","tous":"See the full video library"},"quiz":{"titre":"Test your knowledge","texte":"Finished this lesson? Check what you've remembered.","bouton":"Go to the quiz","bientot":"Coming soon"}},"es":{"meta":{"kicker":"Nivel 5 · Cultura ecuestre","titre":"Las embocaduras","sous":"Entender sus efectos y elegirlas bien.","duree":"Unos 20 min de lectura","type":"Clase teórica","audio":"Lectura en audio","langues":"Disponible en los 14 idiomas","retour":"Las clases del Nivel 5","progression":"Progreso de lectura","sommaire":"Índice de la clase","photoAVenir":"Foto próximamente","agrandir":"Ampliar la foto","fermer":"Cerrar","voirPlus":"Ver el detalle","voirMoins":"Ocultar el detalle","fonctionnement":"Funcionamiento","caracteristiques":"Para saber","precautions":"Precauciones"},"nav":["Por qué","Familias","Anatomía","Elegir","Ajustar","Casos especiales"],"s1":{"num":"01","titre":"¿Por qué usar una embocadura?","paras":["La embocadura es la pieza de metal o de material flexible que se coloca en la boca del caballo y va unida a las riendas. Transmite al caballo las acciones de tu mano: es uno de los medios de comunicación entre tú y él, junto con las piernas, el asiento y la voz.","Un buen contacto es una unión ligera, elástica y constante entre tu mano y la boca del caballo. Tu mano acompaña el movimiento del cuello, sobre todo al paso y al galope, para que el caballo encuentre en la embocadura un apoyo estable y tranquilizador, nunca una molestia.","La boca del caballo es muy sensible. Cada acción de rienda —media parada, rienda de apertura, rienda contraria— debe ser breve, medida, y cederse en cuanto el caballo responde. Cediendo en el momento justo, la mano recompensa y el caballo aprende."],"retenir":{"titre":"Para recordar","points":["La embocadura transmite las acciones de la mano: no sustituye ni a las piernas ni al asiento.","El contacto debe ser ligero, elástico y regular.","Una acción de rienda se cede en cuanto el caballo ha respondido."]}},"s2":{"num":"02","titre":"Las distintas familias de embocaduras","intro":"Las embocaduras se clasifican según dos grandes criterios: la forma del cañón (la parte que entra en la boca) y la manera en que se une a las riendas (anillas de filete o camas de bocado). Toca una tarjeta para ver el detalle.","groupes":[{"titre":"Los filetes: acción directa","texte":"Con un filete, la rienda actúa directamente sobre la embocadura, sin efecto de palanca: la presión que siente el caballo corresponde a la tensión de la rienda.","cartes":[{"nom":"Filete de olivas","court":"Las anillas están unidas al cañón mediante olivas.","fonctionnement":"Las olivas impiden que la embocadura gire y se deslice: se mantiene estable en la boca.","caracteristiques":"No pellizca las comisuras. Se elige a menudo para caballos sensibles o que están aprendiendo el contacto.","precautions":"Comprueba el ancho: si la embocadura es demasiado estrecha aprieta los labios; si es demasiado ancha, se descentra."},{"nom":"Filete de patillas","court":"Unas patillas verticales prolongan las anillas a ambos lados de la boca.","fonctionnement":"Las patillas presionan el lateral de la cabeza al usar la rienda de apertura y ayudan al caballo a girar. También impiden que el filete se deslice por la boca.","caracteristiques":"Práctico para caballos jóvenes y para los que se dirigen con dificultad.","precautions":"Las patillas suelen sujetarse a las carrilleras de la cabezada con pequeñas presillas de cuero, para que no se enganchen en ningún sitio."},{"nom":"Filete de anillas en D (Verdun)","court":"Anillas fijas en forma de «D», con un lado recto contra la mejilla.","fonctionnement":"El lado recto de la anilla queda pegado a la mejilla: la embocadura es estable y el caballo nota claramente la rienda de apertura.","caracteristiques":"No pellizca las comisuras. Se usa tanto en doma como en salto y en carreras.","precautions":"Como en cualquier filete de anillas fijas, el ancho debe ser el justo."},{"nom":"Filete de anillas sueltas","court":"Las anillas se deslizan libremente por los orificios del cañón.","fonctionnement":"La embocadura se mueve más en la boca, lo que a menudo anima al caballo a mascar y a relajarse.","caracteristiques":"Es el filete más habitual.","precautions":"Si los orificios están desgastados o la embocadura es demasiado estrecha, las anillas pueden pellizcar las comisuras: revísalas con regularidad."}]},{"titre":"La forma del cañón","texte":"Sea cual sea el tipo de anillas, la forma del cañón cambia la manera en que la presión se reparte en la boca.","cartes":[{"nom":"Cañón recto","court":"Un cañón de una sola pieza, rígido o ligeramente flexible.","fonctionnement":"La presión se reparte sobre la lengua y las barras, por igual a derecha e izquierda.","caracteristiques":"Embocadura estable, a menudo disponible en caucho o en material sintético flexible.","precautions":"Las acciones de una sola rienda son menos precisas que con un cañón articulado."},{"nom":"Articulación simple","court":"Dos partes unidas en el centro por una articulación.","fonctionnement":"Cuando las dos riendas se tensan, el cañón se dobla: presiona la lengua y las barras y puede subir hacia el paladar (efecto «cascanueces»).","caracteristiques":"Permite actuar por separado sobre cada lado de la boca.","precautions":"Con una mano dura o un caballo de paladar bajo, la articulación puede tocar el paladar."},{"nom":"Doble articulación","court":"Tres partes: una pequeña pieza central (anilla, oliva o placa) entre dos cañones.","fonctionnement":"La pieza central se adapta a la lengua: el efecto «cascanueces» se reduce mucho.","caracteristiques":"Suele ser más cómoda para los caballos de lengua gruesa o sensible.","precautions":"La placa central debe quedar plana sobre la lengua: no debe ponerse de lado."}]},{"titre":"Los bocados de palanca","texte":"Estas embocaduras tienen camas. Cuando la rienda tira de la parte baja de la cama, el bocado gira: es el efecto de palanca.","cartes":[{"nom":"Principio de la palanca","court":"Camas, barbada y testera actúan juntas.","fonctionnement":"Al girar, el bocado presiona las barras, la barbada se cierra en el hueco de la barbilla y la testera presiona la nuca.","caracteristiques":"Cuanto más larga es la cama por debajo del cañón, más potente es el efecto con la misma tensión de rienda.","precautions":"La barbada debe estar bien ajustada y las riendas deben usarse con mucha suavidad."},{"nom":"Pelham","court":"Un solo cañón con camas, una barbada y dos pares de riendas.","fonctionnement":"La rienda superior actúa sobre todo como un filete; la inferior añade el efecto de palanca.","caracteristiques":"Reúne en una sola embocadura los efectos del filete y del bocado.","precautions":"Montado con una sola rienda (con una pieza de unión entre las dos anillas), pierde precisión."},{"nom":"Bocado Pessoa (filete holandés)","court":"Un filete con varias anillas superpuestas.","fonctionnement":"Según la anilla en la que se sujete la rienda, el efecto se parece al de un filete o añade palanca.","caracteristiques":"Cuanto más baja es la anilla elegida, más marcado es el efecto de palanca.","precautions":"Reservado a jinetes con una mano segura; el ajuste debe elegirse con el profesor."}]},{"titre":"La brida","texte":"La brida reúne dos embocaduras en la boca del caballo: un filete fino, llamado bridón, y un bocado de brida con camas y su barbada, cada uno con su par de riendas.","cartes":[{"nom":"Bocado y bridón","court":"Dos embocaduras, cuatro riendas.","fonctionnement":"El bridón actúa sobre las comisuras y eleva; el bocado de brida añade el efecto de palanca sobre las barras, la barbilla y la nuca. El jinete dosifica cada rienda por separado.","caracteristiques":"Se utiliza en doma de alto nivel y en atuendo tradicional. Montar con brida forma parte del programa del Nivel 7.","precautions":"Exige una mano independiente, un asiento estable y un caballo ya bien domado con filete."}]}],"matieres":{"titre":"¿Sabías que…?","texte":"Las embocaduras existen en varios materiales: acero inoxidable, cobre o aleaciones que favorecen la salivación, y caucho o materiales sintéticos más flexibles. Una boca que saliva un poco y masca suele ser una boca relajada."}},"s3":{"num":"03","titre":"Anatomía y zonas de acción","intro":"La embocadura descansa en un espacio muy concreto: entre los incisivos y los molares, donde no hay dientes. Actúa sobre varias zonas, que no reaccionan todas de la misma manera.","schemaTitre":"Esquema simplificado de la cabeza de un caballo","schemaNote":"Esquema didáctico, proporciones simplificadas.","zones":[{"nom":"La lengua","texte":"Recibe gran parte de la presión, sobre todo con un cañón recto o de doble articulación."},{"nom":"Las barras","texte":"Parte de la mandíbula inferior sin dientes, entre los incisivos y los molares. Ahí la encía cubre directamente el hueso: es una zona muy sensible."},{"nom":"Las comisuras y los labios","texte":"Las esquinas de la boca. El filete actúa sobre ellas, sobre todo cuando eleva o con la rienda de apertura."},{"nom":"El paladar","texte":"La parte superior de la boca. Una articulación simple que se dobla demasiado puede llegar a tocarlo."},{"nom":"La nuca","texte":"Con un bocado de palanca, la testera transmite presión a la parte alta de la cabeza."},{"nom":"La barbilla","texte":"La barbada de un bocado de camas se coloca en el hueco de la barbilla y presiona ahí cuando el bocado gira."}],"mecaTitre":"Tres formas de actuar","mecanismes":[{"nom":"Presión directa","texte":"Con un filete, la tensión de la rienda llega a la lengua, las barras y las comisuras, en la dirección en la que tira la mano."},{"nom":"Efecto de palanca","texte":"Con camas, el bocado gira: la fuerza se multiplica y se reparte entre las barras, la barbilla y la nuca."},{"nom":"Acción lateral","texte":"Las anillas fijas o las patillas presionan la mejilla opuesta a la rienda de apertura y ayudan al caballo a girar."}]},"s4":{"num":"04","titre":"¿Cómo elegir una embocadura?","intro":"No existe una embocadura «buena» en términos absolutos: existe una embocadura adecuada para un caballo, un jinete y un momento concreto de su trabajo. Estos son los criterios que debes revisar con tu profesor.","criteres":[{"nom":"La boca del caballo","texte":"Su anchura determina la medida de la embocadura. Una lengua gruesa o un paladar bajo suelen pedir un cañón más fino o de doble articulación."},{"nom":"Su sensibilidad","texte":"Un caballo muy sensible suele estar más cómodo con una embocadura estable y suave."},{"nom":"Su nivel de doma","texte":"Un caballo joven empieza con un filete sencillo. Los bocados de palanca y la brida llegan más tarde, con un caballo ya hecho."},{"nom":"La disciplina","texte":"El reglamento de cada disciplina fija las embocaduras autorizadas en competición. Comprueba siempre el reglamento federativo vigente."},{"nom":"La mano del jinete","texte":"Cuanto más potente es una embocadura, más exige una mano fija, suave y elástica, independiente del asiento."},{"nom":"El ajuste y la comodidad","texte":"La mejor embocadura solo funciona bien si tiene la medida adecuada y está ajustada a la altura correcta."}],"important":{"titre":"El consejo del entrenador","texte":"Un bocado más severo nunca sustituye un trabajo de doma correcto. Si tu caballo tira, se apoya o abre la boca, busca primero la causa: tu mano, tu equilibrio, su relajación, sus dientes, el ajuste del equipo. Cambia de embocadura solo con la opinión de tu profesor."}},"s5":{"num":"05","titre":"Ajuste y mantenimiento","intro":"Una embocadura bien elegida pero mal ajustada se vuelve incómoda enseguida. Acostúmbrate a comprobar estos puntos antes de cada sesión.","verifTitre":"Las comprobaciones antes de montar","verifs":["El ancho: la embocadura sobresale aproximadamente medio centímetro por cada lado de la boca, sin apretar los labios.","La altura: con un filete se ven, en general, uno o dos pequeños pliegues en la comisura de los labios. Sin pliegues, el filete está demasiado bajo; con muchos pliegues, demasiado alto.","La barbada: queda plana en el hueco de la barbilla; deben caber dos dedos entre la barbada y la barbilla.","El estado: ninguna arista cortante, ningún desgaste en los orificios de las anillas ni en las articulaciones, ninguna pieza que pellizque.","Los cueros: las carrilleras, las hebillas y las riendas están flexibles y en buen estado."],"entretienTitre":"Después de la sesión","entretien":"Enjuaga la embocadura con agua limpia en cuanto hayas desensillado, antes de que la saliva y la hierba se sequen. Sécala con un paño, déjala secar y cuida los cueros con regularidad.","erreurs":{"titre":"Los errores que debes evitar","points":["Ajustar la altura del filete «a ojo» sin mirar las comisuras.","Seguir usando una embocadura dañada porque «el caballo está acostumbrado».","Apretar la barbada para «tener más freno».","Dejar que la embocadura se seque sucia después de la sesión."]}},"s6":{"num":"06","titre":"Casos especiales","intro":"En el Nivel 5 basta con reconocerlos y entender su principio. Su uso se decide con un profesor.","cartes":[{"nom":"El filete Baucher","court":"Un filete con una pequeña anilla adicional sujeta a la carrillera.","detail":"La embocadura queda suspendida y muy estable en la boca. Va bien a los caballos que juegan mucho con el bocado."},{"nom":"Las embocaduras flexibles","court":"De caucho o de material sintético.","detail":"Suaves y ligeras, van bien a las bocas sensibles o a los caballos jóvenes. Se desgastan antes: comprueba que no estén mordisqueadas ni agrietadas."},{"nom":"El hackamore","court":"Una cabezada sin embocadura.","detail":"Actúa por presión sobre la caña nasal, la barbilla y la nuca, sin nada en la boca. No es por principio una opción «más suave»: mal ajustado, puede ser muy severo."},{"nom":"La muserola","court":"No es una embocadura, pero cambia su efecto.","detail":"Una muserola demasiado apretada impide que el caballo masque y endurece el contacto. Deben caber dos dedos entre la muserola y la caña nasal."}]},"lateral":{"observerTitre":"Para observar","observer":"En tu próxima sesión, fíjate en la boca del caballo: ¿está cerrada y tranquila? ¿Masca un poco? ¿Se ven uno o dos pliegues en las comisuras? Una boca relajada suele indicar un caballo relajado.","defiTitre":"El reto del jinete","defi":"En el guadarnés de tu club, encuentra tres embocaduras diferentes y nómbralas: tipo de anillas, forma del cañón, acción directa o de palanca. Después enseña tu respuesta a tu profesor."},"videos":{"titre":"Para entenderlo mejor en imágenes","v1":"Reconocer las principales familias de embocaduras","v2":"Entender los distintos efectos de un bocado","v3":"Comprobar el ajuste de una embocadura","aVenir":"Vídeo próximamente","tous":"Ver toda la videoteca"},"quiz":{"titre":"Pon a prueba tus conocimientos","texte":"¿Has terminado esta lección? Comprueba lo que has aprendido.","bouton":"Ir al cuestionario","bientot":"Próximamente"}},"fr":{"meta":{"kicker":"Galop 5 · Culture équestre","titre":"Les embouchures","sous":"Comprendre leurs effets et bien les choisir.","duree":"Environ 20 min de lecture","type":"Cours théorique","audio":"Lecture audio","langues":"Disponible dans les 14 langues","retour":"Les cours du Galop 5","progression":"Progression de lecture","sommaire":"Sommaire du cours","photoAVenir":"Photo à venir","agrandir":"Agrandir la photo","fermer":"Fermer","voirPlus":"Voir le détail","voirMoins":"Masquer le détail","fonctionnement":"Fonctionnement","caracteristiques":"À savoir","precautions":"Précautions"},"nav":["Pourquoi","Familles","Anatomie","Choisir","Ajuster","Cas particuliers"],"s1":{"num":"01","titre":"Pourquoi utiliser une embouchure ?","paras":["L'embouchure est la pièce de métal ou de matière souple placée dans la bouche du cheval et reliée aux rênes. Elle transmet au cheval les actions de ta main : c'est l'un des moyens de communication entre toi et lui, avec les jambes, l'assiette et la voix.","Un bon contact, c'est une liaison légère, élastique et constante entre ta main et la bouche du cheval. Ta main accompagne le mouvement de l'encolure, surtout au pas et au galop, pour que le cheval trouve dans l'embouchure un appui stable et rassurant, jamais une gêne.","La bouche du cheval est très sensible. Chaque action de rêne — demi-arrêt, rêne d'ouverture, rêne contraire — doit être brève, mesurée, puis rendue dès que le cheval répond. C'est en cédant au bon moment que la main récompense et que le cheval apprend."],"retenir":{"titre":"À retenir","points":["L'embouchure transmet les actions de la main : elle ne remplace ni les jambes, ni l'assiette.","Le contact doit être léger, élastique et régulier.","Une action de rêne se rend dès que le cheval a répondu."]}},"s2":{"num":"02","titre":"Les différentes familles d'embouchures","intro":"On classe les embouchures selon deux grands critères : la forme du canon (la partie qui entre dans la bouche) et la manière dont il est relié aux rênes (anneaux de filet ou branches de mors). Touche une carte pour découvrir le détail.","groupes":[{"titre":"Les filets : action directe","texte":"Avec un filet, la rêne agit directement sur l'embouchure, sans effet de levier : la pression ressentie par le cheval correspond à la tension de la rêne.","cartes":[{"nom":"Filet à olives","court":"Les anneaux sont fixés au canon par des olives.","fonctionnement":"Les olives empêchent l'embouchure de tourner et de coulisser : elle reste stable dans la bouche.","caracteristiques":"Ne pince pas les commissures. Souvent choisi pour les chevaux sensibles ou qui apprennent le contact.","precautions":"Vérifie la largeur : une embouchure trop étroite serre les lèvres, trop large elle se décentre."},{"nom":"Filet à aiguilles","court":"Des aiguilles verticales prolongent les anneaux de part et d'autre de la bouche.","fonctionnement":"Les aiguilles appuient sur le côté de la tête lors d'une rêne d'ouverture et aident le cheval à tourner. Elles empêchent aussi le mors de glisser dans la bouche.","caracteristiques":"Pratique pour les jeunes chevaux et ceux qui se dirigent difficilement.","precautions":"On fixe souvent les aiguilles aux montants du filet avec de petits passants en cuir, pour qu'elles ne s'accrochent nulle part."},{"nom":"Filet Verdun","court":"Des anneaux fixes en forme de « D », avec un côté droit contre la joue.","fonctionnement":"Le côté droit de l'anneau reste plaqué contre la joue : l'embouchure est stable et le cheval sent nettement la rêne d'ouverture.","caracteristiques":"Ne pince pas les commissures. Utilisé sur le plat comme à l'obstacle et en course.","precautions":"Comme pour tout filet à anneaux fixes, la largeur doit être juste."},{"nom":"Filet à anneaux libres","court":"Les anneaux coulissent librement dans les trous du canon.","fonctionnement":"L'embouchure bouge davantage dans la bouche, ce qui encourage souvent le cheval à mâchonner et à se décontracter.","caracteristiques":"C'est le filet le plus courant.","precautions":"Si les trous sont usés ou l'embouchure trop étroite, les anneaux peuvent pincer les commissures : vérifie-les régulièrement."}]},{"titre":"La forme du canon","texte":"Quel que soit le type d'anneaux, la forme du canon change la façon dont la pression se répartit dans la bouche.","cartes":[{"nom":"Canon droit","court":"Un canon d'une seule pièce, rigide ou légèrement souple.","fonctionnement":"La pression se répartit sur la langue et sur les barres, de façon égale à droite et à gauche.","caracteristiques":"Embouchure stable, souvent proposée en caoutchouc ou en matière synthétique souple.","precautions":"Les actions d'une seule rêne sont moins précises qu'avec un canon brisé."},{"nom":"Simple brisure","court":"Deux parties reliées au centre par une articulation.","fonctionnement":"Quand les deux rênes se tendent, le canon se plie : il presse la langue et les barres et peut remonter vers le palais (effet « casse-noix »).","caracteristiques":"Permet d'agir séparément sur chaque côté de la bouche.","precautions":"Avec une main dure ou un cheval au palais bas, la brisure peut toucher le palais."},{"nom":"Double brisure","court":"Trois parties : un petit élément central (anneau, olive ou plaquette) entre deux canons.","fonctionnement":"L'élément central épouse la langue : l'effet « casse-noix » est très réduit.","caracteristiques":"Souvent plus confortable pour les chevaux à la langue épaisse ou sensible.","precautions":"La plaquette centrale doit rester à plat sur la langue : elle ne doit pas se mettre de travers."}]},{"titre":"Les mors à effet de levier","texte":"Ces embouchures ont des branches. Quand la rêne tire sur le bas de la branche, le mors pivote : c'est l'effet de levier.","cartes":[{"nom":"Principe du levier","court":"Branches, gourmette et têtière agissent ensemble.","fonctionnement":"En pivotant, le mors appuie sur les barres, la gourmette se serre dans le creux du menton et la têtière appuie sur la nuque.","caracteristiques":"Plus la branche sous le canon est longue, plus l'effet est puissant pour une même tension de rêne.","precautions":"La gourmette doit être bien réglée et les rênes utilisées avec une grande douceur."},{"nom":"Pelham","court":"Un seul canon avec des branches, une gourmette et deux paires de rênes.","fonctionnement":"La rêne attachée en haut agit surtout comme un filet ; celle du bas ajoute l'effet de levier.","caracteristiques":"Il réunit en une seule embouchure les effets du filet et du mors.","precautions":"Monté avec une seule rêne (avec une pièce de liaison entre les deux anneaux), il perd en précision."},{"nom":"Mors Pessoa","court":"Un filet à plusieurs anneaux superposés.","fonctionnement":"Selon l'anneau sur lequel la rêne est attachée, l'effet est proche d'un filet ou ajoute un levier.","caracteristiques":"Plus l'anneau choisi est bas, plus l'effet de levier est marqué.","precautions":"À réserver aux cavaliers dont la main est sûre, et le réglage doit être choisi avec l'enseignant."}]},{"titre":"La bride","texte":"La bride réunit deux embouchures dans la bouche du cheval : un filet fin, appelé filet de bride, et un mors de bride à branches avec sa gourmette, chacun avec sa paire de rênes.","cartes":[{"nom":"Mors et filet de bride","court":"Deux embouchures, quatre rênes.","fonctionnement":"Le filet de bride agit sur la commissure et relève ; le mors de bride ajoute l'effet de levier sur les barres, le menton et la nuque. Le cavalier dose chaque rêne séparément.","caracteristiques":"Utilisée en dressage de haut niveau et en tenue traditionnelle. La monte en bride figure au programme du Galop 7.","precautions":"Demande une main indépendante, une assiette stable et un cheval déjà bien dressé au filet."}]}],"matieres":{"titre":"Le savais-tu ?","texte":"Les embouchures existent en plusieurs matières : acier inoxydable, cuivre ou alliages qui favorisent la salivation, caoutchouc et matières synthétiques plus souples. Une bouche qui salive un peu et qui mâchonne est en général une bouche détendue."}},"s3":{"num":"03","titre":"Anatomie et zones d'action","intro":"L'embouchure repose dans un espace bien précis : entre les incisives et les molaires, là où il n'y a pas de dents. Elle agit sur plusieurs zones, qui ne réagissent pas toutes de la même façon.","schemaTitre":"Schéma simplifié d'une tête de cheval","schemaNote":"Schéma pédagogique, proportions simplifiées.","zones":[{"nom":"La langue","texte":"Elle reçoit une grande partie de la pression, surtout avec un canon droit ou à double brisure."},{"nom":"Les barres","texte":"Partie de la mâchoire inférieure sans dents, entre les incisives et les molaires. La gencive y recouvre directement l'os : c'est une zone très sensible."},{"nom":"Les commissures et les lèvres","texte":"Les coins de la bouche. Le filet y agit, surtout quand il relève ou lors d'une rêne d'ouverture."},{"nom":"Le palais","texte":"Le haut de la bouche. Une simple brisure qui se plie trop peut venir le toucher."},{"nom":"La nuque","texte":"Avec un mors à levier, la têtière transmet une pression sur le haut de la tête."},{"nom":"Le menton","texte":"La gourmette d'un mors à branches se place dans le creux du menton et y appuie quand le mors pivote."}],"mecaTitre":"Trois façons d'agir","mecanismes":[{"nom":"Pression directe","texte":"Avec un filet, la tension de la rêne se retrouve sur la langue, les barres et les commissures, dans la direction où tire la main."},{"nom":"Effet de levier","texte":"Avec des branches, le mors pivote : la force est multipliée et se répartit entre les barres, le menton et la nuque."},{"nom":"Action latérale","texte":"Les anneaux fixes ou les aiguilles appuient sur la joue opposée à la rêne d'ouverture et aident le cheval à tourner."}]},"s4":{"num":"04","titre":"Comment choisir une embouchure ?","intro":"Il n'existe pas de « bonne » embouchure dans l'absolu : il existe une embouchure adaptée à un cheval, à un cavalier et à un moment de leur travail. Voici les critères à regarder, avec ton enseignant.","criteres":[{"nom":"La bouche du cheval","texte":"Sa largeur donne la taille de l'embouchure. Une langue épaisse ou un palais bas demandent souvent un canon plus fin ou à double brisure."},{"nom":"Sa sensibilité","texte":"Un cheval très sensible sera souvent plus à l'aise avec une embouchure stable et douce."},{"nom":"Son niveau de dressage","texte":"Un jeune cheval commence au filet simple. Les mors à levier et la bride viennent plus tard, avec un cheval confirmé."},{"nom":"La discipline","texte":"Le règlement de chaque discipline fixe les embouchures autorisées en compétition. Vérifie toujours le règlement fédéral en vigueur."},{"nom":"La main du cavalier","texte":"Plus une embouchure est puissante, plus elle demande une main fixe, liante et indépendante de l'assiette."},{"nom":"L'ajustement et le confort","texte":"La meilleure embouchure ne fonctionne bien que si elle est à la bonne taille et réglée à la bonne hauteur."}],"important":{"titre":"Le conseil du coach","texte":"Un mors plus sévère ne remplace jamais un travail de dressage correct. Si ton cheval tire, s'appuie ou ouvre la bouche, cherche d'abord la cause : ta main, ton équilibre, sa décontraction, ses dents, le réglage du matériel. Change d'embouchure seulement avec l'avis de ton enseignant."}},"s5":{"num":"05","titre":"Ajustement et entretien","intro":"Une embouchure bien choisie mais mal réglée devient vite inconfortable. Prends l'habitude de vérifier ces points avant chaque séance.","verifTitre":"Les vérifications avant de monter","verifs":["La largeur : l'embouchure dépasse d'environ un demi-centimètre de chaque côté de la bouche, sans serrer les lèvres.","La hauteur : avec un filet, on voit en général un ou deux petits plis au coin des lèvres. Sans pli, le filet est trop bas ; avec beaucoup de plis, il est trop haut.","La gourmette : elle est à plat dans le creux du menton ; on doit pouvoir glisser deux doigts entre la gourmette et le menton.","L'état : aucune arête vive, aucune usure aux trous des anneaux ou aux articulations, aucune pièce qui pince.","Les cuirs : les montants, les boucles et les rênes sont souples et en bon état."],"entretienTitre":"Après la séance","entretien":"Rince l'embouchure à l'eau claire dès que tu as dessellé, avant que la salive et l'herbe ne sèchent. Essuie-la, laisse sécher, puis entretiens les cuirs régulièrement.","erreurs":{"titre":"Les erreurs à éviter","points":["Régler la hauteur du filet « au hasard » sans regarder les commissures.","Garder une embouchure abîmée parce que « le cheval y est habitué ».","Serrer la gourmette pour « avoir plus de frein ».","Laisser sécher l'embouchure sale après la séance."]}},"s6":{"num":"06","titre":"Cas particuliers","intro":"Au Galop 5, il suffit de les reconnaître et de comprendre leur principe. Leur emploi se décide avec un enseignant.","cartes":[{"nom":"Le filet Baucher","court":"Un filet dont un petit anneau supplémentaire est fixé au montant.","detail":"L'embouchure reste suspendue et très stable dans la bouche. Elle convient aux chevaux qui jouent beaucoup avec leur mors."},{"nom":"Les embouchures souples","court":"En caoutchouc ou en matière synthétique.","detail":"Douces et légères, elles conviennent aux bouches sensibles ou aux jeunes chevaux. Elles s'usent plus vite : vérifie qu'elles ne sont pas mordillées ou fendues."},{"nom":"Le hackamore","court":"Une bride sans embouchure.","detail":"Il agit par pression sur le chanfrein, le menton et la nuque, sans rien dans la bouche. Ce n'est pas une solution « plus douce » par principe : mal réglé, il peut être très sévère."},{"nom":"La muserolle","court":"Elle n'est pas une embouchure, mais elle change son effet.","detail":"Une muserolle trop serrée empêche le cheval de mâchonner et rend le contact dur. On doit pouvoir glisser deux doigts entre la muserolle et le chanfrein."}]},"lateral":{"observerTitre":"À observer","observer":"Lors de ta prochaine séance, regarde la bouche du cheval : est-elle fermée et calme ? Mâchonne-t-il un peu ? Voit-on un ou deux plis aux commissures ? Une bouche détendue montre souvent un cheval détendu.","defiTitre":"Le défi du cavalier","defi":"Dans la sellerie de ton club, retrouve trois embouchures différentes et nomme-les : type d'anneaux, forme du canon, action directe ou levier. Montre ensuite ta réponse à ton enseignant."},"videos":{"titre":"Pour mieux comprendre en images","v1":"Reconnaître les principales familles d'embouchures","v2":"Comprendre les différents effets d'un mors","v3":"Vérifier l'ajustement d'une embouchure","aVenir":"Vidéo à venir","tous":"Voir toute la vidéothèque"},"quiz":{"titre":"Teste tes connaissances","texte":"Tu as terminé cette leçon ? Vérifie ce que tu as retenu.","bouton":"Accéder au quiz","bientot":"Bientôt"}},"it":{"meta":{"kicker":"Livello 5 · Cultura equestre","titre":"Le imboccature","sous":"Capire i loro effetti e sceglierle bene.","duree":"Circa 20 min di lettura","type":"Lezione teorica","audio":"Ascolta la lezione","langues":"Disponibile in tutte le 14 lingue","retour":"Le lezioni del Livello 5","progression":"Avanzamento della lettura","sommaire":"Indice della lezione","photoAVenir":"Foto in arrivo","agrandir":"Ingrandisci la foto","fermer":"Chiudi","voirPlus":"Vedi i dettagli","voirMoins":"Nascondi i dettagli","fonctionnement":"Come funziona","caracteristiques":"Da sapere","precautions":"Precauzioni"},"nav":["Perché","Famiglie","Anatomia","Scegliere","Regolare","Casi particolari"],"s1":{"num":"01","titre":"Perché usare un'imboccatura?","paras":["L'imboccatura è il pezzo di metallo o di materiale morbido che si mette in bocca al cavallo ed è collegato alle redini. Trasmette al cavallo le azioni della tua mano: è uno dei mezzi di comunicazione tra te e lui, insieme alle gambe, all'assetto e alla voce.","Un buon contatto è un collegamento leggero, elastico e costante tra la tua mano e la bocca del cavallo. La tua mano accompagna il movimento dell'incollatura, soprattutto al passo e al galoppo, perché il cavallo trovi nell'imboccatura un appoggio stabile e rassicurante, mai un fastidio.","La bocca del cavallo è molto sensibile. Ogni azione di redine — mezza fermata, redine d'apertura, redine contraria — deve essere breve, misurata, e poi ceduta appena il cavallo risponde. È cedendo al momento giusto che la mano premia e il cavallo impara."],"retenir":{"titre":"Da ricordare","points":["L'imboccatura trasmette le azioni della mano: non sostituisce né le gambe né l'assetto.","Il contatto deve essere leggero, elastico e regolare.","Un'azione di redine si cede appena il cavallo ha risposto."]}},"s2":{"num":"02","titre":"Le diverse famiglie di imboccature","intro":"Le imboccature si classificano secondo due grandi criteri: la forma del cannone (la parte che entra in bocca) e il modo in cui è collegato alle redini (anelli da filetto o aste da morso). Tocca una scheda per scoprire i dettagli.","groupes":[{"titre":"I filetti: azione diretta","texte":"Con un filetto, la redine agisce direttamente sull'imboccatura, senza effetto leva: la pressione che sente il cavallo corrisponde alla tensione della redine.","cartes":[{"nom":"Filetto a oliva","court":"Gli anelli sono fissati al cannone tramite olive.","fonctionnement":"Le olive impediscono all'imboccatura di ruotare e di scorrere: resta stabile in bocca.","caracteristiques":"Non pizzica le commessure. Spesso scelto per cavalli sensibili o che stanno imparando il contatto.","precautions":"Controlla la larghezza: un'imboccatura troppo stretta stringe le labbra, troppo larga si decentra."},{"nom":"Filetto a stanghette","court":"Delle stanghette verticali prolungano gli anelli ai due lati della bocca.","fonctionnement":"Le stanghette premono sul lato della testa quando usi la redine d'apertura e aiutano il cavallo a girare. Impediscono anche al filetto di scivolare attraverso la bocca.","caracteristiques":"Pratico per i cavalli giovani e per quelli difficili da dirigere.","precautions":"Spesso le stanghette si fissano ai montanti della testiera con piccoli passanti di cuoio, perché non si impiglino da nessuna parte."},{"nom":"Filetto a D (Verdun)","court":"Anelli fissi a forma di «D», con un lato dritto contro la guancia.","fonctionnement":"Il lato dritto dell'anello resta aderente alla guancia: l'imboccatura è stabile e il cavallo sente chiaramente la redine d'apertura.","caracteristiques":"Non pizzica le commessure. Usato sia in piano sia in salto ostacoli e nelle corse.","precautions":"Come per ogni filetto ad anelli fissi, la larghezza deve essere giusta."},{"nom":"Filetto ad anelli mobili","court":"Gli anelli scorrono liberamente nei fori del cannone.","fonctionnement":"L'imboccatura si muove di più in bocca, il che spesso incoraggia il cavallo a masticare e a decontrarsi.","caracteristiques":"È il filetto più comune.","precautions":"Se i fori sono consumati o l'imboccatura è troppo stretta, gli anelli possono pizzicare le commessure: controllali regolarmente."}]},{"titre":"La forma del cannone","texte":"Qualunque sia il tipo di anelli, la forma del cannone cambia il modo in cui la pressione si distribuisce in bocca.","cartes":[{"nom":"Cannone dritto","court":"Un cannone in un solo pezzo, rigido o leggermente flessibile.","fonctionnement":"La pressione si distribuisce sulla lingua e sulle barre, in modo uguale a destra e a sinistra.","caracteristiques":"Imboccatura stabile, spesso proposta in gomma o in materiale sintetico morbido.","precautions":"Le azioni di una sola redine sono meno precise che con un cannone snodato."},{"nom":"Snodo singolo","court":"Due parti unite al centro da uno snodo.","fonctionnement":"Quando le due redini si tendono, il cannone si piega: preme sulla lingua e sulle barre e può risalire verso il palato (effetto «schiaccianoci»).","caracteristiques":"Permette di agire separatamente su ciascun lato della bocca.","precautions":"Con una mano dura o un cavallo dal palato basso, lo snodo può toccare il palato."},{"nom":"Doppio snodo","court":"Tre parti: un piccolo elemento centrale (anello, oliva o placchetta) tra due cannoni.","fonctionnement":"L'elemento centrale segue la forma della lingua: l'effetto «schiaccianoci» è molto ridotto.","caracteristiques":"Spesso più comodo per i cavalli con la lingua spessa o sensibile.","precautions":"La placchetta centrale deve restare piatta sulla lingua: non deve mettersi di traverso."}]},{"titre":"I morsi a effetto leva","texte":"Queste imboccature hanno delle aste. Quando la redine tira sulla parte bassa dell'asta, il morso ruota: è l'effetto leva.","cartes":[{"nom":"Il principio della leva","court":"Aste, barbozzale e testiera agiscono insieme.","fonctionnement":"Ruotando, il morso preme sulle barre, il barbozzale si stringe nel barbozzo e la testiera preme sulla nuca.","caracteristiques":"Più l'asta sotto il cannone è lunga, più l'effetto è potente a parità di tensione della redine.","precautions":"Il barbozzale deve essere ben regolato e le redini usate con grande delicatezza."},{"nom":"Pelham","court":"Un solo cannone con aste, un barbozzale e due paia di redini.","fonctionnement":"La redine attaccata in alto agisce soprattutto come un filetto; quella in basso aggiunge l'effetto leva.","caracteristiques":"Riunisce in un'unica imboccatura gli effetti del filetto e del morso.","precautions":"Montato con una sola redine (con un raccordo tra i due anelli), perde in precisione."},{"nom":"Morso Pessoa (filetto olandese)","court":"Un filetto con diversi anelli sovrapposti.","fonctionnement":"A seconda dell'anello a cui è attaccata la redine, l'effetto è simile a quello di un filetto oppure aggiunge una leva.","caracteristiques":"Più l'anello scelto è basso, più l'effetto leva è marcato.","precautions":"Da riservare ai cavalieri con una mano sicura; la regolazione va scelta con l'istruttore."}]},{"titre":"La briglia","texte":"La briglia riunisce due imboccature nella bocca del cavallo: un filetto sottile, chiamato filetto da briglia (bridoncino), e un morso da briglia con aste e barbozzale, ognuno con il suo paio di redini.","cartes":[{"nom":"Morso e filetto da briglia","court":"Due imboccature, quattro redini.","fonctionnement":"Il filetto da briglia agisce sulle commessure e solleva; il morso da briglia aggiunge l'effetto leva su barre, barbozzo e nuca. Il cavaliere dosa ogni redine separatamente.","caracteristiques":"Usata nel dressage di alto livello e in tenuta tradizionale. Montare in briglia fa parte del programma del Livello 7.","precautions":"Richiede una mano indipendente, un assetto stabile e un cavallo già ben addestrato al filetto."}]}],"matieres":{"titre":"Lo sapevi?","texte":"Le imboccature esistono in vari materiali: acciaio inossidabile, rame o leghe che favoriscono la salivazione, gomma e materiali sintetici più morbidi. Una bocca che saliva un po' e mastica è in genere una bocca rilassata."}},"s3":{"num":"03","titre":"Anatomia e zone d'azione","intro":"L'imboccatura poggia in uno spazio ben preciso: tra gli incisivi e i molari, dove non ci sono denti. Agisce su diverse zone, che non reagiscono tutte allo stesso modo.","schemaTitre":"Schema semplificato della testa di un cavallo","schemaNote":"Schema didattico, proporzioni semplificate.","zones":[{"nom":"La lingua","texte":"Riceve gran parte della pressione, soprattutto con un cannone dritto o a doppio snodo."},{"nom":"Le barre","texte":"Parte della mandibola senza denti, tra gli incisivi e i molari. Lì la gengiva ricopre direttamente l'osso: è una zona molto sensibile."},{"nom":"Le commessure e le labbra","texte":"Gli angoli della bocca. Il filetto agisce lì, soprattutto quando solleva o con la redine d'apertura."},{"nom":"Il palato","texte":"La parte alta della bocca. Uno snodo singolo che si piega troppo può arrivare a toccarlo."},{"nom":"La nuca","texte":"Con un morso a leva, la testiera trasmette una pressione sulla parte alta della testa."},{"nom":"Il barbozzo","texte":"Il barbozzale di un morso ad aste si posiziona nell'incavo del mento e vi preme quando il morso ruota."}],"mecaTitre":"Tre modi di agire","mecanismes":[{"nom":"Pressione diretta","texte":"Con un filetto, la tensione della redine arriva sulla lingua, sulle barre e sulle commessure, nella direzione in cui tira la mano."},{"nom":"Effetto leva","texte":"Con le aste, il morso ruota: la forza si moltiplica e si distribuisce tra barre, barbozzo e nuca."},{"nom":"Azione laterale","texte":"Gli anelli fissi o le stanghette premono sulla guancia opposta alla redine d'apertura e aiutano il cavallo a girare."}]},"s4":{"num":"04","titre":"Come scegliere un'imboccatura?","intro":"Non esiste un'imboccatura «buona» in assoluto: esiste un'imboccatura adatta a un cavallo, a un cavaliere e a un momento del loro lavoro. Ecco i criteri da valutare con il tuo istruttore.","criteres":[{"nom":"La bocca del cavallo","texte":"La sua larghezza determina la misura dell'imboccatura. Una lingua spessa o un palato basso richiedono spesso un cannone più sottile o a doppio snodo."},{"nom":"La sua sensibilità","texte":"Un cavallo molto sensibile si troverà spesso meglio con un'imboccatura stabile e dolce."},{"nom":"Il suo livello di addestramento","texte":"Un cavallo giovane inizia con un filetto semplice. I morsi a leva e la briglia arrivano più tardi, con un cavallo esperto."},{"nom":"La disciplina","texte":"Il regolamento di ogni disciplina stabilisce le imboccature ammesse in gara. Controlla sempre il regolamento federale in vigore."},{"nom":"La mano del cavaliere","texte":"Più un'imboccatura è potente, più richiede una mano ferma, morbida e indipendente dall'assetto."},{"nom":"Regolazione e comfort","texte":"Anche la migliore imboccatura funziona bene solo se è della misura giusta e regolata all'altezza giusta."}],"important":{"titre":"Il consiglio del coach","texte":"Un morso più severo non sostituisce mai un corretto lavoro di addestramento. Se il tuo cavallo tira, si appoggia o apre la bocca, cerca prima la causa: la tua mano, il tuo equilibrio, la sua decontrazione, i suoi denti, la regolazione della bardatura. Cambia imboccatura solo su consiglio del tuo istruttore."}},"s5":{"num":"05","titre":"Regolazione e manutenzione","intro":"Un'imboccatura scelta bene ma regolata male diventa presto scomoda. Prendi l'abitudine di controllare questi punti prima di ogni sessione.","verifTitre":"I controlli prima di montare","verifs":["La larghezza: l'imboccatura sporge di circa mezzo centimetro da ogni lato della bocca, senza stringere le labbra.","L'altezza: con un filetto si vedono in genere una o due piccole pieghe all'angolo delle labbra. Senza pieghe il filetto è troppo basso; con molte pieghe è troppo alto.","Il barbozzale: è piatto nell'incavo del mento; si devono poter infilare due dita tra il barbozzale e il mento.","Lo stato: nessuno spigolo vivo, nessuna usura nei fori degli anelli o negli snodi, nessun pezzo che pizzica.","I cuoi: montanti, fibbie e redini sono morbidi e in buono stato."],"entretienTitre":"Dopo la sessione","entretien":"Sciacqua l'imboccatura con acqua pulita appena hai dissellato, prima che saliva ed erba si secchino. Asciugala, lasciala asciugare all'aria, poi cura regolarmente i cuoi.","erreurs":{"titre":"Gli errori da evitare","points":["Regolare l'altezza del filetto «a caso» senza guardare le commessure.","Tenere un'imboccatura rovinata perché «il cavallo ci è abituato».","Stringere il barbozzale per «avere più freno».","Lasciare asciugare l'imboccatura sporca dopo la sessione."]}},"s6":{"num":"06","titre":"Casi particolari","intro":"Al Livello 5 basta riconoscerli e capirne il principio. Il loro uso si decide con un istruttore.","cartes":[{"nom":"Il filetto Baucher","court":"Un filetto con un piccolo anello in più fissato al montante.","detail":"L'imboccatura resta sospesa e molto stabile in bocca. È adatta ai cavalli che giocano molto con l'imboccatura."},{"nom":"Le imboccature morbide","court":"In gomma o in materiale sintetico.","detail":"Dolci e leggere, sono adatte alle bocche sensibili o ai cavalli giovani. Si consumano più in fretta: controlla che non siano mordicchiate o spaccate."},{"nom":"L'hackamore","court":"Una testiera senza imboccatura.","detail":"Agisce con una pressione sul naso, sul barbozzo e sulla nuca, senza niente in bocca. Non è per principio una soluzione «più dolce»: se regolato male, può essere molto severo."},{"nom":"La capezzina","court":"Non è un'imboccatura, ma ne cambia l'effetto.","detail":"Una capezzina troppo stretta impedisce al cavallo di masticare e rende il contatto duro. Si devono poter infilare due dita tra la capezzina e il naso."}]},"lateral":{"observerTitre":"Da osservare","observer":"Nella tua prossima sessione, guarda la bocca del cavallo: è chiusa e tranquilla? Mastica un po'? Si vedono una o due pieghe alle commessure? Una bocca rilassata indica spesso un cavallo rilassato.","defiTitre":"La sfida del cavaliere","defi":"Nella selleria del tuo circolo, trova tre imboccature diverse e dagli un nome: tipo di anelli, forma del cannone, azione diretta o a leva. Poi mostra la tua risposta al tuo istruttore."},"videos":{"titre":"Per capire meglio con le immagini","v1":"Riconoscere le principali famiglie di imboccature","v2":"Capire i diversi effetti di un morso","v3":"Controllare la regolazione di un'imboccatura","aVenir":"Video in arrivo","tous":"Vedi tutta la videoteca"},"quiz":{"titre":"Metti alla prova le tue conoscenze","texte":"Hai finito questa lezione? Verifica cosa hai imparato.","bouton":"Vai al quiz","bientot":"Presto disponibile"}},"ja":{"meta":{"kicker":"ギャロップ5 · 馬術の基礎知識","titre":"ハミ","sous":"その効果を理解して、正しく選ぼう。","duree":"約20分で読めるよ","type":"理論レッスン","audio":"音声で聞く","langues":"14の言語で読めるよ","retour":"ギャロップ5のレッスン","progression":"読書の進み具合","sommaire":"レッスンの目次","photoAVenir":"写真は準備中","agrandir":"写真を拡大","fermer":"閉じる","voirPlus":"詳しく見る","voirMoins":"詳細を閉じる","fonctionnement":"しくみ","caracteristiques":"知っておこう","precautions":"注意点"},"nav":["なぜ使う？","種類","体のしくみ","選び方","調整","特別なケース"],"s1":{"num":"01","titre":"なぜハミを使うの？","paras":["ハミは馬の口の中に入れる金属や柔らかい素材のパーツで、手綱につながっているよ。きみの手の動きを馬に伝えるもので、脚・騎座・声と並んで、きみと馬とのコミュニケーション手段のひとつなんだ。","よいコンタクトとは、きみの手と馬の口とのあいだの、軽くて弾力があって一定したつながりのこと。とくに常歩と駈歩では、手で頸の動きについていこう。そうすれば馬はハミに、邪魔なものではなく、安定した安心できる支えを感じられるよ。","馬の口はとても敏感。半減却、開き手綱、押し手綱など、手綱の扶助はどれも短く、加減して行い、馬が応えたらすぐにゆるめよう。ちょうどいいタイミングで譲ることで、手が馬をほめることになり、馬は学んでいくんだ。"],"retenir":{"titre":"ここがポイント","points":["ハミは手の扶助を伝えるもの。脚や騎座の代わりにはならないよ。","コンタクトは軽く、弾力があって、一定であること。","手綱の扶助は、馬が応えたらすぐにゆるめよう。"]}},"s2":{"num":"02","titre":"ハミのいろいろな種類","intro":"ハミは大きく2つの基準で分類されるよ。ハミ身（口に入る部分）の形と、手綱へのつながり方（水勒のリングか、大勒ハミのシャンクか）。カードをタップして詳しく見てみよう。","groupes":[{"titre":"水勒ハミ：直接の作用","texte":"水勒ハミでは、手綱がてこ作用なしで直接ハミに働くよ。馬が感じる圧力は、手綱の張りと同じなんだ。","cartes":[{"nom":"エッグバットハミ","court":"リングがオリーブ形のつなぎ目でハミ身に固定されている。","fonctionnement":"オリーブ形のつなぎ目がハミの回転や横すべりを防ぐので、口の中で安定しているよ。","caracteristiques":"口角をはさまない。敏感な馬や、コンタクトを覚えている途中の馬によく選ばれるよ。","precautions":"幅をチェックしよう。狭すぎると唇を締めつけ、広すぎると中心からずれてしまうよ。"},{"nom":"フルチークハミ","court":"縦のバー（チーク）がリングから口の両側に伸びている。","fonctionnement":"開き手綱のとき、チークが頭の横を押して、馬が曲がるのを助けるよ。ハミが口の中ですべるのも防いでくれる。","caracteristiques":"若い馬や、ハンドリングが難しい馬に便利。","precautions":"チークがどこかに引っかからないように、小さな革のキーパーで頬革に留めることが多いよ。"},{"nom":"Dリングハミ（ヴェルダン）","court":"「D」の形をした固定リングで、まっすぐな辺が頬に当たる。","fonctionnement":"リングのまっすぐな辺が頬にぴったりつくので、ハミが安定して、馬は開き手綱をはっきり感じられるよ。","caracteristiques":"口角をはさまない。フラットワークでも障害でも、競馬でも使われているよ。","precautions":"リングが固定された水勒ハミはどれもそうだけど、幅がぴったり合っていることが大切。"},{"nom":"ルーズリングハミ","court":"リングがハミ身の穴の中を自由に動く。","fonctionnement":"ハミが口の中でよく動くので、馬がハミを噛んでリラックスしやすくなることが多いよ。","caracteristiques":"いちばん一般的な水勒ハミ。","precautions":"穴がすり減っていたり、ハミが狭すぎたりすると、リングが口角をはさむことがあるよ。こまめにチェックしよう。"}]},{"titre":"ハミ身の形","texte":"リングの種類に関係なく、ハミ身の形によって口の中での圧力のかかり方が変わるよ。","cartes":[{"nom":"ストレートバー（棒ハミ）","court":"一本もののハミ身で、硬いものと少ししなるものがある。","fonctionnement":"圧力は舌と歯槽間縁（バー）に、左右均等にかかるよ。","caracteristiques":"安定したハミで、ゴムや柔らかい合成素材のものが多いよ。","precautions":"片方の手綱だけの扶助は、ジョイントのあるハミより正確さが落ちるよ。"},{"nom":"シングルジョイント","court":"2つのパーツが中央の関節でつながっている。","fonctionnement":"両方の手綱が張ると、ハミ身が折れ曲がって舌と歯槽間縁を押し、口蓋のほうへ持ち上がることがあるよ（「くるみ割り」効果）。","caracteristiques":"口の左右それぞれに別々に働きかけられる。","precautions":"手が硬かったり、口蓋の低い馬だったりすると、関節部分が口蓋に当たることがあるよ。"},{"nom":"ダブルジョイント","court":"3つのパーツ：2本のハミ身のあいだに小さな中央パーツ（リング、オリーブ、またはプレート）。","fonctionnement":"中央パーツが舌の形に沿うので、「くるみ割り」効果がかなり小さくなるよ。","caracteristiques":"舌が厚い馬や敏感な馬には、こちらのほうが快適なことが多いよ。","precautions":"中央のプレートは舌の上で平らになっていないといけない。斜めになってはダメだよ。"}]},{"titre":"てこ作用のあるハミ","texte":"これらのハミにはシャンク（ハミ枝）があるよ。手綱がシャンクの下のほうを引くと、ハミが回転する。これがてこ作用だよ。","cartes":[{"nom":"てこの原理","court":"シャンク、大勒鎖（カーブチェーン）、項革がいっしょに働く。","fonctionnement":"ハミが回転すると、歯槽間縁を押し、大勒鎖があごの溝で締まり、項革がうなじ（ポール）を押すよ。","caracteristiques":"ハミ身から下のシャンクが長いほど、同じ手綱の張りでも効果は強くなるよ。","precautions":"大勒鎖をきちんと調整して、手綱はとてもやさしく使おう。"},{"nom":"ペラム","court":"シャンク、大勒鎖、2組の手綱がついた、ハミ身が1本のハミ。","fonctionnement":"上につけた手綱はおもに水勒のように働き、下の手綱がてこ作用を加えるよ。","caracteristiques":"水勒ハミと大勒ハミの効果を、ひとつのハミにまとめたもの。","precautions":"手綱1本で使う（2つのリングをつなぐ連結革を使う）と、正確さが落ちるよ。"},{"nom":"ペソアハミ","court":"リングが何段も重なった水勒ハミ。","fonctionnement":"手綱をどのリングにつけるかで、水勒に近い効果になったり、てこ作用が加わったりするよ。","caracteristiques":"選ぶリングが下になるほど、てこ作用ははっきり強くなるよ。","precautions":"手がしっかり安定した騎手向け。調整は先生といっしょに決めよう。"}]},{"titre":"大勒","texte":"大勒は馬の口に2つのハミを入れるよ。小勒ハミ（ブラドゥーン）と呼ばれる細い水勒ハミと、シャンクと大勒鎖のついた大勒ハミ（カーブ）。それぞれに1組ずつ手綱がつくんだ。","cartes":[{"nom":"大勒ハミと小勒ハミ","court":"ハミが2つ、手綱が4本。","fonctionnement":"小勒ハミは口角に働いて頭を上げさせ、大勒ハミは歯槽間縁・あご・うなじにてこ作用を加えるよ。騎手はそれぞれの手綱を別々に加減するんだ。","caracteristiques":"ハイレベルな馬場馬術や伝統的な服装で使われるよ。大勒での騎乗はギャロップ7のプログラムに入っているよ。","precautions":"独立した手、安定した騎座、そして水勒ですでによく調教された馬が必要だよ。"}]}],"matieres":{"titre":"知ってた？","texte":"ハミにはいろいろな素材があるよ。ステンレス、唾液を出しやすくする銅や合金、もっと柔らかいゴムや合成素材。少し唾液が出てハミを噛んでいる口は、たいていリラックスした口なんだ。"}},"s3":{"num":"03","titre":"体のしくみとハミが作用する部位","intro":"ハミはとても決まった場所に収まるよ。切歯と臼歯のあいだの、歯がないところ。ハミはいくつもの部位に作用するけど、どこも同じように反応するわけじゃないんだ。","schemaTitre":"馬の頭のかんたんな図","schemaNote":"学習用の図で、比率は簡略化しているよ。","zones":[{"nom":"舌","texte":"圧力の大部分を受けるところ。とくにストレートバーやダブルジョイントのハミのときにそうだよ。"},{"nom":"歯槽間縁（バー）","texte":"下あごの、切歯と臼歯のあいだの歯がない部分。歯ぐきが骨を直接おおっているので、とても敏感なところだよ。"},{"nom":"口角と唇","texte":"口の両端。水勒ハミはここに作用するよ。とくに頭を上げさせるときや、開き手綱のときにね。"},{"nom":"口蓋","texte":"口の上の部分。シングルジョイントが曲がりすぎると、ここに当たることがあるよ。"},{"nom":"うなじ（ポール）","texte":"てこ作用のあるハミでは、項革が頭の上のほうに圧力を伝えるよ。"},{"nom":"あご","texte":"シャンクのあるハミの大勒鎖はあごの溝に収まって、ハミが回転するとそこを押すよ。"}],"mecaTitre":"3つの作用のしかた","mecanismes":[{"nom":"直接の圧力","texte":"水勒ハミでは、手綱の張りが舌・歯槽間縁・口角に、手が引く方向そのままに伝わるよ。"},{"nom":"てこ作用","texte":"シャンクがあるとハミが回転して、力が大きくなり、歯槽間縁・あご・うなじに分散されるよ。"},{"nom":"横からの作用","texte":"固定リングやフルチークのバーが、開き手綱と反対側の頬を押して、馬が曲がるのを助けるよ。"}]},"s4":{"num":"04","titre":"ハミはどう選ぶ？","intro":"どんな場合にも「正しい」ハミなんてないよ。あるのは、その馬、その騎手、そのトレーニングの時期に合ったハミ。先生といっしょに見るべきポイントはこれだよ。","criteres":[{"nom":"馬の口","texte":"口の幅でハミのサイズが決まるよ。舌が厚かったり口蓋が低かったりする馬には、細めのハミ身やダブルジョイントが向いていることが多いよ。"},{"nom":"敏感さ","texte":"とても敏感な馬は、安定したやさしいハミのほうが楽なことが多いよ。"},{"nom":"調教レベル","texte":"若い馬はシンプルな水勒ハミから始めるよ。てこ作用のあるハミや大勒は、もっとあと、経験を積んだ馬になってから。"},{"nom":"競技種目","texte":"競技で使えるハミは、各種目の規程で決められているよ。最新の連盟規程をいつも確認しよう。"},{"nom":"騎手の手","texte":"強いハミほど、安定してやわらかく、騎座から独立した手が必要になるよ。"},{"nom":"フィッティングと快適さ","texte":"どんなにいいハミでも、サイズが合っていて正しい高さに調整されていなければ、うまく働かないよ。"}],"important":{"titre":"コーチからのアドバイス","texte":"強いハミが、正しい調教の代わりになることは絶対にないよ。馬が引っぱる、ハミにもたれる、口を開けるなら、まず原因を探そう。きみの手、きみのバランス、馬のリラックス、歯、馬具の調整。ハミを替えるのは、先生の意見を聞いてからにしよう。"}},"s5":{"num":"05","titre":"調整と手入れ","intro":"よく選んだハミでも、調整が悪いとすぐに不快なものになってしまうよ。毎回の騎乗前に、これらのポイントをチェックする習慣をつけよう。","verifTitre":"乗る前のチェック","verifs":["幅：ハミが口の両側から約5ミリずつ出ていて、唇を締めつけていないこと。","高さ：水勒ハミなら、ふつうは唇の端に小さなしわが1〜2本見えるよ。しわがなければ低すぎ、しわがたくさんあれば高すぎ。","大勒鎖：あごの溝に平らに収まっていること。大勒鎖とあごのあいだに指が2本入るようにしよう。","状態：鋭い角がないこと、リングの穴や関節がすり減っていないこと、はさむようなパーツがないこと。","革具：頬革、尾錠、手綱がしなやかで、状態がいいこと。"],"entretienTitre":"騎乗のあと","entretien":"鞍をはずしたら、唾液や草が乾く前に、すぐにハミを真水ですすごう。ふいて乾かし、革具も定期的に手入れしよう。","erreurs":{"titre":"やってはいけないこと","points":["口角を見ないで、水勒ハミの高さを「なんとなく」調整する。","「馬が慣れているから」と、傷んだハミを使い続ける。","「もっと効かせたい」からと、大勒鎖をきつくする。","騎乗のあと、汚れたままのハミを乾かしてしまう。"]}},"s6":{"num":"06","titre":"特別なケース","intro":"ギャロップ5では、見分けられて、そのしくみがわかれば十分。使うかどうかは先生といっしょに決めよう。","cartes":[{"nom":"ボシェハミ","court":"小さな追加のリングが頬革に固定された水勒ハミ。","detail":"ハミが口の中で吊られた状態になって、とても安定するよ。ハミでよく遊ぶ馬に向いているよ。"},{"nom":"柔らかいハミ","court":"ゴムや合成素材でできている。","detail":"やさしくて軽いので、敏感な口や若い馬に向いているよ。すり減るのが早いから、噛まれた跡や割れがないかチェックしよう。"},{"nom":"ハックモア","court":"ハミのない頭絡。","detail":"口の中には何も入れずに、鼻梁・あご・うなじへの圧力で働くよ。もともと「よりやさしい」方法というわけじゃない。調整が悪いと、とても強く効いてしまうこともあるよ。"},{"nom":"鼻革","court":"ハミではないけど、ハミの効果を変えるもの。","detail":"鼻革がきつすぎると、馬がハミを噛めなくなって、コンタクトが硬くなるよ。鼻革と鼻梁のあいだに指が2本入るようにしよう。"}]},"lateral":{"observerTitre":"観察してみよう","observer":"次の騎乗のとき、馬の口を見てみよう。口は閉じていて落ち着いている？少しハミを噛んでいる？口角に1〜2本のしわが見える？リラックスした口は、たいていリラックスした馬のしるしだよ。","defiTitre":"ライダーへのチャレンジ","defi":"クラブの馬具室で、違うハミを3つ見つけて名前を言ってみよう。リングの種類、ハミ身の形、直接の作用かてこ作用か。そのあと、答えを先生に見せてね。"},"videos":{"titre":"映像でもっとよく理解しよう","v1":"おもなハミの種類を見分ける","v2":"ハミのいろいろな効果を理解する","v3":"ハミのフィッティングを確認する","aVenir":"動画は準備中","tous":"ビデオライブラリをすべて見る"},"quiz":{"titre":"知識をテストしよう","texte":"このレッスンは終わった？覚えたことを確かめてみよう。","bouton":"クイズへ進む","bientot":"もうすぐ"}},"ko":{"meta":{"kicker":"Galop 5 · 승마 교양","titre":"재갈","sous":"재갈의 효과를 이해하고 제대로 골라요.","duree":"읽는 데 약 20분","type":"이론 수업","audio":"오디오로 듣기","langues":"14개 언어 모두 지원","retour":"Galop 5 수업","progression":"읽기 진행률","sommaire":"수업 목차","photoAVenir":"사진 준비 중","agrandir":"사진 크게 보기","fermer":"닫기","voirPlus":"자세히 보기","voirMoins":"자세히 숨기기","fonctionnement":"작동 원리","caracteristiques":"알아 두기","precautions":"주의할 점"},"nav":["왜 쓸까","종류","해부","고르기","조절","특별한 경우"],"s1":{"num":"01","titre":"왜 재갈을 쓸까요?","paras":["재갈은 말의 입 안에 들어가고 고삐와 연결된 금속이나 부드러운 소재의 부품이에요. 네 손의 동작을 말에게 전달해요. 다리, 기좌, 목소리와 함께 너와 말 사이의 소통 수단 중 하나예요.","좋은 컨택은 네 손과 말의 입 사이의 가볍고, 탄력 있고, 일정한 연결이에요. 특히 평보와 구보에서는 손이 목의 움직임을 따라가 줘야 말이 재갈에서 불편함이 아니라 안정되고 안심되는 지지를 느껴요.","말의 입은 아주 예민해요. 하프 홀트, 열어 주는 고삐, 반대 고삐 같은 모든 고삐 동작은 짧고 적당하게 하고, 말이 반응하면 바로 풀어 줘야 해요. 알맞은 순간에 양보해야 손이 말에게 보상을 주고, 말이 배우게 돼요."],"retenir":{"titre":"기억해요","points":["재갈은 손의 동작을 전달해요. 다리나 기좌를 대신하지는 않아요.","컨택은 가볍고, 탄력 있고, 일정해야 해요.","말이 반응하면 고삐 동작은 바로 풀어 줘요."]}},"s2":{"num":"02","titre":"재갈의 여러 종류","intro":"재갈은 크게 두 가지 기준으로 나눠요. 마우스피스(입 안에 들어가는 부분)의 모양, 그리고 고삐와 연결되는 방식(수륵 링인지 대륵 재갈의 샹크인지)이에요. 카드를 눌러서 자세한 내용을 확인해 봐요.","groupes":[{"titre":"수륵: 직접 작용","texte":"수륵은 지렛대 효과 없이 고삐가 재갈에 직접 작용해요. 말이 느끼는 압력은 고삐의 당김과 같아요.","cartes":[{"nom":"에그버트 수륵","court":"링이 올리브 모양 이음새로 마우스피스에 고정되어 있어요.","fonctionnement":"올리브 모양 이음새가 재갈이 돌거나 옆으로 미끄러지는 걸 막아 줘서 입 안에서 안정적이에요.","caracteristiques":"입꼬리를 집지 않아요. 예민한 말이나 컨택을 배우는 중인 말에게 자주 선택돼요.","precautions":"폭을 확인해요. 너무 좁으면 입술을 조이고, 너무 넓으면 중심에서 벗어나요."},{"nom":"풀치크 수륵","court":"세로 막대(치크)가 링에서 입 양옆으로 뻗어 있어요.","fonctionnement":"열어 주는 고삐를 쓸 때 치크가 머리 옆을 눌러서 말이 도는 걸 도와줘요. 재갈이 입 안에서 미끄러지는 것도 막아 줘요.","caracteristiques":"어린 말이나 방향 잡기가 어려운 말에게 유용해요.","precautions":"치크가 어디에 걸리지 않도록 작은 가죽 고리로 볼끈에 고정하는 경우가 많아요."},{"nom":"D링 수륵(Verdun)","court":"‘D’ 모양의 고정 링으로, 곧은 면이 볼에 닿아요.","fonctionnement":"링의 곧은 면이 볼에 딱 붙어 있어서 재갈이 안정적이고, 말이 열어 주는 고삐를 또렷하게 느껴요.","caracteristiques":"입꼬리를 집지 않아요. 평지 운동, 장애물, 경마에서도 쓰여요.","precautions":"링이 고정된 수륵은 모두 그렇듯이 폭이 딱 맞아야 해요."},{"nom":"루즈링 수륵","court":"링이 마우스피스 구멍 안에서 자유롭게 움직여요.","fonctionnement":"재갈이 입 안에서 더 많이 움직여서, 말이 재갈을 씹으며 긴장을 푸는 데 도움이 되는 경우가 많아요.","caracteristiques":"가장 흔한 수륵이에요.","precautions":"구멍이 닳았거나 재갈이 너무 좁으면 링이 입꼬리를 집을 수 있어요. 자주 확인해요."}]},{"titre":"마우스피스의 모양","texte":"링 종류와 상관없이, 마우스피스 모양에 따라 입 안에서 압력이 퍼지는 방식이 달라져요.","cartes":[{"nom":"일자형 마우스피스","court":"한 덩어리로 된 마우스피스로, 단단하거나 약간 유연해요.","fonctionnement":"압력이 혀와 바(bars)에 좌우 똑같이 나뉘어요.","caracteristiques":"안정적인 재갈로, 고무나 부드러운 합성 소재로 된 것이 많아요.","precautions":"한쪽 고삐만 쓰는 동작은 관절이 있는 마우스피스보다 덜 정확해요."},{"nom":"싱글 조인트","court":"두 부분이 가운데 관절 하나로 연결되어 있어요.","fonctionnement":"양쪽 고삐가 당겨지면 마우스피스가 접혀요. 혀와 바를 누르고 입천장 쪽으로 올라갈 수 있어요(‘호두까기’ 효과).","caracteristiques":"입의 양쪽에 따로따로 작용할 수 있어요.","precautions":"손이 딱딱하거나 입천장이 낮은 말이라면 관절 부분이 입천장에 닿을 수 있어요."},{"nom":"더블 조인트","court":"세 부분: 두 마우스피스 사이에 작은 가운데 부품(링, 올리브 또는 플레이트)이 있어요.","fonctionnement":"가운데 부품이 혀 모양에 맞춰져서 ‘호두까기’ 효과가 크게 줄어요.","caracteristiques":"혀가 두껍거나 예민한 말에게 더 편한 경우가 많아요.","precautions":"가운데 플레이트는 혀 위에 평평하게 놓여야 해요. 비스듬해지면 안 돼요."}]},{"titre":"지렛대 작용 재갈","texte":"이런 재갈에는 샹크가 있어요. 고삐가 샹크 아래쪽을 당기면 재갈이 회전해요. 이게 지렛대 효과예요.","cartes":[{"nom":"지렛대 원리","court":"샹크, 커브 체인, 정수리끈이 함께 작용해요.","fonctionnement":"재갈이 회전하면서 바를 누르고, 커브 체인이 턱홈에서 조여지고, 정수리끈이 폴(정수리)을 눌러요.","caracteristiques":"마우스피스 아래 샹크가 길수록, 같은 고삐 당김에도 효과가 더 강해져요.","precautions":"커브 체인을 잘 조절하고, 고삐는 아주 부드럽게 써야 해요."},{"nom":"펠햄","court":"샹크, 커브 체인, 두 쌍의 고삐가 달린 마우스피스 하나짜리 재갈이에요.","fonctionnement":"위쪽에 단 고삐는 주로 수륵처럼 작용하고, 아래쪽 고삐는 지렛대 효과를 더해요.","caracteristiques":"수륵과 대륵 재갈의 효과를 재갈 하나에 모은 거예요.","precautions":"고삐 하나로 쓰면(두 링 사이에 연결 가죽을 달아서) 정확도가 떨어져요."},{"nom":"페소아 재갈","court":"링이 여러 개 겹쳐 있는 수륵이에요.","fonctionnement":"고삐를 어느 링에 다느냐에 따라 수륵에 가까운 효과가 나거나 지렛대 작용이 더해져요.","caracteristiques":"고른 링이 아래쪽일수록 지렛대 효과가 뚜렷해져요.","precautions":"손이 안정된 기승자만 써야 하고, 조절은 선생님과 함께 정해야 해요."}]},{"titre":"대륵","texte":"대륵은 말의 입 안에 재갈 두 개를 함께 넣어요. 브래든이라고 부르는 가는 수륵과, 샹크와 커브 체인이 달린 대륵 재갈(커브)이에요. 각각 고삐가 한 쌍씩 있어요.","cartes":[{"nom":"커브와 브래든","court":"재갈 두 개, 고삐 네 개.","fonctionnement":"브래든은 입꼬리에 작용해서 머리를 들어 올리고, 커브는 바, 턱, 폴에 지렛대 효과를 더해요. 기승자는 각 고삐의 힘을 따로따로 조절해요.","caracteristiques":"높은 수준의 마장마술과 전통 복장에서 쓰여요. 대륵 기승은 Galop 7 과정에 들어 있어요.","precautions":"독립된 손, 안정된 기좌, 그리고 이미 수륵으로 잘 훈련된 말이 필요해요."}]}],"matieres":{"titre":"알고 있었어요?","texte":"재갈은 여러 소재로 만들어져요. 스테인리스강, 침이 잘 나오게 해 주는 구리나 합금, 더 부드러운 고무와 합성 소재가 있어요. 침이 조금 나오고 재갈을 살짝 씹는 입은 보통 긴장이 풀린 입이에요."}},"s3":{"num":"03","titre":"해부와 작용 부위","intro":"재갈은 아주 정확한 자리에 놓여요. 앞니와 어금니 사이, 이가 없는 곳이에요. 재갈은 여러 부위에 작용하는데, 부위마다 반응이 달라요.","schemaTitre":"말 머리 간단 그림","schemaNote":"학습용 그림이며, 비율은 단순화했어요.","zones":[{"nom":"혀","texte":"압력의 큰 부분을 받아요. 특히 일자형이나 더블 조인트 마우스피스일 때 그래요."},{"nom":"바(bars)","texte":"아래턱에서 앞니와 어금니 사이의 이가 없는 부분이에요. 잇몸이 뼈를 바로 덮고 있어서 아주 예민한 부위예요."},{"nom":"입꼬리와 입술","texte":"입의 양쪽 끝이에요. 수륵이 여기에 작용해요. 특히 머리를 들어 올릴 때나 열어 주는 고삐를 쓸 때요."},{"nom":"입천장","texte":"입의 윗부분이에요. 싱글 조인트가 너무 많이 접히면 여기에 닿을 수 있어요."},{"nom":"폴(정수리)","texte":"지렛대 재갈을 쓰면 정수리끈이 머리 위쪽에 압력을 전달해요."},{"nom":"턱","texte":"샹크가 있는 재갈의 커브 체인은 턱홈에 놓이고, 재갈이 회전하면 그곳을 눌러요."}],"mecaTitre":"작용하는 세 가지 방식","mecanismes":[{"nom":"직접 압력","texte":"수륵에서는 고삐의 당김이 손이 당기는 방향 그대로 혀, 바, 입꼬리에 전달돼요."},{"nom":"지렛대 효과","texte":"샹크가 있으면 재갈이 회전해요. 힘이 커지고 바, 턱, 폴에 나뉘어 전달돼요."},{"nom":"옆쪽 작용","texte":"고정 링이나 치크가 열어 주는 고삐의 반대쪽 볼을 눌러서 말이 도는 걸 도와줘요."}]},"s4":{"num":"04","titre":"재갈은 어떻게 고를까요?","intro":"어떤 경우에나 ‘좋은’ 재갈은 없어요. 그 말, 그 기승자, 그리고 그들의 훈련 시기에 맞는 재갈이 있을 뿐이에요. 선생님과 함께 살펴볼 기준은 이거예요.","criteres":[{"nom":"말의 입","texte":"입의 폭이 재갈 크기를 정해요. 혀가 두껍거나 입천장이 낮으면 더 가는 마우스피스나 더블 조인트가 필요한 경우가 많아요."},{"nom":"예민함","texte":"아주 예민한 말은 안정적이고 부드러운 재갈을 더 편하게 느끼는 경우가 많아요."},{"nom":"조교 수준","texte":"어린 말은 간단한 수륵부터 시작해요. 지렛대 재갈과 대륵은 나중에, 숙련된 말에게 써요."},{"nom":"종목","texte":"각 종목의 규정이 대회에서 허용되는 재갈을 정해요. 현재 적용되는 연맹 규정을 항상 확인해요."},{"nom":"기승자의 손","texte":"재갈이 강할수록 안정되고, 부드럽게 연결되고, 기좌와 독립된 손이 필요해요."},{"nom":"피팅과 편안함","texte":"아무리 좋은 재갈도 크기가 맞고 높이가 제대로 조절되어야 잘 작동해요."}],"important":{"titre":"코치의 조언","texte":"더 강한 재갈이 올바른 조교를 대신할 수는 절대 없어요. 네 말이 당기거나, 재갈에 기대거나, 입을 벌린다면 먼저 원인을 찾아봐요. 네 손, 네 균형, 말의 이완, 이빨, 장비 조절 같은 것들이요. 재갈은 선생님의 의견을 들은 다음에만 바꿔요."}},"s5":{"num":"05","titre":"조절과 관리","intro":"잘 고른 재갈도 조절이 잘못되면 금방 불편해져요. 매번 타기 전에 이 항목들을 확인하는 습관을 들여요.","verifTitre":"타기 전 확인할 것","verifs":["폭: 재갈이 입 양쪽으로 약 0.5cm씩 나와 있고, 입술을 조이지 않아요.","높이: 수륵이면 보통 입꼬리에 작은 주름이 한두 개 보여요. 주름이 없으면 너무 낮고, 주름이 많으면 너무 높아요.","커브 체인: 턱홈에 평평하게 놓여 있어요. 커브 체인과 턱 사이에 손가락 두 개가 들어가야 해요.","상태: 날카로운 모서리가 없고, 링 구멍이나 관절이 닳지 않았고, 살을 집는 부분이 없어요.","가죽: 볼끈, 버클, 고삐가 부드럽고 상태가 좋아요."],"entretienTitre":"운동이 끝난 뒤","entretien":"안장을 내리자마자 침과 풀이 마르기 전에 재갈을 맑은 물로 헹궈요. 닦아서 말린 다음, 가죽도 정기적으로 관리해요.","erreurs":{"titre":"피해야 할 실수","points":["입꼬리를 보지 않고 수륵 높이를 ‘대충’ 조절하기.","‘말이 익숙하니까’ 하고 망가진 재갈을 계속 쓰기.","‘브레이크를 더 세게’ 하려고 커브 체인을 조이기.","운동 뒤에 더러운 재갈을 그대로 말리기."]}},"s6":{"num":"06","titre":"특별한 경우","intro":"Galop 5에서는 알아보고 원리를 이해하기만 하면 돼요. 사용 여부는 선생님과 함께 정해요.","cartes":[{"nom":"보셰 수륵","court":"작은 링이 하나 더 있어서 볼끈에 고정되는 수륵이에요.","detail":"재갈이 입 안에 매달린 상태로 아주 안정적이에요. 재갈을 많이 가지고 노는 말에게 잘 맞아요."},{"nom":"부드러운 재갈","court":"고무나 합성 소재로 만들어요.","detail":"부드럽고 가벼워서 예민한 입이나 어린 말에게 잘 맞아요. 더 빨리 닳으니까 씹힌 자국이나 갈라진 곳이 없는지 확인해요."},{"nom":"하카모어","court":"재갈 없는 굴레예요.","detail":"입 안에 아무것도 넣지 않고 콧등, 턱, 폴에 압력을 주어 작용해요. 원래부터 ‘더 부드러운’ 방법은 아니에요. 조절이 잘못되면 아주 강하게 작용할 수 있어요."},{"nom":"코끈(노즈밴드)","court":"재갈은 아니지만 재갈의 효과를 바꿔요.","detail":"코끈이 너무 조이면 말이 재갈을 씹지 못하고 컨택이 딱딱해져요. 코끈과 콧등 사이에 손가락 두 개가 들어가야 해요."}]},"lateral":{"observerTitre":"관찰해 봐요","observer":"다음 운동 때 말의 입을 봐요. 입이 닫혀 있고 차분한가요? 재갈을 살짝 씹고 있나요? 입꼬리에 주름이 한두 개 보이나요? 긴장이 풀린 입은 보통 긴장이 풀린 말을 보여 줘요.","defiTitre":"기승자 도전 과제","defi":"클럽 마구실에서 서로 다른 재갈 세 개를 찾아 이름을 말해 봐요. 링 종류, 마우스피스 모양, 직접 작용인지 지렛대인지요. 그다음 선생님께 네 답을 보여 줘요."},"videos":{"titre":"영상으로 더 잘 이해하기","v1":"주요 재갈 종류 알아보기","v2":"재갈의 여러 효과 이해하기","v3":"재갈 피팅 확인하기","aVenir":"영상 준비 중","tous":"영상 라이브러리 전체 보기"},"quiz":{"titre":"실력을 확인해 봐요","texte":"이 수업을 다 끝냈어요? 기억한 내용을 확인해 봐요.","bouton":"퀴즈 시작하기","bientot":"곧 공개"}},"nl":{"meta":{"kicker":"Galop 5 · Paardenkennis","titre":"De bitten","sous":"Hun werking begrijpen en het juiste bit kiezen.","duree":"Ongeveer 20 min leestijd","type":"Theorieles","audio":"Luisteren","langues":"Beschikbaar in 14 talen","retour":"De lessen van Galop 5","progression":"Leesvoortgang","sommaire":"Inhoud van de les","photoAVenir":"Foto volgt","agrandir":"Foto vergroten","fermer":"Sluiten","voirPlus":"Details bekijken","voirMoins":"Details verbergen","fonctionnement":"Werking","caracteristiques":"Goed om te weten","precautions":"Let op"},"nav":["Waarom","Soorten","Anatomie","Kiezen","Afstellen","Bijzondere gevallen"],"s1":{"num":"01","titre":"Waarom een bit gebruiken?","paras":["Het bit is het stuk metaal of zacht materiaal dat in de mond van het paard ligt en met de teugels verbonden is. Het geeft de hulpen van je hand door aan het paard: samen met je benen, je zit en je stem is het een van de manieren waarop jij en je paard met elkaar communiceren.","Een goede aanleuning is een lichte, elastische en constante verbinding tussen je hand en de mond van het paard. Je hand volgt de beweging van de hals, vooral in stap en galop, zodat het paard in het bit een stabiele, vertrouwde steun vindt en het nooit als hinderlijk ervaart.","De mond van het paard is heel gevoelig. Elke teugelhulp – halve parade, openende teugel, tegenteugel – moet kort en afgemeten zijn en weer worden losgelaten zodra het paard reageert. Door op het juiste moment toe te geven beloont je hand het paard, en zo leert het."],"retenir":{"titre":"Onthoud","points":["Het bit geeft de hulpen van de hand door: het vervangt je benen en je zit niet.","De aanleuning moet licht, elastisch en gelijkmatig zijn.","Een teugelhulp geef je terug zodra het paard heeft gereageerd."]}},"s2":{"num":"02","titre":"De verschillende soorten bitten","intro":"Bitten worden ingedeeld volgens twee hoofdcriteria: de vorm van het mondstuk (het deel dat in de mond ligt) en de manier waarop het met de teugels verbonden is (trensringen of stangen van een stangbit). Tik op een kaart om de details te zien.","groupes":[{"titre":"Trenzen: directe werking","texte":"Bij een trens werkt de teugel rechtstreeks op het bit, zonder hefboomwerking: de druk die het paard voelt, komt overeen met de spanning op de teugel.","cartes":[{"nom":"Olijfkoptrens","court":"De ringen zijn met olijfkoppen aan het mondstuk vastgemaakt.","fonctionnement":"De olijfkoppen voorkomen dat het bit draait of verschuift: het ligt stabiel in de mond.","caracteristiques":"Knijpt de mondhoeken niet. Wordt vaak gekozen voor gevoelige paarden of paarden die de aanleuning nog leren.","precautions":"Controleer de breedte: een te smal bit knelt de lippen, een te breed bit schuift opzij."},{"nom":"Knebeltrens (full cheek)","court":"Verticale knevels verlengen de ringen aan beide kanten van de mond.","fonctionnement":"Bij een openende teugel drukken de knevels tegen de zijkant van het hoofd en helpen ze het paard te draaien. Ze voorkomen ook dat het bit door de mond schuift.","caracteristiques":"Handig voor jonge paarden en voor paarden die moeilijk te sturen zijn.","precautions":"De knevels worden vaak met kleine leren lusjes aan de bakstukken vastgemaakt, zodat ze nergens achter blijven haken."},{"nom":"D-ringtrens (Verdun)","court":"Vaste ringen in de vorm van een „D”, met een rechte kant tegen de wang.","fonctionnement":"De rechte kant van de ring ligt plat tegen de wang: het bit ligt stabiel en het paard voelt de openende teugel duidelijk.","caracteristiques":"Knijpt de mondhoeken niet. Wordt gebruikt in de dressuur, bij het springen en in de rensport.","precautions":"Zoals bij elke trens met vaste ringen moet de breedte precies goed zijn."},{"nom":"Watertrens (losse ringen)","court":"De ringen glijden vrij door de gaten van het mondstuk.","fonctionnement":"Het bit beweegt meer in de mond, wat het paard vaak aanmoedigt om te kauwen en te ontspannen.","caracteristiques":"Dit is de meest gebruikte trens.","precautions":"Als de gaten versleten zijn of het bit te smal is, kunnen de ringen de mondhoeken knellen: controleer ze regelmatig."}]},{"titre":"De vorm van het mondstuk","texte":"Welke ringen het bit ook heeft, de vorm van het mondstuk bepaalt hoe de druk zich in de mond verdeelt.","cartes":[{"nom":"Recht mondstuk","court":"Een mondstuk uit één stuk, stijf of licht buigzaam.","fonctionnement":"De druk verdeelt zich gelijkmatig links en rechts over de tong en de laden.","caracteristiques":"Stabiel bit, vaak verkrijgbaar in rubber of zacht kunststof.","precautions":"Hulpen met één teugel zijn minder precies dan met een gebroken mondstuk."},{"nom":"Enkel gebroken","court":"Twee delen die in het midden met een scharnier verbonden zijn.","fonctionnement":"Als beide teugels worden aangenomen, knikt het mondstuk: het drukt op de tong en de laden en kan omhoog richting het verhemelte komen (het „notenkrakereffect”).","caracteristiques":"Maakt het mogelijk om op elke kant van de mond apart in te werken.","precautions":"Bij een harde hand of een paard met een laag verhemelte kan het scharnier het verhemelte raken."},{"nom":"Dubbel gebroken","court":"Drie delen: een klein middenstuk (ring, olijf of plaatje) tussen twee delen van het mondstuk.","fonctionnement":"Het middenstuk volgt de vorm van de tong: het „notenkrakereffect” is sterk verminderd.","caracteristiques":"Vaak comfortabeler voor paarden met een dikke of gevoelige tong.","precautions":"Het middenplaatje moet plat op de tong blijven liggen: het mag niet scheef gaan staan."}]},{"titre":"Bitten met hefboomwerking","texte":"Deze bitten hebben stangen (zijstukken). Als de teugel aan de onderkant van de stang trekt, kantelt het bit: dat is de hefboomwerking.","cartes":[{"nom":"Het hefboomprincipe","court":"Stangen, kinketting en kopstuk werken samen.","fonctionnement":"Bij het kantelen drukt het bit op de laden, de kinketting spant zich in de kinkuil en het kopstuk drukt op de nek.","caracteristiques":"Hoe langer de stang onder het mondstuk, hoe sterker het effect bij dezelfde teugelspanning.","precautions":"De kinketting moet goed afgesteld zijn en de teugels moeten heel zacht gebruikt worden."},{"nom":"Pelham","court":"Eén mondstuk met stangen, een kinketting en twee paar teugels.","fonctionnement":"De bovenste teugel werkt vooral als een trens; de onderste voegt de hefboomwerking toe.","caracteristiques":"Hij combineert de werking van trens en stang in één bit.","precautions":"Met maar één teugel gereden (met een verbindingsriempje tussen de twee ringen) verliest hij aan precisie."},{"nom":"Pessoa-bit","court":"Een trens met meerdere ringen boven elkaar.","fonctionnement":"Afhankelijk van de ring waaraan de teugel vastzit, werkt het bijna als een trens of komt er hefboomwerking bij.","caracteristiques":"Hoe lager de gekozen ring, hoe sterker de hefboomwerking.","precautions":"Alleen voor ruiters met een vaste hand; de afstelling kies je samen met je instructeur."}]},{"titre":"Stang en trens","texte":"Bij stang en trens liggen er twee bitten in de mond van het paard: een dunne trens, de bridontrens, en een stang met zijstukken en kinketting, elk met een eigen paar teugels.","cartes":[{"nom":"Stang en bridontrens","court":"Twee bitten, vier teugels.","fonctionnement":"De bridontrens werkt op de mondhoeken en richt op; de stang voegt de hefboomwerking op de laden, de kin en de nek toe. De ruiter doseert elke teugel apart.","caracteristiques":"Wordt gebruikt in de dressuur op hoog niveau en bij traditioneel tenue. Rijden op stang en trens staat op het programma van Galop 7.","precautions":"Vraagt een onafhankelijke hand, een stabiele zit en een paard dat al goed op de trens is opgeleid."}]}],"matieres":{"titre":"Wist je dat?","texte":"Bitten bestaan in verschillende materialen: roestvrij staal, koper of legeringen die de speekselproductie stimuleren, rubber en zachtere kunststoffen. Een mond die een beetje speekselt en kauwt, is meestal een ontspannen mond."}},"s3":{"num":"03","titre":"Anatomie en inwerkingszones","intro":"Het bit ligt op een heel precieze plek: tussen de snijtanden en de kiezen, waar geen tanden staan. Het werkt op verschillende zones, die niet allemaal op dezelfde manier reageren.","schemaTitre":"Vereenvoudigd schema van een paardenhoofd","schemaNote":"Leerschema, vereenvoudigde verhoudingen.","zones":[{"nom":"De tong","texte":"Die krijgt een groot deel van de druk, vooral bij een recht of dubbel gebroken mondstuk."},{"nom":"De laden","texte":"Het tandeloze deel van de onderkaak, tussen de snijtanden en de kiezen. Het tandvlees ligt daar direct op het bot: een heel gevoelige zone."},{"nom":"De mondhoeken en de lippen","texte":"De hoeken van de mond. Hier werkt de trens, vooral als die opricht of bij een openende teugel."},{"nom":"Het verhemelte","texte":"De bovenkant van de mond. Een enkel gebroken bit dat te ver doorknikt, kan het raken."},{"nom":"De nek","texte":"Bij een bit met hefboomwerking geeft het kopstuk druk door op de bovenkant van het hoofd."},{"nom":"De kin","texte":"De kinketting van een stangbit ligt in de kinkuil en drukt daar als het bit kantelt."}],"mecaTitre":"Drie manieren van inwerken","mecanismes":[{"nom":"Directe druk","texte":"Bij een trens komt de teugelspanning terecht op de tong, de laden en de mondhoeken, in de richting waarin de hand trekt."},{"nom":"Hefboomwerking","texte":"Met stangen kantelt het bit: de kracht wordt vergroot en verdeelt zich over de laden, de kin en de nek."},{"nom":"Zijdelingse werking","texte":"Vaste ringen of knevels drukken tegen de wang aan de kant tegenover de openende teugel en helpen het paard te draaien."}]},"s4":{"num":"04","titre":"Hoe kies je een bit?","intro":"Een „goed” bit bestaat niet op zich: er bestaat een bit dat past bij een paard, een ruiter en een bepaald moment in hun training. Hier zijn de criteria om samen met je instructeur te bekijken.","criteres":[{"nom":"De mond van het paard","texte":"De breedte bepaalt de maat van het bit. Een dikke tong of een laag verhemelte vragen vaak om een dunner of dubbel gebroken mondstuk."},{"nom":"Zijn gevoeligheid","texte":"Een heel gevoelig paard voelt zich vaak beter met een stabiel en zacht bit."},{"nom":"Zijn opleidingsniveau","texte":"Een jong paard begint op een gewone trens. Bitten met hefboomwerking en stang en trens komen later, bij een ervaren paard."},{"nom":"De discipline","texte":"Het reglement van elke discipline bepaalt welke bitten in wedstrijden zijn toegestaan. Controleer altijd het geldende reglement van de bond."},{"nom":"De hand van de ruiter","texte":"Hoe sterker een bit werkt, hoe meer het een vaste, soepele en van de zit onafhankelijke hand vraagt."},{"nom":"Afstelling en comfort","texte":"Zelfs het beste bit werkt alleen goed als het de juiste maat heeft en op de juiste hoogte is afgesteld."}],"important":{"titre":"De tip van de coach","texte":"Een scherper bit vervangt nooit een correcte africhting. Als je paard trekt, op het bit leunt of de mond opendoet, zoek dan eerst de oorzaak: je hand, je evenwicht, zijn ontspanning, zijn gebit, de afstelling van het materiaal. Verander alleen van bit na overleg met je instructeur."}},"s5":{"num":"05","titre":"Afstelling en onderhoud","intro":"Een goed gekozen maar slecht afgesteld bit wordt al snel oncomfortabel. Maak er een gewoonte van om deze punten voor elke les te controleren.","verifTitre":"De controles voor het opstijgen","verifs":["De breedte: het bit steekt aan elke kant van de mond ongeveer een halve centimeter uit, zonder de lippen te knellen.","De hoogte: bij een trens zie je meestal één of twee kleine plooitjes in de mondhoek. Zonder plooi hangt de trens te laag; met veel plooien zit hij te hoog.","De kinketting: die ligt plat in de kinkuil; je moet twee vingers tussen de kinketting en de kin kunnen schuiven.","De staat: geen scherpe randen, geen slijtage bij de gaten van de ringen of bij de scharnieren, geen onderdeel dat knelt.","Het leer: bakstukken, gespen en teugels zijn soepel en in goede staat."],"entretienTitre":"Na de les","entretien":"Spoel het bit af met schoon water zodra je hebt afgezadeld, voordat speeksel en gras opdrogen. Droog het af, laat het drogen en onderhoud het leer regelmatig.","erreurs":{"titre":"Fouten om te vermijden","points":["De hoogte van de trens „op de gok” afstellen zonder naar de mondhoeken te kijken.","Een beschadigd bit blijven gebruiken omdat „het paard eraan gewend is”.","De kinketting strakker zetten om „meer rem” te hebben.","Het bit na de les vuil laten opdrogen."]}},"s6":{"num":"06","titre":"Bijzondere gevallen","intro":"Voor Galop 5 is het genoeg om ze te herkennen en hun principe te begrijpen. Of je ze gebruikt, beslis je samen met een instructeur.","cartes":[{"nom":"De Baucher-trens","court":"Een trens met een extra ringetje dat aan het bakstuk wordt vastgemaakt.","detail":"Het bit hangt in de mond en ligt heel stabiel. Het is geschikt voor paarden die veel met hun bit spelen."},{"nom":"Zachte bitten","court":"Van rubber of kunststof.","detail":"Zacht en licht, geschikt voor gevoelige monden of jonge paarden. Ze slijten sneller: controleer of ze niet aangeknaagd of gescheurd zijn."},{"nom":"De hackamore","court":"Een hoofdstel zonder bit.","detail":"Hij werkt met druk op de neusrug, de kin en de nek, zonder iets in de mond. Het is niet per definitie een „zachtere” oplossing: slecht afgesteld kan hij heel scherp zijn."},{"nom":"De neusriem","court":"Het is geen bit, maar hij verandert wel de werking ervan.","detail":"Een te strakke neusriem belet het paard te kauwen en maakt de aanleuning hard. Je moet twee vingers tussen de neusriem en de neusrug kunnen schuiven."}]},"lateral":{"observerTitre":"Om op te letten","observer":"Kijk tijdens je volgende les naar de mond van het paard: is die gesloten en rustig? Kauwt het een beetje? Zie je één of twee plooitjes in de mondhoeken? Een ontspannen mond wijst vaak op een ontspannen paard.","defiTitre":"De ruiteruitdaging","defi":"Zoek in de zadelkamer van je manege drie verschillende bitten en benoem ze: soort ringen, vorm van het mondstuk, directe werking of hefboomwerking. Laat je antwoord daarna aan je instructeur zien."},"videos":{"titre":"Beter begrijpen met beelden","v1":"De belangrijkste soorten bitten herkennen","v2":"De verschillende werkingen van een bit begrijpen","v3":"De afstelling van een bit controleren","aVenir":"Video volgt","tous":"Alle video's bekijken"},"quiz":{"titre":"Test je kennis","texte":"Ben je klaar met deze les? Controleer wat je hebt onthouden.","bouton":"Naar de quiz","bientot":"Binnenkort"}},"pl":{"meta":{"kicker":"Galop 5 · Wiedza jeździecka","titre":"Kiełzna","sous":"Zrozum, jak działają, i dobrze je wybieraj.","duree":"Około 20 min czytania","type":"Lekcja teoretyczna","audio":"Wersja audio","langues":"Dostępne w 14 językach","retour":"Lekcje Galop 5","progression":"Postęp czytania","sommaire":"Spis treści lekcji","photoAVenir":"Zdjęcie wkrótce","agrandir":"Powiększ zdjęcie","fermer":"Zamknij","voirPlus":"Pokaż szczegóły","voirMoins":"Ukryj szczegóły","fonctionnement":"Działanie","caracteristiques":"Warto wiedzieć","precautions":"Na co uważać"},"nav":["Dlaczego","Rodzaje","Anatomia","Wybór","Dopasowanie","Przypadki szczególne"],"s1":{"num":"01","titre":"Po co używać kiełzna?","paras":["Kiełzno to element z metalu lub miękkiego materiału, który znajduje się w pysku konia i jest połączony z wodzami. Przekazuje koniowi działanie twojej ręki: obok łydek, dosiadu i głosu jest jednym ze sposobów komunikacji między tobą a koniem.","Dobry kontakt to lekkie, elastyczne i stałe połączenie między twoją ręką a pyskiem konia. Twoja ręka towarzyszy ruchom szyi, zwłaszcza w stępie i galopie, aby koń znajdował w kiełźnie stabilne i bezpieczne oparcie, a nigdy nie odczuwał go jako przeszkody.","Pysk konia jest bardzo wrażliwy. Każde działanie wodzy – półparada, wodza otwierająca, wodza przeciwna – musi być krótkie, wyważone i oddane, gdy tylko koń zareaguje. To ustępując we właściwym momencie, ręka nagradza konia, a koń się uczy."],"retenir":{"titre":"Zapamiętaj","points":["Kiełzno przekazuje działanie ręki: nie zastępuje ani łydek, ani dosiadu.","Kontakt musi być lekki, elastyczny i równomierny.","Działanie wodzy oddajesz, gdy tylko koń zareaguje."]}},"s2":{"num":"02","titre":"Różne rodzaje kiełzn","intro":"Kiełzna dzieli się według dwóch głównych kryteriów: kształtu ustnika (części, która znajduje się w pysku) oraz sposobu połączenia z wodzami (kółka wędzidła lub czanki munsztuka). Dotknij karty, aby zobaczyć szczegóły.","groupes":[{"titre":"Wędzidła: działanie bezpośrednie","texte":"W wędzidle wodza działa bezpośrednio na kiełzno, bez efektu dźwigni: nacisk, który odczuwa koń, odpowiada napięciu wodzy.","cartes":[{"nom":"Wędzidło z oliwkami","court":"Kółka są połączone z ustnikiem za pomocą oliwek.","fonctionnement":"Oliwki nie pozwalają kiełznu obracać się ani przesuwać: leży stabilnie w pysku.","caracteristiques":"Nie przyszczypuje kącików warg. Często wybierane dla koni wrażliwych lub uczących się kontaktu.","precautions":"Sprawdź szerokość: zbyt wąskie kiełzno ściska wargi, zbyt szerokie przesuwa się na bok."},{"nom":"Wędzidło z pałkami","court":"Pionowe pałki przedłużają kółka po obu stronach pyska.","fonctionnement":"Przy wodzy otwierającej pałki naciskają na bok głowy i pomagają koniowi skręcić. Zapobiegają też przesuwaniu się wędzidła w pysku.","caracteristiques":"Przydatne dla młodych koni i koni, które trudno się prowadzi.","precautions":"Pałki często mocuje się do policzków ogłowia małymi skórzanymi pętelkami, żeby nigdzie nie zaczepiały."},{"nom":"Wędzidło D-ring (Verdun)","court":"Stałe kółka w kształcie litery „D”, z prostym bokiem przy policzku.","fonctionnement":"Prosty bok kółka przylega do policzka: kiełzno jest stabilne, a koń wyraźnie czuje wodzę otwierającą.","caracteristiques":"Nie przyszczypuje kącików warg. Używane zarówno w ujeżdżeniu, jak i w skokach oraz w wyścigach.","precautions":"Jak w każdym wędzidle ze stałymi kółkami, szerokość musi być dokładnie dobrana."},{"nom":"Wędzidło z luźnymi kółkami","court":"Kółka swobodnie przesuwają się w otworach ustnika.","fonctionnement":"Kiełzno bardziej porusza się w pysku, co często zachęca konia do żucia i rozluźnienia.","caracteristiques":"To najczęściej używane wędzidło.","precautions":"Jeśli otwory są wytarte albo kiełzno jest za wąskie, kółka mogą przyszczypywać kąciki warg: regularnie je sprawdzaj."}]},{"titre":"Kształt ustnika","texte":"Niezależnie od rodzaju kółek kształt ustnika zmienia sposób, w jaki nacisk rozkłada się w pysku.","cartes":[{"nom":"Ustnik prosty","court":"Ustnik z jednego kawałka, sztywny lub lekko giętki.","fonctionnement":"Nacisk rozkłada się na język i laski żuchwy, równo po prawej i lewej stronie.","caracteristiques":"Stabilne kiełzno, często dostępne z gumy lub miękkiego tworzywa sztucznego.","precautions":"Działanie jedną wodzą jest mniej precyzyjne niż przy ustniku łamanym."},{"nom":"Pojedynczo łamane","court":"Dwie części połączone pośrodku przegubem.","fonctionnement":"Gdy obie wodze się napinają, ustnik się zgina: naciska na język i laski żuchwy i może unosić się w stronę podniebienia (efekt „dziadka do orzechów”).","caracteristiques":"Pozwala działać osobno na każdą stronę pyska.","precautions":"Przy twardej ręce lub u konia z niskim podniebieniem przegub może dotykać podniebienia."},{"nom":"Podwójnie łamane","court":"Trzy części: mały element środkowy (kółko, oliwka lub płytka) między dwiema częściami ustnika.","fonctionnement":"Element środkowy dopasowuje się do języka: efekt „dziadka do orzechów” jest mocno ograniczony.","caracteristiques":"Często wygodniejsze dla koni z grubym lub wrażliwym językiem.","precautions":"Płytka środkowa musi leżeć płasko na języku: nie może ustawiać się krzywo."}]},{"titre":"Kiełzna działające dźwignią","texte":"Te kiełzna mają czanki. Gdy wodza ciągnie za dolny koniec czanki, kiełzno się obraca: to jest działanie dźwigni.","cartes":[{"nom":"Zasada dźwigni","court":"Czanki, łańcuszek podbródkowy i nagłówek działają razem.","fonctionnement":"Obracając się, kiełzno naciska na laski żuchwy, łańcuszek zaciska się w rowku podbródkowym, a nagłówek naciska na potylicę.","caracteristiques":"Im dłuższa czanka poniżej ustnika, tym silniejsze działanie przy tym samym napięciu wodzy.","precautions":"Łańcuszek musi być dobrze dopasowany, a wodzami trzeba posługiwać się bardzo delikatnie."},{"nom":"Pelham","court":"Jeden ustnik z czankami, łańcuszkiem podbródkowym i dwiema parami wodzy.","fonctionnement":"Wodza przypięta u góry działa głównie jak wędzidło; dolna dodaje działanie dźwigni.","caracteristiques":"Łączy w jednym kiełźnie działanie wędzidła i munsztuka.","precautions":"Używany z jedną wodzą (z łącznikiem między dwoma kółkami) traci na precyzji."},{"nom":"Wędzidło Pessoa","court":"Wędzidło z kilkoma kółkami umieszczonymi jedno nad drugim.","fonctionnement":"W zależności od kółka, do którego przypięta jest wodza, działa podobnie do wędzidła albo dodaje dźwignię.","caracteristiques":"Im niższe wybrane kółko, tym wyraźniejsze działanie dźwigni.","precautions":"Tylko dla jeźdźców z pewną ręką, a ustawienie trzeba wybrać z instruktorem."}]},{"titre":"Ogłowie munsztukowe","texte":"Ogłowie munsztukowe łączy w pysku konia dwa kiełzna: cienkie wędzidło, zwane bridonem, oraz munsztuk z czankami i łańcuszkiem podbródkowym – każde z własną parą wodzy.","cartes":[{"nom":"Munsztuk i bridon","court":"Dwa kiełzna, cztery wodze.","fonctionnement":"Bridon działa na kąciki warg i unosi; munsztuk dodaje działanie dźwigni na laski żuchwy, podbródek i potylicę. Jeździec dozuje każdą wodzę osobno.","caracteristiques":"Używane w ujeżdżeniu na wysokim poziomie i przy tradycyjnym stroju. Jazda na munsztuku jest w programie Galop 7.","precautions":"Wymaga niezależnej ręki, stabilnego dosiadu i konia dobrze wyszkolonego już na wędzidle."}]}],"matieres":{"titre":"Czy wiesz, że…?","texte":"Kiełzna są wykonane z różnych materiałów: stali nierdzewnej, miedzi lub stopów sprzyjających wydzielaniu śliny, a także gumy i bardziej miękkich tworzyw sztucznych. Pysk, który lekko się ślini i żuje, jest zazwyczaj rozluźniony."}},"s3":{"num":"03","titre":"Anatomia i strefy działania","intro":"Kiełzno leży w bardzo konkretnym miejscu: między siekaczami a zębami trzonowymi, tam gdzie nie ma zębów. Działa na kilka stref, które nie reagują w ten sam sposób.","schemaTitre":"Uproszczony schemat głowy konia","schemaNote":"Schemat poglądowy, uproszczone proporcje.","zones":[{"nom":"Język","texte":"Przyjmuje dużą część nacisku, zwłaszcza przy ustniku prostym lub podwójnie łamanym."},{"nom":"Laski żuchwy","texte":"Bezzębna część żuchwy między siekaczami a zębami trzonowymi. Dziąsło leży tam bezpośrednio na kości: to bardzo wrażliwa strefa."},{"nom":"Kąciki warg i wargi","texte":"Kąciki pyska. Tu działa wędzidło, zwłaszcza gdy unosi lub przy wodzy otwierającej."},{"nom":"Podniebienie","texte":"Górna część pyska. Wędzidło pojedynczo łamane, które za mocno się zgina, może go dotykać."},{"nom":"Potylica","texte":"Przy kiełźnie działającym dźwignią nagłówek przenosi nacisk na górną część głowy."},{"nom":"Podbródek","texte":"Łańcuszek podbródkowy kiełzna z czankami leży w rowku podbródkowym i naciska tam, gdy kiełzno się obraca."}],"mecaTitre":"Trzy sposoby działania","mecanismes":[{"nom":"Nacisk bezpośredni","texte":"W wędzidle napięcie wodzy przenosi się na język, laski żuchwy i kąciki warg, w kierunku, w którym ciągnie ręka."},{"nom":"Działanie dźwigni","texte":"Z czankami kiełzno się obraca: siła się zwiększa i rozkłada między laski żuchwy, podbródek i potylicę."},{"nom":"Działanie boczne","texte":"Stałe kółka lub pałki naciskają na policzek po stronie przeciwnej do wodzy otwierającej i pomagają koniowi skręcić."}]},"s4":{"num":"04","titre":"Jak wybrać kiełzno?","intro":"Nie istnieje „dobre” kiełzno samo w sobie: istnieje kiełzno dopasowane do konia, jeźdźca i konkretnego etapu ich pracy. Oto kryteria, które warto przeanalizować razem z instruktorem.","criteres":[{"nom":"Pysk konia","texte":"Jego szerokość wyznacza rozmiar kiełzna. Gruby język lub niskie podniebienie często wymagają cieńszego ustnika lub podwójnie łamanego."},{"nom":"Jego wrażliwość","texte":"Bardzo wrażliwy koń często lepiej czuje się ze stabilnym i łagodnym kiełznem."},{"nom":"Jego poziom wyszkolenia","texte":"Młody koń zaczyna na zwykłym wędzidle. Kiełzna działające dźwignią i ogłowie munsztukowe przychodzą później, przy koniu wyszkolonym."},{"nom":"Dyscyplina","texte":"Regulamin każdej dyscypliny określa kiełzna dozwolone w zawodach. Zawsze sprawdzaj obowiązujący regulamin federacji."},{"nom":"Ręka jeźdźca","texte":"Im silniej działa kiełzno, tym bardziej wymaga ręki spokojnej, miękkiej i niezależnej od dosiadu."},{"nom":"Dopasowanie i komfort","texte":"Nawet najlepsze kiełzno działa dobrze tylko wtedy, gdy ma właściwy rozmiar i jest zapięte na odpowiedniej wysokości."}],"important":{"titre":"Rada trenera","texte":"Ostrzejsze kiełzno nigdy nie zastąpi prawidłowej pracy ujeżdżeniowej. Jeśli twój koń ciągnie, wiesza się na wodzach lub otwiera pysk, najpierw poszukaj przyczyny: twoja ręka, twoja równowaga, jego rozluźnienie, jego zęby, dopasowanie sprzętu. Zmieniaj kiełzno tylko po konsultacji z instruktorem."}},"s5":{"num":"05","titre":"Dopasowanie i pielęgnacja","intro":"Dobrze wybrane, ale źle dopasowane kiełzno szybko staje się niewygodne. Wyrób sobie nawyk sprawdzania tych punktów przed każdą jazdą.","verifTitre":"Co sprawdzić przed wsiadaniem","verifs":["Szerokość: kiełzno wystaje około pół centymetra z każdej strony pyska, nie ściskając warg.","Wysokość: przy wędzidle zwykle widać jedną lub dwie małe zmarszczki w kąciku warg. Bez zmarszczki wędzidło jest za nisko; przy wielu zmarszczkach – za wysoko.","Łańcuszek podbródkowy: leży płasko w rowku podbródkowym; między łańcuszek a podbródek muszą wchodzić dwa palce.","Stan: żadnych ostrych krawędzi, żadnego zużycia przy otworach na kółka ani przy przegubach, żadnej części, która przyszczypuje.","Skóry: policzki, sprzączki i wodze są miękkie i w dobrym stanie."],"entretienTitre":"Po jeździe","entretien":"Opłucz kiełzno czystą wodą zaraz po rozsiodłaniu, zanim ślina i trawa zaschną. Wytrzyj je, zostaw do wyschnięcia i regularnie konserwuj skóry.","erreurs":{"titre":"Błędy, których należy unikać","points":["Ustawianie wysokości wędzidła „na oko”, bez patrzenia na kąciki warg.","Używanie uszkodzonego kiełzna, bo „koń jest do niego przyzwyczajony”.","Mocniejsze zapinanie łańcuszka, żeby „mieć lepsze hamowanie”.","Zostawianie brudnego kiełzna do wyschnięcia po jeździe."]}},"s6":{"num":"06","titre":"Przypadki szczególne","intro":"Na Galop 5 wystarczy je rozpoznawać i rozumieć ich zasadę. O ich użyciu decyduje się razem z instruktorem.","cartes":[{"nom":"Wędzidło Baucher","court":"Wędzidło z dodatkowym małym kółkiem przypinanym do policzka ogłowia.","detail":"Kiełzno jest zawieszone i leży bardzo stabilnie w pysku. Pasuje koniom, które dużo bawią się wędzidłem."},{"nom":"Miękkie kiełzna","court":"Z gumy lub tworzywa sztucznego.","detail":"Łagodne i lekkie, pasują do wrażliwych pysków lub młodych koni. Szybciej się zużywają: sprawdzaj, czy nie są pogryzione lub pęknięte."},{"nom":"Hackamore","court":"Ogłowie bez kiełzna.","detail":"Działa przez nacisk na grzbiet nosa, podbródek i potylicę, bez niczego w pysku. Nie jest z zasady „łagodniejszym” rozwiązaniem: źle dopasowany może być bardzo ostry."},{"nom":"Nachrapnik","court":"Nie jest kiełznem, ale zmienia jego działanie.","detail":"Zbyt mocno zapięty nachrapnik nie pozwala koniowi żuć i sprawia, że kontakt staje się twardy. Między nachrapnik a grzbiet nosa muszą wchodzić dwa palce."}]},"lateral":{"observerTitre":"Do obserwacji","observer":"Podczas następnej jazdy przyjrzyj się pyskowi konia: czy jest zamknięty i spokojny? Czy koń trochę żuje? Czy w kącikach warg widać jedną lub dwie zmarszczki? Rozluźniony pysk często oznacza rozluźnionego konia.","defiTitre":"Wyzwanie jeźdźca","defi":"W siodlarni swojego klubu znajdź trzy różne kiełzna i nazwij je: rodzaj kółek, kształt ustnika, działanie bezpośrednie czy dźwignia. Potem pokaż swoją odpowiedź instruktorowi."},"videos":{"titre":"Zrozum lepiej dzięki obrazom","v1":"Rozpoznawanie głównych rodzajów kiełzn","v2":"Zrozumienie różnych sposobów działania kiełzna","v3":"Sprawdzanie dopasowania kiełzna","aVenir":"Wideo wkrótce","tous":"Zobacz całą wideotekę"},"quiz":{"titre":"Sprawdź swoją wiedzę","texte":"Lekcja ukończona? Sprawdź, co udało ci się zapamiętać.","bouton":"Przejdź do quizu","bientot":"Wkrótce"}},"pt":{"meta":{"kicker":"Galop 5 · Cultura equestre","titre":"As embocaduras","sous":"Entender seus efeitos e escolhê-las bem.","duree":"Cerca de 20 min de leitura","type":"Aula teórica","audio":"Leitura em áudio","langues":"Disponível nas 14 línguas","retour":"As aulas do Galop 5","progression":"Progresso da leitura","sommaire":"Sumário da aula","photoAVenir":"Foto em breve","agrandir":"Ampliar a foto","fermer":"Fechar","voirPlus":"Ver o detalhe","voirMoins":"Ocultar o detalhe","fonctionnement":"Funcionamento","caracteristiques":"Bom saber","precautions":"Precauções"},"nav":["Por quê","Famílias","Anatomia","Escolher","Ajustar","Casos especiais"],"s1":{"num":"01","titre":"Por que usar uma embocadura?","paras":["A embocadura é a peça de metal ou de material macio colocada na boca do cavalo e ligada às rédeas. Ela transmite ao cavalo as ações da sua mão: é um dos meios de comunicação entre você e ele, junto com as pernas, o assento e a voz.","Um bom contato é uma ligação leve, elástica e constante entre a sua mão e a boca do cavalo. Sua mão acompanha o movimento do pescoço, sobretudo ao passo e ao galope, para que o cavalo encontre na embocadura um apoio estável e tranquilizador, nunca um incômodo.","A boca do cavalo é muito sensível. Cada ação de rédea — meia-parada, rédea de abertura, rédea contrária — deve ser breve, dosada e depois cedida assim que o cavalo responde. É cedendo no momento certo que a mão recompensa e que o cavalo aprende."],"retenir":{"titre":"Para lembrar","points":["A embocadura transmite as ações da mão: ela não substitui nem as pernas, nem o assento.","O contato deve ser leve, elástico e regular.","Uma ação de rédea é cedida assim que o cavalo responde."]}},"s2":{"num":"02","titre":"As diferentes famílias de embocaduras","intro":"As embocaduras são classificadas segundo dois grandes critérios: a forma do bocado (a parte que entra na boca) e a maneira como ele é ligado às rédeas (argolas de bridão ou hastes de freio). Toque em um cartão para descobrir o detalhe.","groupes":[{"titre":"Os bridões: ação direta","texte":"Com um bridão, a rédea age diretamente sobre a embocadura, sem efeito de alavanca: a pressão sentida pelo cavalo corresponde à tensão da rédea.","cartes":[{"nom":"Bridão de olivas","court":"As argolas são fixadas ao bocado por olivas.","fonctionnement":"As olivas impedem a embocadura de girar e de deslizar: ela permanece estável na boca.","caracteristiques":"Não belisca as comissuras labiais. Muitas vezes escolhido para cavalos sensíveis ou que estão aprendendo o contato.","precautions":"Verifique a largura: uma embocadura estreita demais aperta os lábios; larga demais, ela sai do centro."},{"nom":"Bridão de pernas","court":"Pernas verticais prolongam as argolas de cada lado da boca.","fonctionnement":"As pernas pressionam a lateral da cabeça durante uma rédea de abertura e ajudam o cavalo a virar. Elas também impedem a embocadura de escorregar pela boca.","caracteristiques":"Prático para cavalos jovens e para os que são difíceis de dirigir.","precautions":"Muitas vezes as pernas são presas aos montantes da cabeçada com pequenos passadores de couro, para que não se enganchem em nada."},{"nom":"Bridão em D (Verdun)","court":"Argolas fixas em forma de « D », com um lado reto contra a bochecha.","fonctionnement":"O lado reto da argola fica encostado na bochecha: a embocadura é estável e o cavalo sente nitidamente a rédea de abertura.","caracteristiques":"Não belisca as comissuras labiais. Usado no adestramento (trabalho no plano), no salto e nas corridas.","precautions":"Como em todo bridão de argolas fixas, a largura deve ser exata."},{"nom":"Bridão de argolas soltas","court":"As argolas deslizam livremente nos furos do bocado.","fonctionnement":"A embocadura se move mais na boca, o que muitas vezes incentiva o cavalo a mastigar e a relaxar.","caracteristiques":"É o bridão mais comum.","precautions":"Se os furos estiverem gastos ou a embocadura estreita demais, as argolas podem beliscar as comissuras: verifique-as regularmente."}]},{"titre":"A forma do bocado","texte":"Seja qual for o tipo de argolas, a forma do bocado muda a maneira como a pressão se distribui na boca.","cartes":[{"nom":"Bocado reto","court":"Um bocado de uma só peça, rígido ou levemente flexível.","fonctionnement":"A pressão se distribui sobre a língua e sobre as barras, de forma igual à direita e à esquerda.","caracteristiques":"Embocadura estável, muitas vezes oferecida em borracha ou em material sintético macio.","precautions":"As ações de uma única rédea são menos precisas do que com um bocado articulado."},{"nom":"Articulação simples","court":"Duas partes ligadas no centro por uma articulação.","fonctionnement":"Quando as duas rédeas se tensionam, o bocado se dobra: ele pressiona a língua e as barras e pode subir em direção ao palato (efeito « quebra-nozes »).","caracteristiques":"Permite agir separadamente sobre cada lado da boca.","precautions":"Com uma mão dura ou um cavalo de palato baixo, a articulação pode tocar o palato."},{"nom":"Dupla articulação","court":"Três partes: um pequeno elemento central (argola, oliva ou plaquinha) entre duas partes do bocado.","fonctionnement":"O elemento central se adapta à forma da língua: o efeito « quebra-nozes » fica muito reduzido.","caracteristiques":"Muitas vezes mais confortável para cavalos de língua grossa ou sensível.","precautions":"A plaquinha central deve ficar plana sobre a língua: ela não deve ficar atravessada."}]},{"titre":"Os freios de alavanca","texte":"Essas embocaduras têm hastes. Quando a rédea puxa a parte de baixo da haste, o freio gira: é o efeito de alavanca.","cartes":[{"nom":"Princípio da alavanca","court":"Hastes, barbela e testeira agem juntas.","fonctionnement":"Ao girar, o freio pressiona as barras, a barbela se aperta na barbada (o sulco do queixo) e a testeira pressiona a nuca.","caracteristiques":"Quanto mais longa a haste abaixo do bocado, mais potente é o efeito para uma mesma tensão de rédea.","precautions":"A barbela deve estar bem ajustada e as rédeas devem ser usadas com grande suavidade."},{"nom":"Pelham","court":"Um único bocado com hastes, uma barbela e dois pares de rédeas.","fonctionnement":"A rédea presa em cima age sobretudo como um bridão; a de baixo acrescenta o efeito de alavanca.","caracteristiques":"Ele reúne em uma única embocadura os efeitos do bridão e do freio.","precautions":"Montado com uma única rédea (com uma peça de ligação entre as duas argolas), ele perde precisão."},{"nom":"Freio Pessoa","court":"Um bridão com várias argolas sobrepostas.","fonctionnement":"Dependendo da argola em que a rédea é presa, o efeito é próximo ao de um bridão ou acrescenta uma alavanca.","caracteristiques":"Quanto mais baixa a argola escolhida, mais marcado é o efeito de alavanca.","precautions":"Reservado a cavaleiros de mão segura, e o ajuste deve ser escolhido com o instrutor."}]},{"titre":"A embocadura dupla (freio e bridão)","texte":"A embocadura dupla reúne duas embocaduras na boca do cavalo: um bridão fino, chamado bridão de freio, e um freio de hastes com sua barbela, cada um com seu par de rédeas.","cartes":[{"nom":"Freio (Weymouth) e bridão de freio","court":"Duas embocaduras, quatro rédeas.","fonctionnement":"O bridão de freio age sobre a comissura e eleva; o freio acrescenta o efeito de alavanca sobre as barras, o queixo e a nuca. O cavaleiro dosa cada rédea separadamente.","caracteristiques":"Usada no adestramento de alto nível e em traje tradicional. Montar com freio e bridão faz parte do programa do Galop 7.","precautions":"Exige uma mão independente, um assento estável e um cavalo já bem treinado no bridão."}]}],"matieres":{"titre":"Você sabia?","texte":"As embocaduras existem em vários materiais: aço inoxidável, cobre ou ligas que favorecem a salivação, borracha e materiais sintéticos mais macios. Uma boca que saliva um pouco e que mastiga geralmente é uma boca relaxada."}},"s3":{"num":"03","titre":"Anatomia e zonas de ação","intro":"A embocadura repousa em um espaço bem preciso: entre os incisivos e os molares, onde não há dentes. Ela age sobre várias zonas, que não reagem todas da mesma maneira.","schemaTitre":"Esquema simplificado de uma cabeça de cavalo","schemaNote":"Esquema didático, proporções simplificadas.","zones":[{"nom":"A língua","texte":"Recebe grande parte da pressão, sobretudo com um bocado reto ou de dupla articulação."},{"nom":"As barras","texte":"Parte da mandíbula sem dentes, entre os incisivos e os molares. Ali a gengiva cobre diretamente o osso: é uma zona muito sensível."},{"nom":"As comissuras e os lábios","texte":"Os cantos da boca. O bridão age ali, sobretudo quando eleva ou durante uma rédea de abertura."},{"nom":"O palato","texte":"A parte de cima da boca. Uma articulação simples que se dobra demais pode chegar a tocá-lo."},{"nom":"A nuca","texte":"Com um freio de alavanca, a testeira transmite uma pressão sobre o alto da cabeça."},{"nom":"O queixo","texte":"A barbela de um freio de hastes se posiciona na barbada (o sulco do queixo) e pressiona ali quando o freio gira."}],"mecaTitre":"Três formas de agir","mecanismes":[{"nom":"Pressão direta","texte":"Com um bridão, a tensão da rédea chega à língua, às barras e às comissuras, na direção em que a mão puxa."},{"nom":"Efeito de alavanca","texte":"Com hastes, o freio gira: a força é multiplicada e se distribui entre as barras, o queixo e a nuca."},{"nom":"Ação lateral","texte":"As argolas fixas ou as pernas pressionam a bochecha oposta à rédea de abertura e ajudam o cavalo a virar."}]},"s4":{"num":"04","titre":"Como escolher uma embocadura?","intro":"Não existe uma « boa » embocadura de forma absoluta: existe uma embocadura adequada a um cavalo, a um cavaleiro e a um momento do trabalho deles. Veja os critérios a observar, com o seu instrutor.","criteres":[{"nom":"A boca do cavalo","texte":"A largura dela determina o tamanho da embocadura. Uma língua grossa ou um palato baixo muitas vezes pedem um bocado mais fino ou de dupla articulação."},{"nom":"A sensibilidade dele","texte":"Um cavalo muito sensível muitas vezes ficará mais à vontade com uma embocadura estável e suave."},{"nom":"O nível de adestramento dele","texte":"Um cavalo jovem começa com o bridão simples. Os freios de alavanca e a embocadura dupla vêm depois, com um cavalo experiente."},{"nom":"A modalidade","texte":"O regulamento de cada modalidade define as embocaduras permitidas em competição. Verifique sempre o regulamento federal em vigor."},{"nom":"A mão do cavaleiro","texte":"Quanto mais potente for uma embocadura, mais ela exige uma mão fixa, suave e independente do assento."},{"nom":"O ajuste e o conforto","texte":"A melhor embocadura só funciona bem se estiver no tamanho certo e ajustada na altura certa."}],"important":{"titre":"O conselho do instrutor","texte":"Um freio mais severo nunca substitui um trabalho de adestramento correto. Se o seu cavalo puxa, se apoia ou abre a boca, procure primeiro a causa: sua mão, seu equilíbrio, o relaxamento dele, os dentes dele, o ajuste do equipamento. Troque de embocadura somente com a opinião do seu instrutor."}},"s5":{"num":"05","titre":"Ajuste e manutenção","intro":"Uma embocadura bem escolhida, mas mal ajustada, logo se torna desconfortável. Crie o hábito de verificar estes pontos antes de cada aula.","verifTitre":"As verificações antes de montar","verifs":["A largura: a embocadura sobra cerca de meio centímetro de cada lado da boca, sem apertar os lábios.","A altura: com um bridão, geralmente se vê uma ou duas pequenas rugas no canto dos lábios. Sem ruga, o bridão está baixo demais; com muitas rugas, está alto demais.","A barbela: fica plana na barbada (o sulco do queixo); deve ser possível passar dois dedos entre a barbela e o queixo.","O estado: nenhuma aresta viva, nenhum desgaste nos furos das argolas ou nas articulações, nenhuma peça que belisque.","Os couros: os montantes, as fivelas e as rédeas estão macios e em bom estado."],"entretienTitre":"Depois da aula","entretien":"Enxágue a embocadura com água limpa assim que desencilhar, antes que a saliva e o capim sequem. Enxugue-a, deixe secar e depois cuide dos couros regularmente.","erreurs":{"titre":"Os erros a evitar","points":["Ajustar a altura do bridão « no chute », sem olhar as comissuras.","Manter uma embocadura danificada porque « o cavalo está acostumado ».","Apertar a barbela para « ter mais freio ».","Deixar a embocadura secar suja depois da aula."]}},"s6":{"num":"06","titre":"Casos especiais","intro":"No Galop 5, basta reconhecê-los e entender seu princípio. O uso deles é decidido com um instrutor.","cartes":[{"nom":"O bridão Baucher","court":"Um bridão com uma pequena argola adicional presa ao montante.","detail":"A embocadura fica suspensa e muito estável na boca. Ela convém aos cavalos que brincam muito com a embocadura."},{"nom":"As embocaduras macias","court":"De borracha ou de material sintético.","detail":"Suaves e leves, convêm a bocas sensíveis ou a cavalos jovens. Elas se desgastam mais rápido: verifique se não estão mordiscadas ou rachadas."},{"nom":"O hackamore","court":"Uma cabeçada sem embocadura.","detail":"Ele age por pressão sobre o chanfro, o queixo e a nuca, sem nada na boca. Não é por princípio uma solução « mais suave »: mal ajustado, pode ser muito severo."},{"nom":"A focinheira","court":"Ela não é uma embocadura, mas muda o efeito dela.","detail":"Uma focinheira apertada demais impede o cavalo de mastigar e torna o contato duro. Deve ser possível passar dois dedos entre a focinheira e o chanfro."}]},"lateral":{"observerTitre":"Para observar","observer":"Na sua próxima aula, olhe a boca do cavalo: está fechada e calma? Ele mastiga um pouco? Dá para ver uma ou duas rugas nas comissuras? Uma boca relaxada muitas vezes mostra um cavalo relaxado.","defiTitre":"O desafio do cavaleiro","defi":"Na selaria do seu clube, encontre três embocaduras diferentes e dê o nome delas: tipo de argolas, forma do bocado, ação direta ou alavanca. Depois mostre sua resposta ao seu instrutor."},"videos":{"titre":"Para entender melhor com imagens","v1":"Reconhecer as principais famílias de embocaduras","v2":"Entender os diferentes efeitos de um freio","v3":"Verificar o ajuste de uma embocadura","aVenir":"Vídeo em breve","tous":"Ver toda a videoteca"},"quiz":{"titre":"Teste seus conhecimentos","texte":"Terminou esta lição? Verifique o que você aprendeu.","bouton":"Acessar o quiz","bientot":"Em breve"}},"ru":{"meta":{"kicker":"Galop 5 · Конная культура","titre":"Удила","sous":"Понять, как они действуют, и правильно их выбрать.","duree":"Около 20 минут чтения","type":"Теоретический урок","audio":"Аудиоверсия","langues":"Доступно на всех 14 языках","retour":"Уроки Galop 5","progression":"Прогресс чтения","sommaire":"Содержание урока","photoAVenir":"Фото скоро появится","agrandir":"Увеличить фото","fermer":"Закрыть","voirPlus":"Подробнее","voirMoins":"Скрыть подробности","fonctionnement":"Как действует","caracteristiques":"Полезно знать","precautions":"Меры предосторожности"},"nav":["Зачем","Виды","Анатомия","Выбор","Подгонка","Особые случаи"],"s1":{"num":"01","titre":"Зачем нужны удила?","paras":["Удила — это деталь из металла или мягкого материала, которая находится во рту лошади и соединена с поводьями. Они передают лошади действия твоей руки: это одно из средств общения между тобой и лошадью, наряду с шенкелями, посадкой и голосом.","Хороший контакт — это лёгкая, эластичная и постоянная связь между твоей рукой и ртом лошади. Твоя рука сопровождает движение шеи, особенно на шагу и галопе, чтобы лошадь находила в удилах стабильную и успокаивающую опору, а не помеху.","Рот лошади очень чувствителен. Каждое действие поводом — полуодержка, открывающий повод, противоположный (опорный) повод — должно быть коротким, дозированным и отданным, как только лошадь ответила. Именно уступая в нужный момент, рука поощряет лошадь, и лошадь учится."],"retenir":{"titre":"Запомни","points":["Удила передают действия руки: они не заменяют ни шенкеля, ни посадку.","Контакт должен быть лёгким, эластичным и ровным.","Повод отдают, как только лошадь ответила."]}},"s2":{"num":"02","titre":"Основные виды удил","intro":"Удила классифицируют по двум основным критериям: форма грызла (части, которая находится во рту) и способ его соединения с поводьями (трензельные кольца или щёчки мундштука). Нажми на карточку, чтобы узнать подробности.","groupes":[{"titre":"Трензели: прямое действие","texte":"С трензелем повод действует на удила напрямую, без рычага: давление, которое чувствует лошадь, соответствует натяжению повода.","cartes":[{"nom":"Трензель с оливками","court":"Кольца закреплены на грызле с помощью оливок.","fonctionnement":"Оливки не дают удилам вращаться и скользить: они остаются стабильными во рту.","caracteristiques":"Не защемляют углы рта. Часто выбирают для чувствительных лошадей или для тех, кто учится контакту.","precautions":"Проверь ширину: слишком узкие удила сдавливают губы, а слишком широкие смещаются в сторону."},{"nom":"Трензель с усиками","court":"Вертикальные усики продолжают кольца с обеих сторон рта.","fonctionnement":"При открывающем поводе усики давят на боковую сторону головы и помогают лошади повернуть. Они также не дают удилам протягиваться через рот.","caracteristiques":"Удобен для молодых лошадей и для тех, кем трудно управлять.","precautions":"Усики часто крепят к нащёчным ремням оголовья маленькими кожаными петлями, чтобы они ни за что не цеплялись."},{"nom":"D-образный трензель (Verdun)","court":"Неподвижные кольца в форме буквы «D» с прямой стороной, прилегающей к щеке.","fonctionnement":"Прямая сторона кольца прижата к щеке: удила стабильны, и лошадь чётко чувствует открывающий повод.","caracteristiques":"Не защемляет углы рта. Используется и в выездке, и в конкуре, и на скачках.","precautions":"Как и у любого трензеля с неподвижными кольцами, ширина должна быть точной."},{"nom":"Трензель со свободными кольцами","court":"Кольца свободно скользят в отверстиях грызла.","fonctionnement":"Удила больше двигаются во рту, что часто побуждает лошадь жевать и расслабляться.","caracteristiques":"Это самый распространённый трензель.","precautions":"Если отверстия изношены или удила слишком узкие, кольца могут защемлять углы рта: регулярно их проверяй."}]},{"titre":"Форма грызла","texte":"Независимо от типа колец, форма грызла меняет то, как давление распределяется во рту.","cartes":[{"nom":"Прямое грызло","court":"Цельное грызло, жёсткое или слегка гибкое.","fonctionnement":"Давление распределяется на язык и беззубые края, одинаково справа и слева.","caracteristiques":"Стабильные удила, часто из резины или мягкого синтетического материала.","precautions":"Действия одним поводом менее точны, чем с членистым грызлом."},{"nom":"С одним сочленением","court":"Две части, соединённые в центре шарниром.","fonctionnement":"Когда натягиваются оба повода, грызло складывается: оно давит на язык и беззубые края и может подниматься к нёбу (эффект «щелкунчика»).","caracteristiques":"Позволяет действовать отдельно на каждую сторону рта.","precautions":"При жёсткой руке или у лошади с низким нёбом сочленение может касаться нёба."},{"nom":"С двойным сочленением","court":"Три части: небольшой центральный элемент (кольцо, оливка или пластинка) между двумя звеньями.","fonctionnement":"Центральный элемент повторяет форму языка: эффект «щелкунчика» сильно уменьшается.","caracteristiques":"Часто удобнее для лошадей с толстым или чувствительным языком.","precautions":"Центральная пластинка должна лежать на языке плашмя: она не должна вставать боком."}]},{"titre":"Удила рычажного действия","texte":"У этих удил есть щёчки (рычаги). Когда повод тянет за нижнюю часть щёчки, удила поворачиваются: это рычажное действие.","cartes":[{"nom":"Принцип рычага","court":"Щёчки, подбородная цепочка и затылочный ремень действуют вместе.","fonctionnement":"Поворачиваясь, удила давят на беззубые края, цепочка натягивается в подбородочной ямке, а затылочный ремень давит на затылок.","caracteristiques":"Чем длиннее щёчка ниже грызла, тем сильнее действие при одинаковом натяжении повода.","precautions":"Цепочка должна быть правильно отрегулирована, а поводья нужно использовать очень мягко."},{"nom":"Пелям","court":"Одно грызло со щёчками, подбородной цепочкой и двумя парами поводьев.","fonctionnement":"Верхний повод действует в основном как трензель; нижний добавляет рычажное действие.","caracteristiques":"Он объединяет в одних удилах действие трензеля и мундштука.","precautions":"С одним поводом (с соединительным ремешком между двумя кольцами) он теряет точность."},{"nom":"Удила Pessoa","court":"Трензель с несколькими кольцами, расположенными одно над другим.","fonctionnement":"В зависимости от кольца, к которому пристёгнут повод, действие близко к трензелю или добавляет рычаг.","caracteristiques":"Чем ниже выбранное кольцо, тем сильнее рычажное действие.","precautions":"Только для всадников с уверенной рукой; регулировку нужно выбирать вместе с тренером."}]},{"titre":"Мундштучное оголовье","texte":"Мундштучное оголовье объединяет во рту лошади двое удил: тонкий трензель, который называется бридонным, и мундштук со щёчками и подбородной цепочкой, — у каждого своя пара поводьев.","cartes":[{"nom":"Мундштук (Weymouth) и бридонный трензель","court":"Двое удил, четыре повода.","fonctionnement":"Бридонный трензель действует на углы рта и поднимает голову; мундштук добавляет рычажное действие на беззубые края, подбородок и затылок. Всадник дозирует каждый повод отдельно.","caracteristiques":"Используется в выездке высокого уровня и при традиционной форме одежды. Езда на мундштуке входит в программу Galop 7.","precautions":"Требует независимой руки, стабильной посадки и лошади, уже хорошо выезженной на трензеле."}]}],"matieres":{"titre":"А ты знаешь?","texte":"Удила бывают из разных материалов: нержавеющая сталь, медь или сплавы, усиливающие слюноотделение, резина и более мягкие синтетические материалы. Рот, который немного выделяет слюну и жуёт, — как правило, расслабленный рот."}},"s3":{"num":"03","titre":"Анатомия и зоны воздействия","intro":"Удила лежат в строго определённом месте: между резцами и коренными зубами, где зубов нет. Они действуют на несколько зон, и все они реагируют по-разному.","schemaTitre":"Упрощённая схема головы лошади","schemaNote":"Учебная схема, пропорции упрощены.","zones":[{"nom":"Язык","texte":"Принимает на себя значительную часть давления, особенно с прямым грызлом или грызлом с двойным сочленением."},{"nom":"Беззубые края","texte":"Участок нижней челюсти без зубов, между резцами и коренными зубами. Десна там прямо покрывает кость: это очень чувствительная зона."},{"nom":"Углы рта и губы","texte":"Уголки рта. Трензель действует на них, особенно когда поднимает голову или при открывающем поводе."},{"nom":"Нёбо","texte":"Верхняя часть рта. Грызло с одним сочленением, которое слишком сильно складывается, может его касаться."},{"nom":"Затылок","texte":"С рычажными удилами затылочный ремень передаёт давление на верх головы."},{"nom":"Подбородок","texte":"Подбородная цепочка мундштука лежит в подбородочной ямке и давит на неё, когда удила поворачиваются."}],"mecaTitre":"Три способа воздействия","mecanismes":[{"nom":"Прямое давление","texte":"С трензелем натяжение повода передаётся на язык, беззубые края и углы рта, в направлении, куда тянет рука."},{"nom":"Рычажное действие","texte":"Со щёчками удила поворачиваются: сила умножается и распределяется между беззубыми краями, подбородком и затылком."},{"nom":"Боковое действие","texte":"Неподвижные кольца или усики давят на щеку с противоположной открывающему поводу стороны и помогают лошади повернуть."}]},"s4":{"num":"04","titre":"Как выбрать удила?","intro":"Не существует «хороших» удил вообще: есть удила, подходящие конкретной лошади, конкретному всаднику и определённому этапу их работы. Вот критерии, на которые стоит смотреть вместе с тренером.","criteres":[{"nom":"Рот лошади","texte":"Его ширина определяет размер удил. Толстый язык или низкое нёбо часто требуют более тонкого грызла или грызла с двойным сочленением."},{"nom":"Её чувствительность","texte":"Очень чувствительной лошади часто комфортнее со стабильными и мягкими удилами."},{"nom":"Её уровень выездки","texte":"Молодая лошадь начинает с простого трензеля. Рычажные удила и мундштучное оголовье появляются позже, у опытной лошади."},{"nom":"Дисциплина","texte":"Правила каждой дисциплины определяют, какие удила разрешены на соревнованиях. Всегда проверяй действующие правила федерации."},{"nom":"Рука всадника","texte":"Чем сильнее удила, тем более неподвижной, мягкой и независимой от посадки должна быть рука."},{"nom":"Подгонка и комфорт","texte":"Даже лучшие удила хорошо работают, только если они правильного размера и отрегулированы на правильной высоте."}],"important":{"titre":"Совет тренера","texte":"Более жёсткие удила никогда не заменят правильной работы по выездке. Если твоя лошадь тянет, виснет на поводу или открывает рот, сначала ищи причину: твоя рука, твой баланс, её расслабленность, её зубы, регулировка снаряжения. Меняй удила только по совету своего тренера."}},"s5":{"num":"05","titre":"Подгонка и уход","intro":"Хорошо подобранные, но плохо отрегулированные удила быстро становятся неудобными. Возьми за привычку проверять эти пункты перед каждым занятием.","verifTitre":"Проверки перед посадкой","verifs":["Ширина: удила выступают примерно на полсантиметра с каждой стороны рта и не сдавливают губы.","Высота: с трензелем обычно видны одна-две небольшие складки в углах губ. Без складок трензель слишком низко; с большим количеством складок — слишком высоко.","Подбородная цепочка: лежит плоско в подбородочной ямке; между цепочкой и подбородком должны проходить два пальца.","Состояние: никаких острых краёв, никакого износа в отверстиях колец или в сочленениях, ничего, что защемляет.","Кожаные детали: нащёчные ремни, пряжки и поводья мягкие и в хорошем состоянии."],"entretienTitre":"После занятия","entretien":"Сполосни удила чистой водой сразу после расседлывания, пока слюна и трава не засохли. Вытри их, дай высохнуть, а затем регулярно ухаживай за кожаными деталями.","erreurs":{"titre":"Ошибки, которых нужно избегать","points":["Регулировать высоту трензеля «наугад», не глядя на углы рта.","Оставлять повреждённые удила, потому что «лошадь к ним привыкла».","Затягивать подбородную цепочку, чтобы «было больше тормоза».","Оставлять грязные удила сохнуть после занятия."]}},"s6":{"num":"06","titre":"Особые случаи","intro":"На уровне Galop 5 достаточно уметь их узнавать и понимать принцип их действия. Решение об их использовании принимается вместе с тренером.","cartes":[{"nom":"Трензель Боше (Baucher)","court":"Трензель с небольшим дополнительным кольцом, которое крепится к нащёчному ремню.","detail":"Удила остаются подвешенными и очень стабильными во рту. Они подходят лошадям, которые много играют удилами."},{"nom":"Мягкие удила","court":"Из резины или синтетического материала.","detail":"Мягкие и лёгкие, они подходят для чувствительного рта или молодых лошадей. Они быстрее изнашиваются: проверяй, что они не погрызены и не треснули."},{"nom":"Хакамора","court":"Оголовье без удил.","detail":"Она действует давлением на переносицу, подбородок и затылок, ничего не находится во рту. Это не «более мягкое» решение само по себе: при плохой регулировке она может быть очень жёсткой."},{"nom":"Капсюль","court":"Это не удила, но он меняет их действие.","detail":"Слишком туго затянутый капсюль не даёт лошади жевать и делает контакт жёстким. Между капсюлем и переносицей должны проходить два пальца."}]},"lateral":{"observerTitre":"Понаблюдай","observer":"На следующем занятии посмотри на рот лошади: он закрыт и спокоен? Она немного жуёт? Видны ли одна-две складки в углах рта? Расслабленный рот часто говорит о расслабленной лошади.","defiTitre":"Задание для всадника","defi":"В амуничнике своего клуба найди трое разных удил и назови их: тип колец, форма грызла, прямое или рычажное действие. Потом покажи свой ответ тренеру."},"videos":{"titre":"Чтобы лучше понять на видео","v1":"Как распознать основные виды удил","v2":"Как понять разные виды действия удил","v3":"Как проверить подгонку удил","aVenir":"Видео скоро появится","tous":"Смотреть всю видеотеку"},"quiz":{"titre":"Проверь свои знания","texte":"Закончил(а) этот урок? Проверь, что ты запомнил(а).","bouton":"Перейти к тесту","bientot":"Скоро"}},"sv":{"meta":{"kicker":"Galop 5 · Hästkunskap","titre":"Betten","sous":"Förstå hur de verkar och välj rätt.","duree":"Cirka 20 min läsning","type":"Teorilektion","audio":"Lyssna","langues":"Finns på 14 språk","retour":"Lektionerna i Galop 5","progression":"Läsframsteg","sommaire":"Lektionens innehåll","photoAVenir":"Foto kommer snart","agrandir":"Förstora fotot","fermer":"Stäng","voirPlus":"Visa detaljer","voirMoins":"Dölj detaljer","fonctionnement":"Verkan","caracteristiques":"Bra att veta","precautions":"Tänk på"},"nav":["Varför","Typer","Anatomi","Välja","Justera","Specialfall"],"s1":{"num":"01","titre":"Varför använda ett bett?","paras":["Bettet är den del av metall eller mjukt material som ligger i hästens mun och är fäst vid tyglarna. Det förmedlar din hands hjälper till hästen: tillsammans med skänklarna, sitsen och rösten är det ett av sätten som du och hästen kommunicerar på.","En bra kontakt är en lätt, elastisk och jämn förbindelse mellan din hand och hästens mun. Din hand följer halsens rörelse, särskilt i skritt och galopp, så att hästen hittar ett stabilt och tryggt stöd i bettet och aldrig upplever det som obehagligt.","Hästens mun är mycket känslig. Varje tygelhjälp – halvhalt, öppnande tygel, motsatt tygel – ska vara kort och avvägd och släppas efter så snart hästen svarar. Det är genom att ge efter i rätt ögonblick som handen belönar och hästen lär sig."],"retenir":{"titre":"Kom ihåg","points":["Bettet förmedlar handens hjälper: det ersätter varken skänklarna eller sitsen.","Kontakten ska vara lätt, elastisk och jämn.","En tygelhjälp släpps efter så snart hästen har svarat."]}},"s2":{"num":"02","titre":"De olika typerna av bett","intro":"Bett delas in efter två huvudkriterier: munstyckets form (den del som ligger i munnen) och hur det är kopplat till tyglarna (tränsringar eller skänklar på ett stångbett). Tryck på ett kort för att se detaljerna.","groupes":[{"titre":"Tränsbett: direkt verkan","texte":"Med ett tränsbett verkar tygeln direkt på bettet, utan hävstångsverkan: trycket som hästen känner motsvarar spänningen i tygeln.","cartes":[{"nom":"Olivtränsbett","court":"Ringarna är fästa vid munstycket med oliver.","fonctionnement":"Oliverna hindrar bettet från att vrida sig och glida: det ligger stilla i munnen.","caracteristiques":"Nyper inte i mungiporna. Väljs ofta till känsliga hästar eller hästar som håller på att lära sig kontakten.","precautions":"Kontrollera bredden: ett för smalt bett klämmer läpparna, ett för brett glider åt sidan."},{"nom":"Knebeltränsbett","court":"Lodräta knebel förlänger ringarna på båda sidor om munnen.","fonctionnement":"Vid en öppnande tygel trycker knebeln mot sidan av huvudet och hjälper hästen att svänga. De hindrar också bettet från att glida genom munnen.","caracteristiques":"Praktiskt för unga hästar och för hästar som är svåra att styra.","precautions":"Knebeln fästs ofta i huvudlagets kindstycken med små läderöglor, så att de inte fastnar någonstans."},{"nom":"D-ringsbett (Verdun)","court":"Fasta ringar formade som ett ”D”, med en rak sida mot kinden.","fonctionnement":"Ringens raka sida ligger an mot kinden: bettet ligger stilla och hästen känner tydligt den öppnande tygeln.","caracteristiques":"Nyper inte i mungiporna. Används både i dressyr, i hoppning och i galoppsport.","precautions":"Som för alla tränsbett med fasta ringar måste bredden vara exakt rätt."},{"nom":"Tränsbett med lösa ringar","court":"Ringarna glider fritt genom hålen i munstycket.","fonctionnement":"Bettet rör sig mer i munnen, vilket ofta uppmuntrar hästen att tugga och slappna av.","caracteristiques":"Det är det vanligaste tränsbettet.","precautions":"Om hålen är slitna eller bettet för smalt kan ringarna nypa mungiporna: kontrollera dem regelbundet."}]},{"titre":"Munstyckets form","texte":"Oavsett typ av ringar påverkar munstyckets form hur trycket fördelas i munnen.","cartes":[{"nom":"Rakt munstycke","court":"Ett munstycke i ett stycke, styvt eller lätt böjligt.","fonctionnement":"Trycket fördelas jämnt till höger och vänster över tungan och lanerna.","caracteristiques":"Ett stabilt bett, finns ofta i gummi eller mjukt syntetmaterial.","precautions":"Hjälper med en tygel i taget blir mindre exakta än med ett brutet munstycke."},{"nom":"Enkelbrutet","court":"Två delar som är sammankopplade med en led i mitten.","fonctionnement":"När båda tyglarna sträcks viker sig munstycket: det trycker på tungan och lanerna och kan pressas upp mot gommen (”nötknäpparverkan”).","caracteristiques":"Gör det möjligt att verka på varje sida av munnen för sig.","precautions":"Med en hård hand eller hos en häst med låg gom kan leden nå upp till gommen."},{"nom":"Dubbelbrutet","court":"Tre delar: en liten mittdel (ring, oliv eller platta) mellan två munstycksdelar.","fonctionnement":"Mittdelen formar sig efter tungan: ”nötknäpparverkan” blir mycket mindre.","caracteristiques":"Ofta bekvämare för hästar med tjock eller känslig tunga.","precautions":"Mittplattan ska ligga platt mot tungan: den får inte hamna snett."}]},{"titre":"Bett med hävstångsverkan","texte":"De här betten har skänklar. När tygeln drar i skänkelns nedre del vrider sig bettet: det är hävstångsverkan.","cartes":[{"nom":"Hävstångsprincipen","court":"Skänklar, kindkedja och nackstycke verkar tillsammans.","fonctionnement":"När bettet vrider sig trycker det på lanerna, kindkedjan spänns i hakgropen och nackstycket trycker på nacken.","caracteristiques":"Ju längre skänkeln under munstycket är, desto kraftigare blir verkan vid samma tygelspänning.","precautions":"Kindkedjan måste vara rätt justerad och tyglarna ska användas med stor mjukhet."},{"nom":"Pelham","court":"Ett enda munstycke med skänklar, kindkedja och två par tyglar.","fonctionnement":"Den övre tygeln verkar främst som ett tränsbett; den nedre lägger till hävstångsverkan.","caracteristiques":"Den förenar tränsbettets och stångbettets verkan i ett och samma bett.","precautions":"Riden med bara en tygel (med en kopplingsrem mellan de två ringarna) blir den mindre exakt."},{"nom":"Pessoabett","court":"Ett tränsbett med flera ringar ovanför varandra.","fonctionnement":"Beroende på vilken ring tygeln är fäst i verkar det nästan som ett tränsbett eller med hävstång.","caracteristiques":"Ju lägre ring som väljs, desto tydligare hävstångsverkan.","precautions":"Bara för ryttare med en säker hand, och inställningen ska väljas tillsammans med ridläraren."}]},{"titre":"Kandaret","texte":"Med kandar ligger två bett i hästens mun: ett tunt tränsbett, kallat bridong, och ett stångbett med skänklar och kindkedja, vart och ett med sitt eget par tyglar.","cartes":[{"nom":"Stångbett och bridong","court":"Två bett, fyra tyglar.","fonctionnement":"Bridongen verkar på mungiporna och reser; stångbettet lägger till hävstångsverkan på lanerna, hakan och nacken. Ryttaren doserar varje tygel för sig.","caracteristiques":"Används i dressyr på hög nivå och i traditionell klädsel. Ridning på kandar ingår i programmet för Galop 7.","precautions":"Kräver en självständig hand, en stabil sits och en häst som redan är väl utbildad på tränsbett."}]}],"matieres":{"titre":"Visste du?","texte":"Bett finns i flera material: rostfritt stål, koppar eller legeringar som främjar salivering, gummi och mjukare syntetmaterial. En mun som saliverar lite och tuggar är oftast en avslappnad mun."}},"s3":{"num":"03","titre":"Anatomi och verkningsområden","intro":"Bettet ligger på en mycket bestämd plats: mellan framtänderna och kindtänderna, där det inte finns några tänder. Det verkar på flera områden, som inte alla reagerar på samma sätt.","schemaTitre":"Förenklad skiss av ett hästhuvud","schemaNote":"Pedagogisk skiss, förenklade proportioner.","zones":[{"nom":"Tungan","texte":"Den tar emot en stor del av trycket, särskilt med ett rakt eller dubbelbrutet munstycke."},{"nom":"Lanerna","texte":"Den tandlösa delen av underkäken, mellan framtänderna och kindtänderna. Där ligger tandköttet direkt på benet: ett mycket känsligt område."},{"nom":"Mungiporna och läpparna","texte":"Munnens hörn. Här verkar tränsbettet, särskilt när det reser eller vid en öppnande tygel."},{"nom":"Gommen","texte":"Munnens tak. Ett enkelbrutet bett som viker sig för mycket kan nå upp till den."},{"nom":"Nacken","texte":"Med ett hävstångsbett förmedlar nackstycket ett tryck på huvudets ovansida."},{"nom":"Hakan","texte":"Kindkedjan på ett stångbett ligger i hakgropen och trycker där när bettet vrider sig."}],"mecaTitre":"Tre sätt att verka","mecanismes":[{"nom":"Direkt tryck","texte":"Med ett tränsbett hamnar tygelns spänning på tungan, lanerna och mungiporna, i den riktning handen drar."},{"nom":"Hävstångsverkan","texte":"Med skänklar vrider sig bettet: kraften förstärks och fördelas mellan lanerna, hakan och nacken."},{"nom":"Sidoverkan","texte":"Fasta ringar eller knebel trycker mot kinden på motsatt sida från den öppnande tygeln och hjälper hästen att svänga."}]},"s4":{"num":"04","titre":"Hur väljer man bett?","intro":"Det finns inget ”bra” bett i sig: det finns ett bett som passar en häst, en ryttare och ett visst skede i deras arbete. Här är kriterierna att titta på tillsammans med din ridlärare.","criteres":[{"nom":"Hästens mun","texte":"Munnens bredd avgör bettets storlek. En tjock tunga eller en låg gom kräver ofta ett tunnare eller dubbelbrutet munstycke."},{"nom":"Hästens känslighet","texte":"En mycket känslig häst trivs ofta bättre med ett stabilt och mjukt bett."},{"nom":"Hästens utbildningsnivå","texte":"En ung häst börjar på ett enkelt tränsbett. Hävstångsbett och kandar kommer senare, med en färdigutbildad häst."},{"nom":"Grenen","texte":"Varje grens reglemente fastställer vilka bett som är tillåtna på tävling. Kontrollera alltid det gällande förbundsreglementet."},{"nom":"Ryttarens hand","texte":"Ju kraftigare ett bett är, desto mer kräver det en stadig, följsam hand som är oberoende av sitsen."},{"nom":"Passform och komfort","texte":"Även det bästa bettet fungerar bara bra om det har rätt storlek och sitter på rätt höjd."}],"important":{"titre":"Tränarens råd","texte":"Ett skarpare bett ersätter aldrig korrekt utbildning. Om din häst drar, lägger sig på bettet eller gapar, leta först efter orsaken: din hand, din balans, hästens avspänning, tänderna, utrustningens justering. Byt bett bara efter att ha frågat din ridlärare."}},"s5":{"num":"05","titre":"Justering och skötsel","intro":"Ett väl valt men dåligt justerat bett blir snabbt obekvämt. Gör det till en vana att kontrollera de här punkterna före varje ridpass.","verifTitre":"Kontrollerna innan du sitter upp","verifs":["Bredden: bettet sticker ut ungefär en halv centimeter på varje sida av munnen, utan att klämma läpparna.","Höjden: med ett tränsbett ser man oftast en eller två små veck i mungipan. Utan veck sitter tränsbettet för lågt; med många veck sitter det för högt.","Kindkedjan: den ligger platt i hakgropen; man ska kunna sticka in två fingrar mellan kindkedjan och hakan.","Skicket: inga vassa kanter, inget slitage vid ringhålen eller lederna, ingen del som nyper.","Lädret: kindstycken, spännen och tyglar är mjuka och i gott skick."],"entretienTitre":"Efter ridpasset","entretien":"Skölj bettet i rent vatten så fort du har sadlat av, innan saliv och gräs torkar in. Torka av det, låt det torka och sköt om lädret regelbundet.","erreurs":{"titre":"Misstag att undvika","points":["Att justera tränsbettets höjd ”på måfå” utan att titta på mungiporna.","Att behålla ett skadat bett för att ”hästen är van vid det”.","Att dra åt kindkedjan för att ”få mer broms”.","Att låta bettet torka smutsigt efter ridpasset."]}},"s6":{"num":"06","titre":"Specialfall","intro":"På Galop 5 räcker det att känna igen dem och förstå principen. Om de ska användas bestäms tillsammans med en ridlärare.","cartes":[{"nom":"Baucherbettet","court":"Ett tränsbett med en extra liten ring som fästs i kindstycket.","detail":"Bettet hänger i munnen och ligger mycket stilla. Det passar hästar som leker mycket med bettet."},{"nom":"Mjuka bett","court":"Av gummi eller syntetmaterial.","detail":"Mjuka och lätta, de passar känsliga munnar eller unga hästar. De slits fortare: kontrollera att de inte är söndertuggade eller spruckna."},{"nom":"Hackamore","court":"Ett betslöst huvudlag.","detail":"Den verkar genom tryck på nosryggen, hakan och nacken, utan något i munnen. Den är inte en ”mjukare” lösning i sig: felaktigt justerad kan den vara mycket skarp."},{"nom":"Nosgrimman","court":"Den är inget bett, men den påverkar bettets verkan.","detail":"En för hårt spänd nosgrimma hindrar hästen från att tugga och gör kontakten hård. Man ska kunna sticka in två fingrar mellan nosgrimman och nosryggen."}]},"lateral":{"observerTitre":"Att observera","observer":"Titta på hästens mun under ditt nästa ridpass: är den stängd och lugn? Tuggar hästen lite? Syns det ett eller två veck i mungiporna? En avslappnad mun visar ofta en avslappnad häst.","defiTitre":"Ryttarens utmaning","defi":"Leta upp tre olika bett i sadelkammaren på din klubb och namnge dem: typ av ringar, munstyckets form, direkt verkan eller hävstång. Visa sedan ditt svar för din ridlärare."},"videos":{"titre":"Förstå bättre med bilder","v1":"Känna igen de viktigaste typerna av bett","v2":"Förstå ett betts olika verkan","v3":"Kontrollera hur ett bett sitter","aVenir":"Video kommer snart","tous":"Se hela videobiblioteket"},"quiz":{"titre":"Testa dina kunskaper","texte":"Har du läst klart lektionen? Kolla vad du kommer ihåg.","bouton":"Till quizet","bientot":"Snart"}},"zh":{"meta":{"kicker":"Galop 5 · 马术文化","titre":"衔铁","sous":"理解它们的作用，学会正确选择。","duree":"阅读约需 20 分钟","type":"理论课","audio":"语音朗读","langues":"提供全部 14 种语言","retour":"Galop 5 课程","progression":"阅读进度","sommaire":"课程目录","photoAVenir":"照片即将上线","agrandir":"放大照片","fermer":"关闭","voirPlus":"查看详情","voirMoins":"收起详情","fonctionnement":"工作原理","caracteristiques":"须知","precautions":"注意事项"},"nav":["为什么","种类","解剖","选择","调整","特殊情况"],"s1":{"num":"01","titre":"为什么要用衔铁？","paras":["衔铁是放在马嘴里、与缰绳相连的金属或软质部件。它把你手上的动作传递给马：它和腿、骑坐、声音一样，是你和马之间沟通的方式之一。","好的衔接，是你的手和马嘴之间一种轻柔、有弹性且稳定的联系。你的手要跟随马颈的动作，尤其是在慢步和跑步时，这样马才会在衔铁上感受到稳定、安心的支撑，而不是不适。","马嘴非常敏感。每一个缰绳动作——半减却、开缰、反缰——都要短促、有分寸，马一回应就立刻放松。正是在恰当的时机让步，手才是在奖励马，马也才能学会。"],"retenir":{"titre":"要点","points":["衔铁传递手的动作：它不能代替腿，也不能代替骑坐。","衔接必须轻柔、有弹性且均匀。","马一回应，缰绳动作就要放松。"]}},"s2":{"num":"02","titre":"衔铁的不同种类","intro":"衔铁主要按两大标准分类：衔体（进入嘴里的部分）的形状，以及它与缰绳的连接方式（水勒衔环或大勒衔铁的衔杆）。点一下卡片，看看详细内容。","groupes":[{"titre":"水勒衔铁：直接作用","texte":"使用水勒衔铁时，缰绳直接作用于衔铁，没有杠杆效应：马感受到的压力就等于缰绳的张力。","cartes":[{"nom":"蛋形环水勒（橄榄环）","court":"衔环通过橄榄形接头固定在衔体上。","fonctionnement":"橄榄形接头防止衔铁转动和左右滑动：它在嘴里保持稳定。","caracteristiques":"不会夹嘴角。常用于敏感的马或正在学习衔接的马。","precautions":"检查宽度：衔铁太窄会勒紧嘴唇，太宽则会偏离中心。"},{"nom":"全颊水勒","court":"竖直的颊杆从衔环向嘴的两侧延伸。","fonctionnement":"使用开缰时，颊杆压在头的侧面，帮助马转弯。它们还能防止衔铁在嘴里滑动。","caracteristiques":"适合年轻马和不太好控制方向的马。","precautions":"通常用小皮扣把颊杆固定在颊带上，以免它们挂到别的东西。"},{"nom":"D 环水勒（Verdun）","court":"固定的“D”形衔环，直边贴着脸颊。","fonctionnement":"衔环的直边紧贴脸颊：衔铁稳定，马能清楚地感受到开缰。","caracteristiques":"不会夹嘴角。平地训练、障碍和赛马都会用到。","precautions":"和所有固定衔环的水勒衔铁一样，宽度必须合适。"},{"nom":"活环水勒","court":"衔环可以在衔体的孔中自由滑动。","fonctionnement":"衔铁在嘴里活动更多，这常常会鼓励马咀嚼衔铁并放松下来。","caracteristiques":"这是最常见的水勒衔铁。","precautions":"如果孔磨损了或衔铁太窄，衔环可能会夹到嘴角：要经常检查。"}]},{"titre":"衔体的形状","texte":"无论是哪种衔环，衔体的形状都会改变压力在嘴里的分布方式。","cartes":[{"nom":"直杆衔铁","court":"整根的衔体，硬质或略有弹性。","fonctionnement":"压力分布在舌头和齿槽间缘上，左右均等。","caracteristiques":"衔铁稳定，常见橡胶或软质合成材料的款式。","precautions":"单侧缰绳的动作不如分节衔铁精确。"},{"nom":"单节衔铁","court":"两段在中间用一个关节相连。","fonctionnement":"两侧缰绳同时拉紧时，衔体会折起来：它压住舌头和齿槽间缘，并可能向上顶到上颚（“胡桃夹子”效应）。","caracteristiques":"可以分别作用于嘴的每一侧。","precautions":"如果手太硬，或者马的上颚较低，关节可能会碰到上颚。"},{"nom":"双节衔铁","court":"三段：两根衔杆之间有一个小的中间件（环、橄榄形或片状）。","fonctionnement":"中间件贴合舌头的形状：“胡桃夹子”效应大大减弱。","caracteristiques":"对舌头厚或敏感的马来说，通常更舒服。","precautions":"中间的片必须平贴在舌头上：不能歪斜。"}]},{"titre":"带杠杆作用的衔铁","texte":"这类衔铁带有衔杆。当缰绳拉动衔杆下端时，衔铁会转动：这就是杠杆效应。","cartes":[{"nom":"杠杆原理","court":"衔杆、下颌链和项带共同作用。","fonctionnement":"衔铁转动时会压在齿槽间缘上，下颌链在下颌沟处收紧，项带压在项部上。","caracteristiques":"衔体以下的衔杆越长，在同样的缰绳张力下效果就越强。","precautions":"下颌链必须调好，缰绳也要用得非常温和。"},{"nom":"佩勒姆衔铁","court":"只有一根衔体，带衔杆、下颌链和两副缰绳。","fonctionnement":"系在上面的缰绳主要起水勒的作用；下面的缰绳则加上杠杆效应。","caracteristiques":"它把水勒衔铁和大勒衔铁的效果集中在一个衔铁上。","precautions":"如果只用一根缰绳（在两个环之间加一条连接带），精确度会下降。"},{"nom":"佩索阿衔铁","court":"一种有多个叠放衔环的水勒衔铁。","fonctionnement":"根据缰绳系在哪个环上，效果接近水勒，或者会加上杠杆作用。","caracteristiques":"选的环越低，杠杆效应就越明显。","precautions":"只适合手很稳的骑手，具体怎么调要和教练一起决定。"}]},{"titre":"大勒","texte":"大勒在马嘴里同时放两个衔铁：一个细的水勒衔铁，叫作小勒衔铁，以及一个带衔杆和下颌链的大勒衔铁，各配一副缰绳。","cartes":[{"nom":"大勒衔铁和小勒衔铁","court":"两个衔铁，四根缰绳。","fonctionnement":"小勒衔铁作用于嘴角，起抬头的作用；大勒衔铁则在齿槽间缘、下颌和项部加上杠杆效应。骑手分别控制每根缰绳的力度。","caracteristiques":"用于高水平盛装舞步和传统着装场合。用大勒骑乘是 Galop 7 的考核内容。","precautions":"需要独立的手、稳定的骑坐，以及一匹已经用水勒调教得很好的马。"}]}],"matieres":{"titre":"你知道吗？","texte":"衔铁有多种材质：不锈钢、能促进分泌唾液的铜或合金，以及更柔软的橡胶和合成材料。嘴里有一点唾液、会轻轻咀嚼的马，通常嘴是放松的。"}},"s3":{"num":"03","titre":"解剖与作用部位","intro":"衔铁放在一个很明确的位置：门齿和臼齿之间没有牙齿的地方。它作用于好几个部位，而这些部位的反应各不相同。","schemaTitre":"马头简化示意图","schemaNote":"教学示意图，比例已简化。","zones":[{"nom":"舌头","texte":"它承受很大一部分压力，尤其是使用直杆或双节衔铁时。"},{"nom":"齿槽间缘","texte":"下颌上门齿和臼齿之间没有牙齿的部分。那里的牙龈直接覆盖在骨头上：这是一个非常敏感的部位。"},{"nom":"嘴角和嘴唇","texte":"嘴的两角。水勒衔铁作用在这里，尤其是在抬头或使用开缰的时候。"},{"nom":"上颚","texte":"嘴的上部。单节衔铁折得太厉害时可能会碰到它。"},{"nom":"项部","texte":"使用杠杆衔铁时，项带会把压力传到头顶。"},{"nom":"下颌","texte":"带衔杆衔铁的下颌链放在下颌沟里，衔铁转动时就压在那里。"}],"mecaTitre":"三种作用方式","mecanismes":[{"nom":"直接压力","texte":"使用水勒衔铁时，缰绳的张力会沿着手拉的方向，作用到舌头、齿槽间缘和嘴角上。"},{"nom":"杠杆效应","texte":"有衔杆时，衔铁会转动：力量被放大，并分布到齿槽间缘、下颌和项部。"},{"nom":"侧向作用","texte":"固定衔环或颊杆压在开缰另一侧的脸颊上，帮助马转弯。"}]},"s4":{"num":"04","titre":"怎么选择衔铁？","intro":"没有绝对“好”的衔铁：只有适合某匹马、某个骑手、以及他们训练中某个阶段的衔铁。下面是你要和教练一起看的标准。","criteres":[{"nom":"马的嘴","texte":"嘴的宽度决定衔铁的尺寸。舌头厚或上颚低的马，常常需要更细的衔体或双节衔铁。"},{"nom":"它的敏感度","texte":"非常敏感的马，用稳定、温和的衔铁往往会更自在。"},{"nom":"它的调教水平","texte":"年轻马从简单的水勒衔铁开始。杠杆衔铁和大勒要等到以后，用在训练有素的马身上。"},{"nom":"项目","texte":"每个项目的规则都规定了比赛中允许使用的衔铁。一定要查看现行的马术协会规则。"},{"nom":"骑手的手","texte":"衔铁越强，就越需要一双稳定、柔和、并且独立于骑坐的手。"},{"nom":"调整与舒适","texte":"再好的衔铁，也只有尺寸合适、高度调整正确，才能好好发挥作用。"}],"important":{"titre":"教练的建议","texte":"更严厉的衔铁永远代替不了正确的调教。如果你的马拉扯、压衔或张嘴，先找原因：你的手、你的平衡、它是否放松、它的牙齿、装备的调整。只有在征求教练意见后才更换衔铁。"}},"s5":{"num":"05","titre":"调整与保养","intro":"衔铁选得再好，调得不对也会很快让马不舒服。养成每次骑乘前检查这些要点的习惯吧。","verifTitre":"上马前的检查","verifs":["宽度：衔铁在嘴的两侧各露出约半厘米，不勒紧嘴唇。","高度：使用水勒衔铁时，一般能在嘴角看到一两道小褶皱。没有褶皱，说明衔铁太低；褶皱很多，说明太高。","下颌链：平贴在下颌沟里；下颌链和下颌之间要能插进两根手指。","状态：没有锋利的棱角，衔环的孔和关节没有磨损，没有会夹肉的部件。","皮具：颊带、扣环和缰绳都柔软、状态良好。"],"entretienTitre":"骑乘之后","entretien":"一卸下马鞍，就在唾液和草渣干掉之前用清水冲洗衔铁。擦干、晾干，然后定期保养皮具。","erreurs":{"titre":"要避免的错误","points":["不看嘴角，就“随便”调整水勒衔铁的高度。","因为“马已经习惯了”，就继续用损坏的衔铁。","为了“刹车更灵”而把下颌链收紧。","骑乘后让脏衔铁就这样晾干。"]}},"s6":{"num":"06","titre":"特殊情况","intro":"在 Galop 5 阶段，你只需要认出它们并理解原理。是否使用要和教练一起决定。","cartes":[{"nom":"博谢衔铁","court":"一种水勒衔铁，多了一个固定在颊带上的小环。","detail":"衔铁悬挂在嘴里，非常稳定。适合经常玩衔铁的马。"},{"nom":"软质衔铁","court":"橡胶或合成材料制成。","detail":"柔和又轻便，适合敏感的嘴或年轻马。它们磨损更快：要检查有没有被咬坏或开裂。"},{"nom":"无衔笼头（hackamore）","court":"没有衔铁的勒。","detail":"它通过压在鼻梁、下颌和项部起作用，嘴里什么都没有。它本身并不是“更温和”的方案：调得不好，可能会非常严厉。"},{"nom":"鼻革","court":"它不是衔铁，但会改变衔铁的效果。","detail":"鼻革太紧会让马无法咀嚼，使衔接变硬。鼻革和鼻梁之间要能插进两根手指。"}]},"lateral":{"observerTitre":"观察一下","observer":"下次骑乘时，看看马的嘴：是闭着而且安静的吗？它在轻轻咀嚼吗？嘴角能看到一两道褶皱吗？放松的嘴往往说明马是放松的。","defiTitre":"骑手挑战","defi":"在你俱乐部的马具室里，找出三个不同的衔铁并说出它们的名字：衔环类型、衔体形状、直接作用还是杠杆作用。然后把你的答案给教练看。"},"videos":{"titre":"通过视频更好地理解","v1":"认识主要的衔铁种类","v2":"理解衔铁的不同效果","v3":"检查衔铁的调整","aVenir":"视频即将上线","tous":"查看全部视频库"},"quiz":{"titre":"测测你的知识","texte":"这节课学完了吗？检查一下你记住了什么。","bouton":"进入测验","bientot":"即将推出"}}};
